var e=JSON.parse(`[{"id":"ty-lo-gia-na","name":"Đức Phật Tỳ Lô Giá Na","summary":"Đức Phật Tỳ Lô Giá Na (Vairocana) là bậc Giáo Chủ biểu thị cho Thanh Tịnh Pháp Thân, bản thể giác ngộ sáng suốt chiếu khắp muôn phương vô lượng pháp giới. Ngài tiêu biểu cho Đại Nhật Như Lai, đại trí tuệ vô biên và cõi Hoa Tạng Trang Nghiêm thanh tịnh nhiệm mầu.","sections":[{"id":"biography","title":"Tiểu sử và cõi Hoa Tạng Thế Giới Hải","paragraphs":["Danh hiệu Tỳ Lô Giá Na trong tiếng Phạn là Vairocana, mang ý nghĩa là Biến Nhất Thiết Xứ hoặc Quang Minh Biến Chiếu, tức ánh sáng giác ngộ chiếu khắp cùng hư không pháp giới, không nơi nào không tới. Ngài là biểu tượng tối cao của Thanh Tịnh Pháp Thân Phật, bản thể thường trụ bất sinh bất diệt, vốn sẵn đủ nơi tự tính của tất cả muôn loài chúng sinh nhưng bị mây mờ vô minh ngăn che.","Theo Kinh Đại Phương Quảng Phật Hoa Nghiêm (phẩm Hoa Tạng Thế Giới thứ 5), Đức Phật Tỳ Lô Giá Na an ngự tại cõi Hoa Tạng Trang Nghiêm Thế Giới Hải. Cõi giới thù thắng ấy được trang nghiêm bởi muôn vàn hạnh nguyện và công đức tu nhân thuở quá khứ của Ngài: bên dưới có các tầng phong luân nâng đỡ biển nước hương thơm trang nghiêm bằng ngọc ma-ni; giữa biển nở đóa đại liên hoa rực rỡ mang tên Chủng Chủng Quang Minh Nhụy Hương Tràng; mặt đất bằng phẳng bằng kim cang bất hoại xen lẫn thất bảo, cây báu thành hàng và lưới châu ma-ni tỏa sáng vô tận.","Trong giáo lý Đại thừa về Tam Thân Phật viên mãn, Đức Phật Tỳ Lô Giá Na là Pháp thân thanh tịnh thường trụ; Đức Phật Lô Xá Na (Rocana) là Báo thân viên mãn muôn vạn công đức; và Đức Phật Thích Ca Mâu Ni (Śākyamuni) là Ứng hóa thân tùy duyên xuất hiện nơi cõi Ta Bà độ hóa chúng sinh. Ba thân tuy ba phương diện nhưng cùng đồng nhất trong một thể giác ngộ thanh tịnh tối hậu.","Trong giáo lý Mật Tông Chân Ngôn thừa dựa trên Đại Nhật Kinh và Kim Cang Đỉnh Kinh, Ngài được tôn xưng là Đại Nhật Như Lai (Mahāvairocana), vị Phật trung tâm của Kim Cang Giới và Thai Tạng Giới Mạn-đà-la, bắt ấn Trí Quyền biểu thị sự hợp nhất viên mãn giữa trí tuệ siêu việt và từ bi bình đẳng."],"notes":["Tài liệu căn bản về cõi Hoa Tạng y cứ Kinh Hoa Nghiêm (phẩm 5); giáo lý Chân Ngôn tông y cứ Đại Nhật Kinh (Đại Chính tạng T848)."]},{"id":"initial-vows","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Đại Phương Quảng Phật Hoa Nghiêm, phẩm Tỳ Lô Giá Na thứ 6, thuở quá khứ xa xưa cách đây vô lượng vô biên a-tăng-kỳ kiếp, tại thế giới Thắng Âm có vị Chuyển luân Thánh vương tên là Oai Quang, cai quản bốn đại châu thiên hạ bằng Chánh pháp. Vị vua ấy sinh được một người con trai đoan nghiêm xuất chúng tên là Thái tử Đại Oai Quang. Khi Đức Phật Câu Tô Ma Tô Mâu Ni giáng trần thành đạo, Thái tử cùng phụ vương đến chiêm ngưỡng dung nhan tướng hảo quang minh của Đức Thế Tôn, lắng nghe diệu âm chuyển pháp luân mà phát khởi Bồ-đề tâm sâu dày kiên cố.","Sau khi vua cha qua đời, Thái tử Đại Oai Quang nối ngôi Chuyển luân vương, đem trọn vẹn của báu thiên hạ cúng dường Tam Bảo, rồi dũng mãnh xả bỏ ngôi báu xuất gia tu hành, trải qua phụng sự vô lượng Đức Phật trong cõi Thắng Âm. Nhờ dốc lòng tu tập Ba-la-mật và nuôi lớn lòng đại bi không thoái chuyển qua trăm ngàn ức kiếp, Ngài đã viên mãn Bồ-đề tâm, chuyển hóa thân tâm thành tựu quả vị Pháp thân Tỳ Lô Giá Na biến chiếu khắp mười phương.","Trong Đại Nhật Kinh, nền tảng phát tâm tu tập của Ngài được tóm gọn qua ba câu tâm yếu thâm sâu: Lấy tâm Bồ-đề làm nhân, lấy lòng đại bi làm cội rễ, lấy phương tiện thiện xảo làm cứu cánh rốt ráo. Hành giả khi phát tâm tu học theo hạnh nguyện Tỳ Lô Giá Na trước hết phải tự soi rọi lại chính mình, nhận ra tự tính giác ngộ thanh tịnh sẵn có để mở lòng thương xót độ thoát muôn loài."],"notes":["Nhân duyên tiền thân Thái tử Đại Oai Quang trích Kinh Hoa Nghiêm phẩm 6 (Đại Chính tạng T279); ba câu tâm yếu trích Đại Nhật Kinh chương 1."]},{"id":"great-vows","title":"Đại nguyện","paragraphs":["Trong Kinh Đại Phương Quảng Phật Hoa Nghiêm, phẩm Tỳ Lô Giá Na, Đức Phật Tỳ Lô Giá Na là biểu thị cho Thanh Tịnh Pháp Thân thường trụ khắp pháp giới mười phương. Bản nguyện vô lượng của Ngài được khắc họa qua việc nghiêm tịnh tất cả các cõi Phật trong khắp mười phương hư không giới, khiến cho khắp pháp giới chúng sinh đều thâm nhập Phật trí, thấy rõ muôn pháp duy tâm và đồng chứng Pháp thân thanh tịnh vô ngại.","Đại nguyện khai mở Tự Tính Bồ Đề (theo Đại Nhật Kinh): Nguyện cho tất cả chúng sinh nhận ra tự tính giác ngộ vốn sẵn đủ nơi chính mình, vượt qua mọi vọng tưởng chấp trước nhị nguyên, thể nhập vào cảnh giới đại quang minh thanh tịnh vô biên, đoạn dứt sinh tử phiền não và đồng thành tựu quả vị Nhất Thiết Chủng Trí như chư Phật mười phương.","Kinh Hoa Nghiêm dùng hình ảnh lưới báu của trời Đế Thích để diễn tả cảnh giới Pháp thân Tỳ Lô Giá Na: mỗi viên ngọc phản chiếu tất cả viên ngọc khác, một hạt bụi chứa trọn mười phương cõi nước. Giáo lý ấy được chư Tổ Hoa Nghiêm hệ thống thành Thập Huyền Môn và pháp giới trùng trùng duyên khởi, nhắc người tu học rằng mọi việc thiện nhỏ đều lan tỏa khắp pháp giới.","Kinh Hoa Nghiêm, phẩm Dạ Ma Cung Kệ Tán, có câu: tâm, Phật và chúng sinh, cả ba không sai khác. Hướng về Đức Tỳ Lô Giá Na vì thế không phải cầu một đấng ở ngoài, mà là quay về soi sáng tâm mình, kính trọng Phật tính nơi mọi người và sống hòa hợp với muôn loài."],"notes":["Khảo sát theo Kinh Hoa Nghiêm phẩm 5-6 và Đại Nhật Kinh; nhấn mạnh tinh thần Pháp thân thanh tịnh biến chiếu."]},{"id":"name-benefits","title":"Công đức niệm danh hiệu","paragraphs":["Trong nghi thức truyền thống tôn kính Tam thân Phật (ba phương diện của Phật gồm Pháp thân, Báo thân và Ứng thân), người tu học thường đảnh lễ câu: Nam Mô Thanh Tịnh Pháp Thân Tỳ Lô Giá Na Phật. Một số chùa quen đọc là Tỳ Lô Xá Na; hai cách đọc đều phiên âm từ danh hiệu Vairocana và cùng chỉ một Đức Phật. Riêng danh hiệu Lô Xá Na (Rocana) trong Kinh Phạm Võng thường được hiểu là Báo thân viên mãn. Niệm danh hiệu Ngài là hướng tâm về bản thể thanh tịnh vốn có nơi tự tâm, gạn lọc những xao động và nhận biết tánh giác sáng suốt bình đẳng nơi mọi người.","Theo Kinh Hoa Nghiêm, phẩm Tỳ Lô Giá Na, nhờ nhân duyên thấy ánh sáng Phật, chí thành lễ bái và lắng nghe chánh pháp mà người tu học gieo trồng căn lành sâu dày, từng bước thâm nhập cảnh giới thanh tịnh. Việc xưng niệm danh hiệu cần gắn liền với công phu chuyển hóa: giữ gìn giới hạnh, soi rọi tâm ý và nuôi dưỡng lòng từ bi, không dừng lại ở việc đọc tụng nơi cửa miệng.","Trong thời khóa hằng ngày, người tu học có thể xưng niệm danh hiệu Ngài trước khi tụng Kinh Hoa Nghiêm hoặc phẩm Phổ Hiền Hạnh Nguyện, rồi ngồi yên giây lát quán chiếu ánh sáng trí tuệ chiếu khắp mười phương, nguyện cho mình và mọi người đều nhận ra tự tính thanh tịnh."],"notes":["Theo nghi thức truyền thống Bắc truyền và Kinh Hoa Nghiêm phẩm Tỳ Lô Giá Na."]},{"id":"mantras","title":"Thần chú và đà-la-ni","paragraphs":["Pháp môn gắn liền với Đức Phật Tỳ Lô Giá Na có Quang Minh chân ngôn (Kōmyō Shingon), một bài chú quan trọng trong truyền thống Chân Ngôn tông Nhật Bản và Mật tạng Bắc truyền. Bản phiên tự Phạn văn thường được ghi là: oṃ amogha vairocana mahāmudrā maṇipadma jvāla pravarttaya hūṃ.","Tại Việt Nam, Quang Minh Chân Ngôn thường được xưng tụng theo âm Hán-Việt truyền thống: “Án a mô già, vĩ lô giá nẵng, ma ha mẫu nại-ra, ma nỉ, bát nạp-mạ, nhập-phược-la, bát-ra vạt-đa-dã hồng”.","Công dụng của Quang Minh Chân Ngôn theo kinh điển: Năng lực đại quang minh của Đức Phật Tỳ Lô Giá Na chiếu soi phá tan bóng tối vô minh và nghiệp chướng sâu dày nhiều đời; người chí thành trì tụng được thân tâm an lạc thanh tịnh, gia hộ tiêu trừ tai chướng ách nạn, giải thoát các linh hồn khỏi cảnh giới đọa lạc tăm tối và dẫn dắt hành giả hướng về cõi Phật thanh tịnh.","Trong tạng kinh chữ Hán, văn bản liên hệ trực tiếp với pháp này là Bất Không Quyến Sách Tỳ Lô Giá Na Phật Đại Quán Đảnh Quang Chân Ngôn, Đại Chính tạng số 1002. Kinh dạy rằng chú này như ánh mặt trời xua tan đêm tối, có công năng cứu độ người nhiều nghiệp chướng nếu biết ăn năn sám hối.","Khi thực hành trong thời khóa cư sĩ của Chân Ngôn tông, Quang Minh chân ngôn được đặt trong mạch tu tập trọn vẹn gồm quy y, sám hối, phát bồ-đề tâm và hồi hướng công đức; không nên xem đây là một câu thần chú đọc lên để cầu lợi ích riêng tư mà thiếu sự chuyển hóa thân tâm."],"notes":["Đối chiếu Bất Không Quyến Sách Tỳ Lô Giá Na Phật Đại Quán Đảnh Quang Chân Ngôn (T1002)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Pháp rải cát gia trì (Thổ sa gia trì) được chép ngay trong Bất Không Quyến Sách Tỳ Lô Giá Na Phật Đại Quán Đảnh Quang Chân Ngôn: nếu có người tạo nhiều tội nặng, sau khi mất đọa vào đường ác, thân quyến lấy cát sạch, trì Quang Minh Chân Ngôn một trăm lẻ tám biến rồi rải lên thi hài hoặc mộ phần, thì nhờ ánh sáng của chân ngôn chiếu đến, người mất được lìa thân khổ, sinh về cõi lành. Lời kinh nhấn mạnh năng lực của chân ngôn đi cùng tâm thương xót và hồi hướng của người còn sống.","Tại Nhật Bản thời Kamakura, Thượng nhân Minh Huệ (Myōe, 1173–1232), trụ trì chùa Cao Sơn (Kōzan-ji) ở Toganoo, là người hết lòng hoằng dương pháp này. Ngài soạn sách Quang Minh Chân Ngôn Thổ Sa Khuyến Tín Ký, khuyên hàng cư sĩ trì chân ngôn để cầu siêu cho thân nhân, rải cát gia trì cho người quá vãng. Nhờ công hạnh của ngài, Quang Minh Chân Ngôn trở thành thời khóa cầu siêu phổ biến trong các chùa Chân Ngôn tông và vẫn được tụng đọc đến ngày nay.","Theo Tống Cao Tăng Truyện (quyển 5), khi Tổ thứ ba Hoa Nghiêm tông là Đại sư Pháp Tạng (Hiền Thủ Quốc Sư) giảng bộ Kinh Hoa Nghiêm cho Võ Tắc Thiên, nhà vua còn mơ hồ trước nghĩa lý trùng trùng vô tận của Pháp thân Tỳ Lô Giá Na. Ngài Pháp Tạng bèn đặt mười mặt gương ở tám phương cùng trên dưới đối diện nhau, ở giữa đặt một tôn tượng Phật và thắp một ngọn đuốc chiếu sáng. Ánh sáng và hình tượng phản chiếu giao thoa vô tận trong từng mặt gương, giúp người học thấu rõ cảnh giới trùng trùng duyên khởi của Hoa Tạng Thế Giới."],"notes":["Pháp rải cát đối chiếu Bất Không Quyến Sách Tỳ Lô Giá Na Phật Đại Quán Đảnh Quang Chân Ngôn (T1002); hành trạng Thượng nhân Minh Huệ đối chiếu Quang Minh Chân Ngôn Thổ Sa Khuyến Tín Ký."]}],"references":["Kinh Hoa Nghiêm, Đại Chính tạng số 279, phẩm 5: Hoa Tạng Thế Giới và phẩm 6: Tỳ Lô Giá Na.","The Vairocanābhisaṃbodhi Sutra (Kinh Đại Nhật), Đại Chính tạng số 848, Rolf W. Giebel dịch, BDK, 2005.","Bất Không Quyến Sách Tỳ Lô Giá Na Phật Đại Quán Đảnh Quang Chân Ngôn, Đại Chính tạng số 1002, một quyển — Bất Không dịch.","Nghi lễ Chân Ngôn tông: Koyasan Shingon Lay Service Book, mục Kōmyō Shingon.","Quang Minh Chân Ngôn Thổ Sa Khuyến Tín Ký — trước tác của Thượng nhân Minh Huệ (Myōe), chùa Cao Sơn (Kōzan-ji).","Tống Cao Tăng Truyện, quyển 5: truyện Pháp Tạng — Tán Ninh soạn, Đại Chính tạng tập 50, số 2061."]},{"id":"a-di-da","name":"Đức Phật A Di Đà","summary":"Đức Phật A Di Đà là giáo chủ cõi Cực Lạc ở phương Tây, biểu trưng cho ánh sáng trí tuệ vô lượng và thọ mạng vô lượng. Ngài nổi bật với bốn mươi tám đại nguyện thiết lập cõi nước thanh tịnh và tiếp dẫn chúng sinh biết tin sâu, phát nguyện, tu tập hướng về giác ngộ.","sections":[{"id":"tieu-su","title":"Tiểu sử và cõi Tây Phương Cực Lạc","paragraphs":["Theo Kinh A Di Đà và Kinh Vô Lượng Thọ, danh hiệu của Đức Phật A Di Đà mang hai ý nghĩa sâu sắc: Vô Lượng Quang (Amitābha) nghĩa là ánh sáng trí tuệ vô lượng vô biên chiếu khắp mười phương cõi nước không hề bị ngăn ngại, và Vô Lượng Thọ (Amitāyus) nghĩa là thọ mạng vô lượng vô biên cùng thọ mạng của hàng thánh chúng tại cõi ấy trải qua vô số kiếp không thể tính đếm. Tiền thân của Ngài là Tỳ-kheo Pháp Tạng, phát 48 đại nguyện thanh tịnh xây dựng cõi Phật trang nghiêm. Ngài là bậc Giáo chủ của cõi Tây Phương Cực Lạc, cách cõi Ta Bà mười muôn ức cõi Phật.","Trong Kinh Vô Lượng Thọ và Quán Vô Lượng Thọ, cõi Tây Phương Cực Lạc được miêu tả là một thế giới hoàn toàn thanh tịnh và trang nghiêm: không có ba đường ác (địa ngục, ngạ quỷ, súc sinh), mặt đất bằng vàng ròng bảy báu, cây báu thành hàng giăng lưới ngọc, gió thoảng lay động phát ra tiếng pháp vi diệu nhiệm mầu. Nơi ấy có ao thất bảo chứa đầy nước tám công đức thanh mát, trong ao nở hoa sen báu lớn như bánh xe với đủ sắc màu quang minh rực rỡ: hoa sen xanh ánh sáng xanh, hoa sen vàng ánh sáng vàng, hoa sen đỏ ánh sáng đỏ, hoa sen trắng ánh sáng trắng, vi diệu tỏa hương thơm thanh khiết.","Chúng sinh sinh về cõi Cực Lạc đều hóa sinh từ trong hoa sen báu, thân tướng đoan nghiêm đẹp đẽ như nhau, không còn phân biệt sang hèn hay chịu nỗi khổ sinh, già, bệnh, chết; ngày ngày nghe chim báu hót tiếng pháp âm diễn nói Ngũ căn, Ngũ lực, Thất Bồ-đề phần, Bát Thánh đạo phần, tự nhiên khởi lòng niệm Phật, niệm Pháp, niệm Tăng, trọn đời an trú nơi cảnh giới Bất thoái chuyển cho đến khi viên thành Phật quả.","Đức Phật A Di Đà cùng hai vị Đại Bồ Tát thượng thủ là Quán Thế Âm và Đại Thế Chí hợp thành Tây Phương Tam Thánh, luôn phóng ánh từ quang tiếp dẫn mười phương chúng sinh hữu duyên hướng về bến giác giải thoát."],"notes":["Miêu tả cõi Tây Phương Cực Lạc y cứ Kinh A Di Đà (Đại Chính tạng T366) và Kinh Vô Lượng Thọ (T360)."]},{"id":"phat-nguyen-ban-dau","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Vô Lượng Thọ, quyển thượng, vào thuở quá khứ xa xưa vô lượng kiếp về trước, có Đức Phật Thế Tự Tại Vương giáng trần giáo hóa muôn loài. Bấy giờ có một vị Quốc vương tên là Kiều Thi Ca nghe Phật thuyết pháp bèn khởi lòng hoan hỷ kính tin sâu sắc, phát tâm Bồ-đề vô thượng, từ bỏ ngai vàng xuất gia làm một vị Sa-môn tên là Pháp Tạng (Dharmākara). Tỳ-kheo Pháp Tạng tài trí siêu việt, dõng mãnh tinh tấn, chí nguyện hơn đời.","Tỳ-kheo Pháp Tạng đối trước Đức Phật Thế Tự Tại Vương đảnh lễ phát đại thệ nguyện muốn xây dựng một cõi Phật thanh tịnh thù thắng nhất trong mười phương. Đức Phật Thế Tự Tại Vương nhìn thấu tâm nguyện vĩ đại ấy liền vì ngài mà thị hiện hai trăm mười ức cõi Phật trang nghiêm sai biệt. Sau khi quán sát tường tận trong suốt năm kiếp thiền định lắng sâu, Tỳ-kheo Pháp Tạng chọn lọc tất cả những nét trang nghiêm vi diệu nhất của các cõi Phật, rồi đối trước Thế Tôn dõng mãnh tuyên thuyết Bốn mươi tám đại nguyện chấn động tam thiên đại thiên thế giới. Ngài thề rằng nếu bốn mươi tám nguyện ấy không viên mãn thì quyết không nhận lấy quả vị Chánh Giác.","Sau khi tuyên thuyết bốn mươi tám đại nguyện, Tỳ-kheo Pháp Tạng trải qua vô lượng kiếp tu tập lục độ vạn hạnh, tích lũy công đức rộng lớn không biết mệt mỏi, trang nghiêm thanh tịnh hai trăm mười ức cõi nước để thành tựu thế giới Tây Phương Cực Lạc. Kinh Vô Lượng Thọ dạy rằng chính từ tâm đại bi không bỏ sót một chúng sinh nào ấy mà danh hiệu Nam Mô A Di Đà Phật vang vọng khắp mười phương, làm điểm tựa vững chắc cho người cầu giải thoát."],"notes":["Sự tích Tỳ-kheo Pháp Tạng trích Phật Thuyết Vô Lượng Thọ Kinh (bản dịch Khang Tăng Khải, Đại Chính tạng T360)."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Nguyên văn phẩm thứ sáu: Phát Đại Thệ Nguyện, trong Phật Thuyết Đại Thừa Vô Lượng Thọ Trang Nghiêm Thanh Tịnh Bình Đẳng Giác Kinh. Hạ Liên Cư hội tập; HT Thích Đức Niệm và cư sĩ Minh Chánh Việt dịch. Theo bản Đạo Tràng Liên Hoa, phiên bản 1.5, trang in 19–32. Giữ nguyên 24 nhóm kinh văn cùng các nhãn 1–48 trong bản này; không ghép với thứ tự nguyện của bản dịch khác.","Pháp Tạng bạch rằng: “Bạch đức Thế Tôn! Cúi xin đức Thế Tôn thương xót nghe cho:","● Con nếu chứng được Vô thượng Bồ Đề, thành Đẳng chánh giác rồi, cõi nước của Phật ở có đầy đủ vô lượng công đức trang nghiêm không thể nghĩ bàn, không có địa ngục, ngạ quỷ, súc sanh các loại. Nếu có chúng sanh trong ba đường ác cho đến từ địa ngục sanh về cõi con, thọ giáo pháp của con, tất thành A Nậu Đa La Tam Miệu Tam Bồ Đề, không đọa lại ba đường ác nữa. Được như vậy con mới làm Phật. Nếu không được như nguyện, thề không thành Vô thượng Chánh giác. [1. Nguyện trong nước không có ác đạo. 2. Nguyện không đọa ba đường ác.]","● Khi con thành Phật, các chúng sanh ở mười phương thế giới sanh về cõi con, thân tướng sắc vàng ròng, đủ ba mươi hai tướng tốt, đủ tướng đại trượng phu, đoan nghiêm chánh trực, tất cả đồng một dung nhan, nếu có tốt xấu, hình thể sai biệt, thề không thành Chánh giác. [3. Nguyện thân có sắc vàng ròng. 4. Nguyện có ba mươi hai tướng tốt. 5. Nguyện cho thân không sai biệt.]","● Khi con thành Phật, các chúng sanh sanh về cõi con, biết rõ vô lượng kiếp trước. Thấy rõ những việc thiện ác đã làm. Nghe rõ sự việc khắp mười phương cả ba đời khứ lai hiện tại. Nếu không được như nguyện, thề không thành Chánh giác. [6. Nguyện có túc mạng thông. 7. Nguyện có thiên nhãn thông. 8. Nguyện có thiên nhĩ thông.]","● Khi con thành Phật, nếu có chúng sanh sanh về cõi con đều được tha tâm trí thông, biết được tâm niệm của chúng sanh xa cách trăm ngàn vạn ức cõi Phật, nếu không như vậy thề không thành Chánh giác. [9. Nguyện có tha tâm thông.]","● Khi con thành Phật, nếu có chúng sanh sanh về cõi con, được thần thông tự tại Ba la mật đa. Trong khoảnh khắc nếu không đi khắp trăm ngàn vạn ức cõi Phật để cúng dường, thề không thành Chánh giác. [10. Nguyện được thần túc thông. 11. Nguyện giáp khắp cúng dường chư Phật.]","● Khi con thành Phật, nếu có chúng sanh sanh về cõi con, xa lìa tâm phân biệt, các căn tịch tịnh, nếu chẳng an trụ trong định tụ đến đại Niết bàn, thề không thành Chánh giác. [12. Nguyện quyết định thành bậc Chánh giác.]","● Khi con thành Phật, có quang minh vô lượng chiếu khắp mười phương chư Phật, gấp ngàn vạn ức lần ánh sáng của nhựt nguyệt. Nếu có chúng sanh nào thấy hay chạm được ánh sáng của con thì được an lạc, khởi từ tâm làm điều lành, sau sanh về nước con. Nếu không được như vậy, thề không thành Chánh giác. [13. Nguyện ánh sáng vô lượng. 14. Nguyện chạm Quang minh được an lạc.]","● Khi con thành Phật sống lâu vô lượng. Vô số Thanh văn và trời người trong nước cũng có thọ mạng vô lượng. Giả như chúng sanh ở ba ngàn thế giới thành bậc Duyên giác trải qua trăm ngàn kiếp để tính đếm, nếu biết được số lượng ấy, thề không thành Chánh giác. [15. Nguyện thọ mạng vô lượng. 16. Nguyện Thanh văn vô số.]","● Khi con thành Phật, vô số chư Phật trong vô lượng cõi ở mười phương thế giới, nếu không khen ngợi tên con, nói công đức quốc độ của con, thề không thành Chánh giác. [17. Nguyện được chư Phật xưng tán.]","● Khi con thành Phật, chúng sanh trong mười phương nghe danh hiệu con, hết lòng tin tưởng, nếu có điều lành nào, tâm tâm hồi hướng nguyện sanh về cõi nước con, cho đến mười niệm, nếu không được vãng sanh, thề không thành Chánh giác. Ngoại trừ những kẻ phạm tội ngũ nghịch, phỉ báng chánh pháp. [18. Nguyện mười niệm tất vãng sanh.]","● Khi con thành Phật, chúng sanh khắp mười phương nghe danh hiệu con, phát tâm Bồ đề, tu các công hạnh, hành sáu Ba la mật, kiên cố không lùi, lại đem các căn lành hồi hướng nguyện sanh về cõi nước con, một lòng nghĩ đến con ngày đêm không dứt, đến khi mạng chung, con cùng Thánh chúng Bồ Tát liền đến tiếp đón, khoảnh khắc sanh về cõi con được Bất thối chuyển. Nếu không được như nguyện, thề không thành Chánh giác. [19. Nguyện nghe danh phát tâm. 20. Nguyện lâm chung tiếp dẫn.]","● Khi con thành Phật, chúng sanh trong mười phương nghe danh hiệu con, nhớ nghĩ nước con, phát tâm Bồ đề kiên cố không thối lui, trồng các căn lành, hết lòng hồi hướng sanh về Cực Lạc, đều được toại ý; nếu có ác nghiệp đời trước, nghe danh hiệu con hết lòng sám hối, làm các điều lành, lại trì kinh giữ giới nguyện sanh về nước con, mạng chung không lạc vào ba đường ác, liền sanh về nước con. Nếu không được như vậy, thề không thành Chánh giác. [21. Nguyện sám hối được vãng sanh.]","● Khi con thành Phật, nước con không có phụ nữ. Nếu có nữ nhơn nào nghe danh hiệu con, thanh tịnh tin tưởng, phát tâm Bồ đề, chán ghét nữ thân, mạng chung liền hóa thân nam tử sanh về nước con. Các loại chúng sanh ở thế giới mười phương, sanh về nước con đều hóa sanh trong hoa sen thất bảo. Nếu không được như vậy, thề không thành Chánh giác. [22. Nguyện trong nước không có người nữ. 23. Nguyện nhàm chán thân nữ, chuyển thân nam. 24. Nguyện Liên hoa hóa sanh.]","● Khi con thành Phật, chúng sanh khắp mười phương nghe danh hiệu con vui mừng tin tưởng, lễ bái qui mạng, đem tâm thanh tịnh tu hạnh Bồ tát, chư Thiên và người đời hết lòng tôn kính. Nếu nghe danh hiệu con, sau khi mạng chung được sanh vào nhà tôn quý, các căn đầy đủ. Thường tu thù thắng phạm hạnh. Nếu không được như vậy, thề không thành Chánh giác. [25. Nguyện Thiên Nhân lễ kính. 26. Nguyện nghe danh hiệu được phước. 27. Nguyện tu thù thắng hạnh.]","● Khi con thành Phật, nước con không có tên ba đường ác. Chúng sanh sanh vào nước con đều nhất tâm trụ vào chánh định. Không còn nhiệt não, tâm được mát mẻ, hưởng thọ an lạc, như Tỳ kheo lậu tận. Nếu còn khởi tưởng niệm tham đắm thân sau, thề không thành Chánh giác. [28. Nguyện nước không có tên “Bất thiện”. 29. Nguyện trụ Chánh định tụ. 30. Nguyện vui như Tỳ kheo dứt sạch các lậu. 31. Nguyện không tham chấp thân.]","● Khi con thành Phật, chúng sanh sanh vào nước con, được vô lượng căn lành, thân thể vững chắc như kim cang bất hoại, thân mình đều có hào quang chiếu sáng. Thành tựu hết thảy trí huệ, biện tài không cùng tận. Rộng nói các pháp bí yếu, giảng kinh thuyết pháp, tiếng như chuông vang. Nếu không được như vậy, thề không thành Chánh giác. [32. Nguyện được Na la diên thân. 33. Nguyện Quang minh trí huệ biện tài. 34. Nguyện khéo nói pháp yếu.]","● Khi con thành Phật, chúng sanh sanh vào nước con quyết chắc đến bậc Nhất Sanh Bổ Xứ. Trừ khi phát nguyện rộng lớn trở lại độ sanh, giáo hóa hữu tình, khuyến phát tín tâm, tu hạnh Bồ tát, hành nguyện Phổ Hiền, tuy sanh vào thế giới khác hằng lìa ác thú, hoặc thích thuyết pháp, nghe pháp, hay hiện thần túc, tùy ý tu tập thảy đều viên mãn. Nếu không được như vậy, thề không thành Chánh giác. [35. Nguyện nhất sanh bổ xứ. 36. Nguyện giáo hóa tùy ý.]","● Khi con thành Phật, chúng sanh sanh vào nước con, nếu muốn ăn uống, y phục hay các đồ cần dùng tùy ý liền đến. Nếu khởi niệm cúng dường mười phương chư Phật, liền được mãn nguyện. Nếu không được như vậy, thề không thành Chánh giác. [37. Nguyện y thực tự đến. 38. Nguyện ứng niệm thọ cúng.]","● Khi con thành Phật, vạn vật trong cõi nước con đều trang nghiêm thanh tịnh sáng chói, hình sắc thù thắng vi diệu không thể tả xiết, dù có thiên nhãn cũng không thể diễn tả hết vẻ đẹp về hình sắc, hình tướng lộng lẫy và số lượng chúng sanh ở đó v.v... Nếu không được như vậy, thề không thành Chánh giác. [39. Nguyện trang nghiêm vô tận.]","● Khi con thành Phật, vô lượng cây cảnh trong cõi nước con cao trăm ngàn do tuần. Cây làm đạo tràng cao bốn trăm vạn dặm. Các bậc Bồ Tát trung phẩm cũng có thể biết rõ. Nếu muốn thấy các cõi thanh tịnh trang nghiêm của chư Phật, tuy ở nơi cây báu cũng được thấy rõ vạn tượng như xem trong gương. Nếu không được như vậy, thề không thành Chánh giác. [40. Nguyện có vô lượng cây sắc báu. 41. Nguyện cây hiện cõi Phật.]","● Khi con thành Phật, cõi nước rộng rãi nghiêm tịnh, sáng chói như gương, chiếu khắp vô lượng vô số bất khả tư nghì thế giới chư Phật khắp mười phương, chúng sanh thấy rồi sanh tâm hi hữu. Nếu không được như vậy, thề không thành Chánh giác. [42. Nguyện chiếu suốt mười phương.]","● Khi con thành Phật, cùng tột dưới đất, trên đến hư không, tất cả vạn vật cung điện, lầu các, ao nước, hoa cây v.v... trong nước đều do vô lượng bảo hương hiệp thành, hương thơm xông khắp mười phương thế giới, chúng sanh ngửi được đều tu Phật hạnh. Nếu không được như vậy, thề không thành Chánh giác. [43. Nguyện hương báu xông khắp.]","● Khi con thành Phật, các bậc Bồ Tát trong mười phương cõi Phật, nghe danh con rồi đều được thanh tịnh giải thoát, Phổ đẳng Tam muội, các môn Tổng trì vào Tam ma địa cho đến thành Phật. Tuy ở trong định thường cúng dường vô lượng vô biên chư Phật vẫn không mất định ý. Nếu không được như vậy, thề không thành Chánh giác. [44. Nguyện phổ đẳng tam muội. 45. Nguyện trong định cúng Phật.]","● Khi con thành Phật, các bậc Bồ Tát ở thế giới khác nghe danh con rồi chứng Ly sanh pháp, được các môn Đà la ni. Thanh tịnh hoan hỷ, an trụ trong thể tướng bình đẳng, tu Bồ Tát hạnh, đầy đủ trí đức mà không chứng được ba nhẫn, nơi Phật pháp mà không chứng được bậc Bất thối chuyển, thề không thành Chánh giác”. [46. Nguyện được môn Tổng trì. 47. Nguyện nghe danh đặng pháp nhẫn. 48. Nguyện hiện chứng quả bất thối chuyển.]"],"notes":[]},{"id":"loi-ich","title":"Công đức niệm danh hiệu","paragraphs":["Theo Kinh A Di Đà, người thiện nam hay thiện nữ nào nghe nói đến Đức Phật A Di Đà rồi chí tâm chấp trì danh hiệu của Ngài, hoặc một ngày, hai ngày, cho đến bảy ngày với tâm nhất tâm bất loạn không xao động, thì khi người ấy lâm chung, Đức Phật A Di Đà cùng hàng thánh chúng sẽ hiện thân trước mặt. Nhờ tha lực tiếp dẫn của Phật và tự tâm thanh tịnh, hành giả tâm không điên đảo, liền được vãng sinh về cõi Cực Lạc phương Tây.","Trong Kinh Quán Vô Lượng Thọ, pháp môn niệm Phật được mở rộng cho tất cả chúng sinh thông qua chín phẩm sen (Tam bối Cửu phẩm). Ngay cả kẻ tạo nhiều tội lỗi nơi thế gian, lúc lâm chung đối diện với cảnh khổ hỏa ngục, nếu gặp được thiện tri thức khai thị và chí thành xưng niệm mười niệm “Nam Mô A Di Đà Phật”, thì nhờ sức đại nguyện của Phật mà mỗi niệm tiêu trừ tội nặng trong tám mươi ức kiếp sinh tử, hoa sen báu hiện tiền đón rước sinh về cõi lành.","Niệm Phật trong pháp môn Tịnh Độ đòi hỏi đầy đủ ba yếu tố Tín, Hạnh và Nguyện ví như chiếc đỉnh ba chân: Tín là tin sâu có cõi Cực Lạc và bản nguyện tiếp dẫn của Phật A Di Đà; Nguyện là tha thiết mong muốn lìa cõi Ta Bà khổ đau để vãng sinh về cõi Tịnh độ; Hạnh là chuyên cần niệm Phật, giữ tâm thanh tịnh, làm các việc lành hồi hướng. Ba điều ấy hòa quyện giúp hành giả nuôi dưỡng định lực và an lạc ngay trong đời sống hiện tại.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô A Di Đà Phật”."],"notes":["Dẫn kinh A Di Đà, kinh Quán Vô Lượng Thọ và giáo lý Tín-Nguyện-Hạnh của Tịnh Độ tông."]},{"id":"chan-ngon-va-da-la-ni-lien-he","title":"Thần chú và đà-la-ni","paragraphs":["Trong thực hành Tịnh độ, bên cạnh câu xưng niệm danh hiệu Nam mô A Di Đà Phật, người tu học còn trì tụng Bạt nhất thiết nghiệp chướng căn bản đắc sinh Tịnh độ thần chú, thường được gọi tắt là Vãng sinh quyết định chân ngôn hay Chú Vãng Sinh.","Bài chú được trì tụng theo âm Hán-Việt truyền thống: “Nam-mô a di đa bà dạ, Đa tha già đa dạ, Đa địa dạ tha, A di rị đô bà tỳ, A di rị đa tất đam bà tỳ, A di rị đa tỳ ca lan đế, A di rị đa tỳ ca lan đa, Già di nị, Già già na, Chỉ đa ca lệ, Sa-bà-ha”.","Công dụng của Chú Vãng Sinh theo kinh điển: Có năng lực diệt trừ tận gốc rễ tất cả các nghiệp chướng tội lỗi sâu dày tích lũy từ vô lượng kiếp trước; người chí thành thọ trì được Đức Phật A Di Đà thường trụ trên đảnh đầu âm thầm bảo hộ, hiện đời thân tâm an lạc không bị oan gia tà ma quấy nhiễu, lâm chung tiêu diêu tự tại vãng sinh Cực Lạc.","Trong Tạng kinh chữ Hán, văn bản này được ghi lại dưới mã số Đại Chính tạng 368. Chú giải truyền thống khuyên người thực hành súc miệng, giữ thân tâm thanh tịnh và phát tâm bồ-đề trước khi trì chú, không nên xem việc đọc chú như một phương tiện thuần túy hình thức.","Việc trì tụng Chú Vãng Sinh hỗ trợ tâm định tĩnh và củng cố niềm tin nơi bản nguyện tiếp dẫn của Đức Phật A Di Đà; công phu ấy chỉ thực sự phát huy trọn vẹn khi hành giả kết hợp với việc giữ gìn năm giới, sống hướng thiện và nuôi dưỡng tâm từ bi."],"notes":["Đối chiếu Bạt nhất thiết nghiệp chướng căn bản đắc sinh Tịnh độ thần chú (T368)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích người làm nghề mổ gà Trương Chung Quỳ niệm Phật thoát khỏi hỏa ngục được ghi chép trong Tịnh Độ Thánh Hiền Lục (quyển 8) và Vãng Sanh Tập: Trương Chung Quỳ sống tại Trường An vào thời nhà Đường, cả đời mưu sinh bằng nghề mổ gà bán thịt, sát hại vô số sinh linh không biết gớm tay. Đến khi lâm bệnh nặng sắp qua đời, thần thức Chung Quỳ hoảng loạn nhìn thấy vô số người thân người đầu gà với chiếc mỏ sắt sắc nhọn xông đến mổ túi bụi vào hai mắt, miệng mũi và toàn thân, máu me đầm đìa, đau đớn kêu thét kinh hoàng, lăn lộn dưới đất cầu cứu. Người vợ trông thấy cảnh tượng hãi hùng liền vội vã chạy đi thỉnh một vị Tăng tại chùa phụ cận đến giải nguy. Vị Tăng đến nơi thấy tình cảnh khẩn cấp bèn lớn tiếng bảo: “Nghiệp báo sát sinh của thí chủ nay đã hiện tiền, hỏa ngục đang chờ đón; trong tam giới chỉ duy nhất oai đức đại bi vô lượng của Đức Phật A Di Đà mới có thể cứu vớt được ngươi mà thôi. Ngươi hãy mau chí tâm gào khóc xưng niệm danh hiệu Ngài để cầu vãng sinh!”. Chung Quỳ tay run rẩy cầm nén hương, toàn thân run bắn vì sợ hãi tột cùng, dùng hết tàn lực còn lại vừa khóc lóc thảm thiết vừa gào lớn: “Nam mô A Di Đà Phật! Nam mô A Di Đà Phật!”. Niệm được vài mươi câu với tâm chí thành phát khởi từ tận cùng nỗi sợ hãi địa ngục, Chung Quỳ bỗng nhiên mở to mắt, nét mặt rạng rỡ thở phào bảo người nhà: “Đàn gà mổ mắt đã biến mất rồi! Trên không trung có một vị Phật thân sắc vàng rực rỡ từ phương Tây bay đến, phóng ra luồng ánh sáng êm dịu bao trùm lấy con, trên đài sen báu Ngài đưa cánh tay vàng tiếp dẫn con đi!”. Nói xong lời ấy, Chung Quỳ an nhiên nhắm mắt trút hơi thở cuối cùng trong tư thế đoan nghiêm, nét mặt thanh thản mỉm cười, để lại niềm kính tín sâu xa cho muôn người chứng kiến.","Sự tích Sơ Tổ Tịnh Độ Tông Huệ Viễn Đại Sư ba lần thấy Phật thọ ký được ghi trong Lương Cao Tăng Truyện (quyển 6): Vào thời Đông Tấn, ngài Huệ Viễn dựng chùa Đông Lâm trên núi Lô Sơn, kết hợp cùng một trăm hai mươi ba vị danh tăng và cư sĩ kiệt xuất lập nên Bạch Liên Xã, ngày đêm chuyên tâm tu niệm Phật Tam Muội cầu sinh Cực Lạc. Trong suốt ba mươi năm kiên trì tịnh nghiệp nơi Lô Sơn, chân không bước ra khỏi ngõ Hổ Khê, ngài từng ba lần trong lúc định quán thâm sâu đã tận mắt chiêm ngưỡng thân tướng trang nghiêm của Đức Phật A Di Đà phóng quang minh xoa đầu thọ ký, nhưng ngài giữ kín trong lòng không bao giờ hé lộ với đại chúng. Đến năm Nghĩa Hi thứ mười hai (năm 416), vào đêm mùng sáu tháng tám, khi đang an tọa niệm Phật trong tịnh thất, ngài bỗng thấy hư không bừng sáng như ban ngày, Đức Phật A Di Đà thân vàng tử kim rực rỡ ngự trên đài hoa sen báu biến khắp mười phương, tả hữu có Bồ Tát Quán Thế Âm và Bồ Tát Đại Thế Chí tỏa ánh hào quang chiếu soi ấm áp. Đức Phật từ bi phán bảo rằng: “Ta dùng sức đại nguyện xưa kia nay đến an ủi ngươi; trải qua bảy ngày nữa, ngươi sẽ được vãng sinh về cõi nước Cực Lạc của Ta”. Ngài Huệ Viễn chắp tay đảnh lễ thưa: “Đệ tử từ ngày phát tâm tu học đến nay được ba lần thấy Phật quang dung mạo, nay lại được Thế Tôn trực tiếp thọ ký kỳ hạn, bản nguyện đời con thế là viên mãn!”. Đến đúng ngày ước định sau bảy ngày, ngài an nhiên ngồi ngay thẳng trên bồ đoàn niệm Phật, nhắm mắt thị tịch trong tiếng nhạc trời du dương và hương thơm ngào ngạt lan tỏa khắp núi rừng ba ngày chưa dứt.","Cũng trong truyền thống Bạch Liên Xã núi Lô Sơn được Tịnh Độ Thánh Hiền Lục ghi nhận, cư sĩ Lưu Di Dân (Lưu Trình Chi) vốn là bậc sĩ phu thanh liêm từ quan lên núi Lô Sơn theo Đại sư Huệ Viễn tu niệm Phật. Ông chuyên tâm trì danh hiệu Đức Phật A Di Đà suốt mười lăm năm, định lực thâm sâu đến mức trong lúc tọa thiền thường thấy ánh quang minh thanh tịnh. Khi lâm chung năm Nghĩa Hi thứ sáu, ông thắp hương hướng về phương Tây, bảo chúng bạn rằng đã thấy Đức Phật đến đón, rồi an nhiên chắp tay vãng sinh."],"notes":["Truyện Trương Chung Quỳ trích Tịnh Độ Thánh Hiền Lục quyển 8; truyện Huệ Viễn Đại Sư trích Lương Cao Tăng Truyện quyển 6 (T2059)."]}],"references":["Phật Thuyết Đại Thừa Vô Lượng Thọ Trang Nghiêm Thanh Tịnh Bình Đẳng Giác Kinh, phẩm thứ sáu: Phát Đại Thệ Nguyện, trang in 19–32 — Hạ Liên Cư hội tập; HT Thích Đức Niệm và cư sĩ Minh Chánh Việt dịch; Đạo Tràng Liên Hoa, phiên bản 1.5. Nguồn nguyên văn của mục Đại nguyện.","Phật thuyết Vô Lượng Thọ Kinh, quyển thượng: Pháp Tạng nhân địa, 48 nguyện và đoạn thành Phật; Đại Chính tạng, tập 12, số 360; truyền thống ghi Khang Tăng Khải dịch.","Phật thuyết A Di Đà Kinh, đoạn giải thích danh hiệu và chấp trì danh hiệu từ một đến bảy ngày; Đại Chính tạng, tập 12, số 366; Cưu-ma-la-thập dịch.","Phật thuyết Quán Vô Lượng Thọ Phật Kinh, đoạn ba phước và phép quán thứ 16 về hạ phẩm sinh; Đại Chính tạng, tập 12, số 365; Cương-lương-da-xá dịch.","Bạt nhất thiết nghiệp chướng căn bản đắc sinh Tịnh độ thần chú, một quyển; Đại Chính tạng số 368; thư mục ghi Cầu-na-bạt-đà-la trùng dịch.","Tịnh Độ Thánh Hiền Lục, quyển 8: truyện Trương Chung Quỳ — Bành Tế Thanh soạn tập.","Lương Cao Tăng Truyện, quyển 6: truyện Lô Sơn Huệ Viễn Đại Sư — Huệ Hạo soạn, Đại Chính tạng tập 50, số 2059."]},{"id":"duoc-su","name":"Đức Phật Dược Sư Lưu Ly Quang Như Lai","summary":"Đức Phật Dược Sư Lưu Ly Quang Như Lai là giáo chủ cõi Tịnh Lưu Ly ở phương Đông, tỏa ánh sáng trong suốt và thanh tịnh như ngọc lưu ly. Ngài nổi bật với mười hai đại nguyện cứu giúp chúng sinh vượt qua bệnh khổ, thiếu thốn, tà kiến và dìu dắt muôn loài tiến lên con đường giác ngộ.","sections":[{"id":"biography","title":"Tiểu sử và cõi Tịnh Lưu Ly","paragraphs":["Theo Kinh Dược Sư Bản Nguyện Công Đức, đi về phương Đông vượt qua vô số cõi Phật nhiều như cát của mười sông Hằng, có một thế giới tên là Tịnh Lưu Ly. Giáo chủ của cõi nước thanh tịnh ấy là Đức Phật Dược Sư Lưu Ly Quang Như Lai (Bhaiṣajyaguru Vaiḍūryaprabhārāja). Danh hiệu Dược Sư mang nghĩa là vị Thầy thuốc chữa lành mọi thứ bệnh tật; Lưu Ly Quang nghĩa là ánh sáng xanh biếc trong suốt, sáng sạch không một chút bợn nhơ như chất ngọc lưu ly báu nhiệm mầu.","Cõi Tịnh Lưu Ly ở phương Đông có cảnh sắc trang nghiêm thù thắng hệt như cõi Cực Lạc phương Tây của Đức Phật A Di Đà: mặt đất thuần bằng ngọc lưu ly xanh biếc trong suốt, ranh giới các đường sá được phân định bằng dây vàng ròng, thành quách cung điện, lan can cửa sổ đều được trang sức bằng thất bảo vi diệu. Cõi ấy thuần một bậc giác ngộ thanh tịnh, không có người nữ, không có ác đạo khổ đau và vắng bặt mọi âm thanh phiền não não hại.","Đức Phật Dược Sư có hai vị Đại Bồ Tát thượng thủ là Bồ Tát Nhật Quang Biến Chiếu và Bồ Tát Nguyệt Quang Biến Chiếu, đứng đầu vô lượng chúng Bồ Tát tại cõi Tịnh Lưu Ly, thay nhau phụ tá Đức Phật tuyên dương Chánh pháp và cứu độ chúng sinh khắp mười phương, cùng mười hai vị Dược Xoa Đại Tướng hộ trì người thọ trì danh hiệu Phật.","Kinh Dược Sư Thất Phật Bổn Nguyện Công Đức (do ngài Nghĩa Tịnh dịch) còn nói đến bảy Đức Phật Dược Sư ở phương Đông, trong đó Đức Dược Sư Lưu Ly Quang Như Lai là vị thứ bảy. Kinh cũng ghi mười hai vị Dược Xoa Đại Tướng như Cung Tỳ La, Phạt Chiết La, Mê Xí La cùng phát nguyện hộ trì người thọ trì danh hiệu Phật và lưu thông kinh này."],"notes":["Miêu tả cõi Tịnh Lưu Ly và danh hiệu y cứ Kinh Dược Sư Bản Nguyện Công Đức (Đại Chính tạng T450)."]},{"id":"past-vows","title":"Phát tâm ban đầu","paragraphs":["Kinh Dược Sư ghi nhận rằng thuở quá khứ xa xưa khi còn thực hành Bồ Tát đạo, Đức Phật Dược Sư đã khởi lòng đại bi thương xót chúng sinh chìm đắm trong muôn vàn nỗi thống khổ của thân xác và tâm linh. Ngài quán sát thấy chúng sinh đời mạt pháp bị trăm ngàn thứ bệnh tật bức bách, thân thể tàn tật khiếm khuyết, nghèo cùng túng thiếu cơm ăn áo mặc, lại rơi vào tà kiến mê tín quỷ thần ma quái, đọa lạc vào ba đường ác sinh tử luân hồi.","Đối trước chư Phật mười phương, Ngài đã dõng mãnh phát mười hai lời đại nguyện sâu rộng bao trùm khắp cõi trời người. Ngài nguyện rằng khi thành tựu đạo quả Bồ-đề vô thượng, ánh sáng lưu ly từ thân Ngài sẽ chiếu soi rạng rỡ khắp muôn phương, khiến cho bất kỳ ai nghe đến danh hiệu, chiêm ngưỡng hình tượng hoặc nhất tâm xưng niệm đều được tiêu trừ ác tật, thân tâm đoan trang lành lặn, đầy đủ y phục thực phẩm, chuyển tà quy chánh và tiến thẳng lên con đường giải thoát viên mãn.","Không chỉ phát mười hai đại nguyện cứu khổ ban vui, Đức Phật Dược Sư còn chỉ bày con đường tự lực chuyển hóa nghiệp chướng qua lời Bồ Tát Cứu Thoát trong Kinh Dược Sư: người cầu an lành phải biết giữ gìn tám giới thanh tịnh, siêng năng bố thí phóng sinh, thắp đèn trí tuệ và thực hành tâm từ bi. Nhờ sự kết hợp giữa bổn nguyện gia hộ của Phật và công phu sửa mình của hành giả, thân bệnh và tâm bệnh mới được trị lành tận gốc."],"notes":["Nhân duyên phát tâm trích Kinh Dược Sư Bản Nguyện Công Đức (T450)."]},{"id":"great-vows","title":"Đại nguyện","paragraphs":["Mười hai đại nguyện dưới đây được chép nguyên văn bản Kinh Dược Sư do Trưởng lão HT Thích Trí Quảng biên soạn, đang có trong thư viện của ứng dụng. Nguồn ghi người biên soạn, không ghi dịch giả; đây là nguyên văn của bản biên soạn này.","THỨ NHỨT: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, hào quang của Ta chiếu khắp vô lượng vô biên thế giới, khiến chúng hữu tình thấy ánh quang này, thân tâm thanh tịnh, đủ tướng trượng phu, siêng tu Lục độ, rời biển trần khổ, vào chốn Niết Bàn.","THỨ HAI: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, thân Ta như ngọc lưu ly, trong ngoài sáng suốt, tinh sạch hoàn toàn, hào quang rực rỡ chiếu khắp mười phương. Các chúng hữu tình ở nơi tăm tối cũng thấy thân Ta và được an lành, tùy tâm mãn nguyện.","THỨ BA: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, dùng trí phương tiện dạy chúng hữu tình khiến tin lẫn nhau, làm cho dân giàu nước mạnh.","THỨ TƯ: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình tu theo tà đạo, thì Ta khiến họ trở về chánh đạo. Nếu theo nhị thừa, thì Ta khiến họ cầu Vô thượng giác.","THỨ NĂM: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình ở trong giáo pháp tu hạnh thanh tịnh, thì Ta khiến họ đầy đủ Tam tụ tịnh giới. Nếu ai hủy phạm mà nghe danh Ta, tâm liền thanh tịnh, không đọa ác đạo.","THỨ SÁU: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình thân hình hèn hạ, không đủ sáu căn, xấu xí, khờ khạo, tai điếc, mắt mù, nói năng ngọng liệu, tay chân tật nguyền, lác hủi, điên cuồng, chịu nhiều khổ não. Nghe được danh Ta, liền được khỏi bệnh, thân hình đoan chánh, trí huệ sáng suốt.","THỨ BẢY: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình mang bệnh hiểm nghèo, không người cứu chữa, không chỗ cậy nhờ, nghèo cùng khốn khổ. Nghe được danh Ta, liền được khỏi bệnh, thân tâm thanh tịnh, quyến thuộc sum vầy.","THỨ TÁM: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình mang thân phụ nữ chịu nhiều đau khổ, muốn cầu ra khỏi, nghe được danh Ta, thân tâm thanh tịnh, đủ tướng trượng phu, tiến đến Vô thượng Bồ đề.","THỨ CHÍN: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình sa vào lưới ma, tà giáo ràng buộc, Ta dùng phương tiện khai thị cho họ, khiến khỏi đường mê, tu hạnh Bồ tát, chứng quả Vô thượng Bồ đề.","THỨ MƯỜI: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có hữu tình do vì vô minh phạm phải sai lầm, nên bị giam cầm, chịu nhiều đau khổ. Nghe được danh Ta, tất cả khổ ấy liền được tiêu trừ.","THỨ MƯỜI MỘT: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có người nào nghèo cùng, đói khát, vì cầu thức ăn mà tạo nghiệp ác. Nghe được danh Ta, chuyên lòng thọ trì, thì Ta khiến họ có đủ vật thực và dạy pháp Phật, khiến cho họ được Vô thượng Bồ đề.","THỨ MƯỜI HAI: Ta nguyện đời sau, khi chứng Vô thượng Bồ đề, nếu có người nào nghèo cùng hèn hạ, không có áo mặc, muỗi mòng cắn đốt, nóng lạnh dãi dầu. Nghe được danh Ta, chuyên lòng thọ trì, thì Ta khiến họ có đủ đồ dùng, y phục tốt đẹp, của báu dư thừa."],"notes":[]},{"id":"recitation-benefits","title":"Công đức niệm danh hiệu","paragraphs":["Trong Kinh Dược Sư, công đức của việc tiếp nhận danh hiệu Phật được trình bày gắn liền với sự chuyển hóa khổ đau thiết thực ngay trong đời sống: người bệnh tật được lành bệnh, người nghèo thiếu được no ấm, người lầm đường tà kiến được trở về chánh đạo, và người sợ hãi hiểm nạn được che chở bình an.","Kinh cũng nhấn mạnh rằng khi niệm danh hiệu Đức Phật Dược Sư, hành giả cần nuôi dưỡng tâm từ bi, không khởi tâm hại người, giữ trọn vẹn giới hạnh thanh tịnh và biết bố thí cứu giúp kẻ khốn cùng. Sự tương ứng giữa tâm hành giả với mười hai đại nguyện của Phật mới là cội nguồn phát sinh năng lực chuyển hóa nghiệp chướng.","Bên cạnh đó, Kinh Dược Sư còn chỉ dạy phương pháp hồi hướng cầu sinh cõi Cực Lạc Tây Phương: nếu người nào thọ trì tám giới bát quan trai, nghe và niệm danh hiệu Đức Phật Dược Sư, khi lâm chung sẽ có tám vị Đại Bồ Tát từ trên không trung bay đến chỉ đường đưa lối vãng sinh về thế giới Cực Lạc của Đức Phật A Di Đà.","Trong Kinh Dược Sư, Bồ Tát Cứu Thoát chỉ dạy pháp cầu an cho người bệnh nặng: thọ trì tám giới trong bảy ngày đêm, cúng dường chư Tăng, lễ bái Đức Dược Sư, đọc tụng kinh bốn mươi chín biến, thắp bốn mươi chín ngọn đèn và treo phan ngũ sắc. Ý nghĩa cốt lõi của nghi thức là giữ giới, bố thí, phóng sinh và chí thành sám hối; nghi lễ hỗ trợ cho việc chữa trị y khoa chứ không thay thế thuốc men.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Dược Sư Lưu Ly Quang Vương Phật”."],"notes":["Dẫn kinh Dược Sư, đoạn tám vị Bồ Tát chỉ lối và mười hai nguyện công đức."]},{"id":"mantra-dharani","title":"Thần chú và đà-la-ni","paragraphs":["Bên cạnh việc xưng niệm danh hiệu, pháp môn Dược Sư còn lưu truyền Đà-la-ni và chân ngôn Dược Sư. Trong nghi lễ Bắc truyền Việt Nam, bài chú thường được trì tụng là Dược Sư Quán Đảnh Chân Ngôn (Dược Sư Quán Đảnh Đà-la-ni).","Bài thần chú được xưng tụng theo âm Hán-Việt truyền thống: “Nam-mô bạt-già-phạt-đế, bệ-sát-xã, lũ-lô thích-lưu-ly, bác-lạt-bà, hắc-ra-xà-dã, đát-tha-yết-đa-dã, a-ra-hách-đế, tam-miệu-tam-bột-đà-dã. Đát-điệt-tha: Án, bệ-sát-thệ, bệ-sát-thệ, bệ-sát-xã, tam-một-yết-đế, sa-bà-ha”.","Công dụng của Thần chú Dược Sư theo kinh điển: Khiến cho mọi bệnh tật khổ não nơi thân tâm của chúng sinh đều được dứt trừ tiêu tán; người chí thành trì tụng vào nước sạch hoặc thức ăn thuốc men đem cho người bệnh uống thì tật bệnh mau lành, thân thể kiện khang, tiêu trừ tai ách hiểm nạn và kéo dài thọ mạng.","Kinh Dược Sư chỉ dẫn: khi muốn chữa bệnh cho người, hãy tắm gội sạch sẽ, súc miệng thanh tịnh, trước tôn tượng Phật chuyên tâm trì tụng thần chú một trăm lẻ tám biến vào nước sạch không có vi trùng rồi cho người bệnh uống, nhờ đó những bệnh tật khổ não đều được giải trừ.","Việc trì tụng thần chú Dược Sư luôn đi cùng với việc tìm kiếm sự chăm sóc y tế đúng đắn, ăn uống điều độ, sám hối lỗi lầm và nuôi dưỡng tâm từ bi đối với muôn loài, không nên lạm dụng niềm tin tôn giáo để từ bỏ các phương pháp chữa trị y khoa cần thiết."],"notes":["Đối chiếu Dược Sư Quán Đảnh Chân Ngôn trong Kinh Dược Sư (T450)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sách Tam Bảo Cảm Ứng Yếu Lược Lục chép rằng: ở Thiên Trúc có một gia đình Bà-la-môn hiếm muộn, sau nhiều năm cầu nguyện mới sinh được một con trai khôi ngô. Thầy tướng xem rồi nói đứa bé mang tướng yểu, khó sống qua bảy ngày. Cha mẹ đau buồn, được một vị Sa-môn khuyên tạo tượng Đức Dược Sư, thắp đèn, treo phan, tụng kinh và thọ trì tám giới. Hai vợ chồng thành tâm làm theo. Đêm ấy người cha mộng thấy có người báo rằng nhờ công đức cúng dường Đức Dược Sư, đứa trẻ được tăng thêm tuổi thọ. Về sau con trai lớn lên khỏe mạnh, cả nhà càng thêm tin sâu Tam Bảo.","Cũng theo Tam Bảo Cảm Ứng Yếu Lược Lục, có một người vốn xuất thân giàu có nhưng sa sút, phải đi xin ăn; họ hàng thấy ông đến đều đóng cửa, nên người đời gọi ông là Bế Môn. Hổ thẹn và cùng quẫn, ông vào chùa có tượng Đức Dược Sư, chí thành sám hối, đi nhiễu quanh tượng và niệm danh hiệu Nam Mô Dược Sư Lưu Ly Quang Như Lai suốt nhiều ngày. Đến ngày thứ năm, ông mộng thấy Đức Phật bảo rằng nghiệp chướng cũ đã nhẹ, hãy trở về nhà xưa. Ông làm theo và tìm được của cải tổ tiên cất giữ, từ đó đời sống ổn định, ông đem một phần tài sản cúng dường Tam Bảo và giúp đỡ người nghèo.","Ngay trong Kinh Dược Sư, khi Tôn giả A-nan hỏi về cách cứu người bệnh nặng sắp hết thọ mạng, Bồ Tát Cứu Thoát đã truyền dạy pháp tục mạng: thân quyến chí thành thọ trì bát quan trai giới trong bảy ngày bảy đêm, tụng Kinh Dược Sư bốn mươi chín biến, thắp bốn mươi chín ngọn đèn sáng liên tục, treo thần phan ngũ sắc dài bốn mươi chín gang tay và phóng sinh bốn mươi chín loài vật. Nhờ phước lực thanh tịnh ấy, nhiều người lâm vào cảnh nguy kịch đã chuyển hóa được nghiệp lực, hồi tỉnh và tiếp tục sống đời hướng thiện.","Sách Minh Chí Ký (trích trong Tam Bảo Cảm Ứng Yếu Lược Lục) kể về cô gái nghèo côi cút ở Biên Châu đời Đường: cả gia tài cô chỉ còn vỏn vẹn một đồng tiền. Nghe giảng về bổn nguyện cứu giúp người nghèo khó của Đức Phật Dược Sư, cô đem đồng tiền duy nhất đến chùa dâng cúng trước tôn tượng Ngài với tâm thanh tịnh không chút tiếc nuối. Không lâu sau, cô gặp nhân duyên lành với một gia đình thiện tâm giàu có ở huyện bên, thoát cảnh bần hàn và suốt đời hộ trì Tam Bảo.","Bên cạnh các tích cứu thoát bệnh tật hiểm nghèo và cảnh cùng quẫn trong Tam Bảo Cảm Ứng Yếu Lược Lục, truyền thống Dược Sư luôn nhấn mạnh sự gia hộ đi đôi với tâm sám hối và chuyển hóa lối sống. Khi người bệnh giữ tâm an tĩnh, tin sâu nhân quả, kết hợp chí thành niệm danh hiệu Nam Mô Dược Sư Lưu Ly Quang Như Lai với việc chữa trị y khoa đúng đắn, tinh thần vững vàng sẽ hỗ trợ thân tâm sớm phục hồi an lạc."],"notes":["Hai truyện đối chiếu Tam Bảo Cảm Ứng Yếu Lược Lục (Phi Trược soạn đời Liêu), phần cảm ứng của Đức Dược Sư."]}],"references":["Kinh Dược Sư — Trưởng lão HT Thích Trí Quảng biên soạn, phần mười hai đại nguyện, từ THỨ NHỨT đến THỨ MƯỜI HAI. Bản đang có trong thư viện của ứng dụng; nguồn nguyên văn của mục Đại nguyện.","The Detailed Account of the Previous Aspirations of the Blessed Bhaiṣajyaguruvaiḍūryaprabha, Toh 504, đoạn 1.2–1.7 và 1.20–1.22 — Dharmachakra Translation Committee, 84000.","Kinh Dược Sư, Đại Chính tạng tập 14, số 450: mười hai nguyện và các đoạn tám giới, cầu sinh Cực Lạc, cúng dường bảy ngày đêm — Huyền Trang Hán dịch.","Tam Bảo Cảm Ứng Yếu Lược Lục — Phi Trược soạn, Đại Chính tạng tập 51, số 2084.","Kinh Dược Sư Thất Phật Bổn Nguyện Công Đức — Nghĩa Tịnh Hán dịch, Đại Chính tạng số 451."]},{"id":"quan-the-am","name":"Quán Thế Âm Bồ Tát","summary":"Bồ Tát Quán Thế Âm (Avalokiteśvara) là vị Đại Bồ Tát biểu trưng cho lòng Đại Bi vô lượng vô biên, tầm thinh cứu khổ cứu nạn khắp mười phương pháp giới. Ngài cùng Bồ Tát Đại Thế Chí là hai bậc Thượng thủ trợ hóa Đức Phật A Di Đà nơi cõi Tây Phương Cực Lạc.","sections":[{"id":"tieu-su","title":"Tiểu sử và ba mươi hai ứng hóa thân","paragraphs":["Trong truyền thống Phật giáo Đại thừa, danh hiệu Quán Thế Âm mang ý nghĩa vô cùng sâu sắc: Quán là quán chiếu, lắng nghe và thấu suốt; Thế Âm là mọi âm thanh tiếng kêu cầu đau khổ, than khóc của chúng sinh chốn trần gian. Khi chúng sinh gặp phải muôn vàn nghịch cảnh hiểm nguy, nếu chí tâm xưng niệm danh hiệu Ngài, Ngài liền quán xét âm thanh ấy mà hiện thân cứu độ, ban cho sự không sợ hãi (vô úy thí). Ngài còn được tôn xưng là Quán Tự Tại (Avalokiteśvara), biểu thị cho trí tuệ Bát-nhã quán chiếu sâu xa năm uẩn đều không, tự tại giải thoát trước mọi ràng buộc của sinh tử luân hồi.","Theo Kinh Bi Hoa (phẩm Chư Bồ Tát Bổn Thọ Ký), vào thuở quá khứ xa xưa, tiền thân của Bồ Tát Quán Thế Âm là Thái tử Bất Huyền, con trưởng của vua Vô Tranh Niệm (tiền thân Đức Phật A Di Đà). Vâng theo lời dạy của phụ vương, Thái tử đối trước Đức Phật Bảo Tạng phát đại thệ nguyện: Nếu có chúng sinh nào chịu muôn ngàn khổ não, sợ hãi, không nơi nương tựa, nếu xưng danh hiệu con mà con không quán xét cứu thoát thì con quyết không thành Phật. Đức Phật Bảo Tạng khen ngợi và thọ ký cho Thái tử danh hiệu Quán Thế Âm, đời sau khi Phật A Di Đà nhập Niết-bàn thì Ngài sẽ nối ngôi vị Phật tại cõi Cực Lạc với tôn hiệu Biến Xuất Nhất Thiết Quang Minh Công Đức Sơn Vương Như Lai.","Kinh Diệu Pháp Liên Hoa (phẩm Quán Thế Âm Bồ Tát Phổ Môn thứ 25) chỉ rõ hạnh nguyện tùy duyên hóa độ của Ngài qua ba mươi hai ứng hóa thân: tùy theo căn cơ và hoàn cảnh của người cần độ mà Ngài hiện thân Phật, thân Bích Chi Phật, thân Thinh Văn, thân Phạm Vương, thân Đế Thích, thân Tể quan, thân Cư sĩ, phụ nữ hay đồng nam đồng nữ để thuyết pháp hóa độ, dắt dẫn muôn loài về nẻo thiện lành an lạc.","Hình tượng Bồ Tát Quán Thế Âm trong lòng người Phật tử Việt Nam thường hiện thân người mẹ hiền từ đắp y trắng thanh khiết (Bạch Y Quán Âm), tay trái nâng tịnh bình chứa đầy nước cam lộ biểu trưng cho lòng từ bi dập tắt lửa phiền não, tay phải cầm cành dương liễu dẻo dai biểu trưng cho đức nhẫn nhục nhu hòa rưới mát nhân gian."],"notes":["Ý nghĩa danh hiệu và ba mươi hai ứng thân y cứ Kinh Pháp Hoa phẩm Phổ Môn; nhân duyên tiền thân y cứ Kinh Bi Hoa."]},{"id":"phat-nguyen-khi-tu-nhan","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, vào thuở quá khứ vô lượng kiếp về trước, khi Đức Bồ Tát Quán Thế Âm đang ở bậc sơ địa tu học nơi đạo tràng của Đức Phật Thiên Quang Vương Tịnh Trụ Như Lai. Bấy giờ, Đức Phật Thiên Quang Vương Tịnh Trụ vì thương xót chúng sinh đời vị lai nhiều tội chướng khổ đau bèn truyền trao cho Ngài thần chú Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, và ân cần căn dặn: “Này thiện nam tử, ngươi hãy trì giữ chú tâm này để làm lợi ích an vui lớn cho tất cả chúng sinh trong đời ác vị lai”.","Vừa nghe thần chú xong, Bồ Tát Quán Thế Âm liền từ bậc Sơ địa vượt thẳng lên Đệ bát địa (Bất Động Địa), tâm sinh hoan hỷ cùng tột. Đối trước mười phương chư Phật, Ngài dõng mãnh phát lời đại thệ nguyện: “Nếu trong đời vị lai, con có thể làm lợi ích an vui cho tất cả chúng sinh, thì xin khiến cho thân con ngay lập tức sinh ra ngàn tay ngàn mắt để soi thấu và cứu vớt muôn loài!”. Lời nguyện vừa dứt, toàn thân Ngài liền hiện ra ngàn tay ngàn mắt sáng rực rỡ, mười phương chư Phật đồng phóng ánh quang minh chiếu soi, trời mưa hoa báu ngào ngạt, địa cầu rung chuyển sáu điệu chấn động, minh chứng cho tâm Bồ-đề kim cang bất hoại.","Ngoài pháp môn Đại Bi Tâm Đà La Ni, trong Kinh Thủ Lăng Nghiêm (quyển 6), Bồ Tát Quán Thế Âm trình bày rằng Ngài đã chứng đắc Nhĩ Căn Viên Thông nhờ theo Đức Phật Quán Thế Âm Như Lai thuở quá khứ tu tập pháp lắng nghe phản văn tự tánh. Từ khi nhập lưu quên sở, Ngài thành tựu ba mươi hai ứng thân tùy duyên thị hiện khắp mười phương, có hai sức mạnh thù thắng là trên hợp bản giác diệu tâm của chư Phật và dưới đồng bi ngưỡng của tất cả chúng sinh trong sáu đường."],"notes":["Trích Kinh Đại Bi Tâm Đà La Ni (Đại Chính tạng T1060), bản dịch Già Phạm Đạt Ma."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Kinh Diệu Pháp Liên Hoa, phẩm Quán Thế Âm Bồ Tát Phổ Môn thứ 25, có lời kệ Đức Phật nói về hạnh nguyện của Bồ Tát Quán Thế Âm. Đây là lời kinh mô tả hạnh nguyện, không phải danh sách mười hai đại nguyện do Bồ Tát tự tuyên nói. Bản Việt dịch HT Thích Trí Tịnh:","Ông nghe hạnh Quán-Âm Khéo ứng các nơi chỗ Thệ rộng sâu như biển Nhiều kiếp chẳng nghĩ bàn Hầu nhiều nghìn đức Phật Phát nguyện thanh tịnh lớn.","Kệ nói về hạnh cứu khổ khắp mười phương — phẩm Phổ Môn:","Chúng sanh bị khổ ách Vô lượng khổ bức thân Quán-Âm sức trí diệu Hay cứu khổ thế gian Đầy đủ sức thần thông Rộng tu trí phương tiện Các cõi nước mười phương Không cõi nào chẳng hiện. Các loài trong đường dữ: Địa-ngục, quỉ, súc sanh Sanh, già, bịnh, chết khổ Lần đều khiến dứt hết.","Đức Phật nói về hạnh hiện thân độ sinh và ban sự không sợ hãi — phẩm Phổ Môn:","Vô-Tận-Ý! Quán-Thế-Âm Bồ-Tát đó thành tựu công đức như thế, dùng các thân hình, dạo đi trong các cõi nước để độ thoát chúng sanh, cho nên các ông phải một lòng cúng dường Quán-Thế-Âm Bồ-Tát. Quán-Thế-Âm đại Bồ-Tát đó ở trong chỗ nạn gấp sợ sệt hay ban sự vô-úy, cho nên cõi Ta-bà này đều gọi Ngài là vị \\"Thí-vô-úy\\".","Mười Lời Nguyện Lớn trong Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni (Bản dịch HT Thích Trí Tịnh):","1. Nam mô Đại Bi Quán Thế Âm, nguyện con mau biết tất cả pháp.\\n2. Nam mô Đại Bi Quán Thế Âm, nguyện con sớm được mắt trí tuệ.\\n3. Nam mô Đại Bi Quán Thế Âm, nguyện con mau độ tất cả chúng.\\n4. Nam mô Đại Bi Quán Thế Âm, nguyện con sớm được phương tiện khéo.\\n5. Nam mô Đại Bi Quán Thế Âm, nguyện con mau lên thuyền Bát-nhã.\\n6. Nam mô Đại Bi Quán Thế Âm, nguyện con sớm qua biển khổ ách.\\n7. Nam mô Đại Bi Quán Thế Âm, nguyện con mau được giới định đạo.\\n8. Nam mô Đại Bi Quán Thế Âm, nguyện con sớm lên non Niết-bàn.\\n9. Nam mô Đại Bi Quán Thế Âm, nguyện con mau về nhà vô vi.\\n10. Nam mô Đại Bi Quán Thế Âm, nguyện con sớm chứng pháp thân Phật.","Thệ nguyện cứu nạn nơi chốn khổ đau cùng cực:\\n“Nếu con hướng về núi đao, núi đao tự sụp đổ;\\nHướng về lửa dữ, lửa dữ tự tắt cháy;\\nHướng về địa ngục, địa ngục tự khô cạn;\\nHướng về ngạ quỷ, ngạ quỷ tự no đủ;\\nHướng về Tu-la, tâm ác tự điều phục;\\nHướng về súc sanh, súc sanh tự đặng đại trí huệ.”"],"notes":[]},{"id":"loi-ich-tri-danh","title":"Công đức niệm danh hiệu","paragraphs":["Theo Kinh Diệu Pháp Liên Hoa, phẩm Phổ Môn, nếu có chúng sinh nào đang chịu nhiều khổ não mà được nghe danh hiệu Quán Thế Âm Bồ Tát, rồi một lòng xưng niệm, thì Bồ Tát liền quán sát âm thanh ấy mà khiến cho tất cả đều được giải thoát. Kinh nêu rõ các trường hợp hiểm nguy như lửa cháy, nước cuốn, chìm thuyền nơi biển cả, đao trượng gươm giáo, quỷ dữ, tù ngục xiềng xích và giặc cướp hại; khi chí tâm niệm danh hiệu Ngài thì những mối nguy ấy đều được hóa giải an toàn.","Bên cạnh việc cứu nạn tai khổ nơi thân thể, phẩm Phổ Môn còn nhấn mạnh công năng chuyển hóa sâu sắc nơi tâm thức: người nhiều lòng dâm dục nếu thường cung kính niệm Quán Thế Âm Bồ Tát liền được lìa lòng dục; người nhiều sân hận nóng nảy thường niệm Ngài liền được lìa lòng sân; người nhiều si mê tăm tối thường niệm Ngài liền được lìa lòng si. Lời kinh khẳng định oai thần của Bồ Tát rộng lớn nhiều điều lợi ích như thế, nên người tu học phải luôn thường nhớ nghĩ nơi lòng.","Xưng niệm danh hiệu Quán Thế Âm không phải là sự van xin mê tín hay ỷ lại vào tha lực bên ngoài, mà chính là sự kết nối tâm mình với bản nguyện Đại Bi của Bồ Tát. Khi miệng niệm tai nghe, lòng hành giả thấm nhuần chất liệu yêu thương và hiểu biết, biết lắng nghe nỗi khổ niềm đau của chính mình và những người chung quanh, từ đó mở rộng dung lượng trái tim bao dung tha thứ.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đại Bi Quán Thế Âm Bồ Tát”."],"notes":["Dẫn Kinh Pháp Hoa, phẩm Phổ Môn thứ 25."]},{"id":"chan-ngon-da-la-ni","title":"Thần chú và đà-la-ni","paragraphs":["Pháp môn gắn với Bồ Tát Quán Thế Âm có nhiều bài đà-la-ni và chân ngôn quan trọng, trong đó nổi bật nhất là Thần chú Đại Bi (Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni) gồm 84 câu, và Lục Tự Đại Minh Chân Ngôn (Oṃ Maṇi Padme Hūṃ).","Câu thần chú Lục Tự Đại Minh Chân Ngôn được phiên âm tiếng Việt: “Ôm ma-ni bát-mê hồng” (hoặc “Án ma ni bát di hồng”), biểu thị cho viên ngọc quý ma-ni nằm trong đóa hoa sen thanh tịnh, biểu trưng cho tâm Bồ-đề giác ngộ tròn đầy vượt thoát sáu nẻo luân hồi.","Công dụng của Thần chú Đại Bi và Lục Tự Chân Ngôn theo kinh điển: Khiến cho hành giả tiêu trừ trăm ngàn muôn ức kiếp tội nặng sinh tử; diệt trừ mười lăm thứ ác tử và thành tựu mười lăm điều thiện sinh; xua đuổi tà ma ác quỷ, chữa lành các thứ tật bệnh nan y; tăng trưởng phước đức, trí tuệ Ba-la-mật và được chư Phật, Bồ Tát mười phương thường theo gia hộ.","Kinh Đại Bi Tâm Đà La Ni dạy rằng trước khi trì tụng, hành giả cần khởi lòng thương xót bình đẳng đối với tất cả chúng sinh, phát mười điều nguyện lớn, giữ gìn trai giới sạch sẽ, không khởi tâm nghi ngờ. Lời dạy ấy cho thấy công năng của mật chú phát sinh từ nền tảng từ bi chân thật, không thể tách rời việc tu dưỡng đạo đức và thanh tịnh hóa thân tâm.","Khi thực hành, người Phật tử nên nương tựa vào cách phát âm truyền thống của chùa viện mình tu học, giữ nhịp thở đều đặn, chú tâm lắng nghe từng âm thanh chú ngữ để tâm trí lắng đọng và an định."],"notes":["Đối chiếu Kinh Đại Bi Tâm Đà La Ni (T1060) và Kinh Đại Thừa Trang Nghiêm Bảo Vương (T1050)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích đoàn thuyền buôn Lưu Bá Hưng vượt cuồng phong bão táp trên biển Đông Hải được ghi chép trong Tân Biên Quán Âm Linh Cảm Lục (do Đại lão Hòa thượng Ấn Quang chứng minh và đề tựa): Vào thời nhà Thanh, một thương gia thuần thành tên là Lưu Bá Hưng cùng hơn sáu mươi người đi trên một chiếc thuyền buôn lớn chở đầy tơ lụa và trà từ Quảng Đông sang vùng duyên hải phương Bắc. Khi thuyền ra đến giữa biển Đông Hải, mây đen cuồn cuộn kéo đến che kín bầu trời, một trận cuồng phong bão táp dữ dội bất ngờ ập tới. Những đợt sóng biển dâng cao như ngọn núi khổng lồ gầm rú trùm lên boong thuyền, cột buồm chính gãy đôi kêu răng rắc rớt xuống biển, bánh lái bị gãy văng, nước biển tràn vào khoang ầm ầm. Trong bóng đêm mịt mù sấm chớp gầm vang, chiếc thuyền chao đảo ngả nghiêng chực chìm xuống đáy đại dương, hơn sáu mươi thương nhân và thủy thủ hoảng loạn cùng cực, ôm lấy nhau khóc lóc thảm thiết chuẩn bị chờ cái chết. Trong giây phút sinh tử ngàn cân treo sợi tóc ấy, Lưu Bá Hưng sực nhớ đến lời dạy trong Kinh Pháp Hoa phẩm Phổ Môn, bèn đứng bật dậy giữa boong thuyền, dốc hết tàn lực hô to: “Tất cả bà con hãy quỳ xuống mau, hãy cùng tôi dốc trọn tính mạng niệm Bồ Tát Quán Thế Âm để cầu cứu!”. Hơn sáu mươi con người trong cơn cùng quẫn liền đồng loạt quỳ sụp xuống sàn gỗ ướt sũng, chắp tay hướng lên hư không gào khóc thảm thiết: “Nam mô Đại Bi Quán Thế Âm Bồ Tát! Nam mô Đại Bi Quán Thế Âm Bồ Tát!”. Tiếng niệm Phật át cả tiếng gầm của sóng gió bão bùng. Kỳ diệu thay, chỉ sau vài mươi tiếng xưng niệm tha thiết, bỗng nhiên giữa bầu trời giông bão đen kịt xuất hiện một vầng mây trắng tỏa ra luồng ánh sáng vàng dịu mát bao trùm lấy con thuyền. Giữa vầng mây ấy, mọi người tận mắt nhìn thấy rõ ràng hình ảnh một vị Bồ Tát áo trắng trang nghiêm vô cùng thanh khiết, tay nâng bình ngọc, tay cầm cành dương liễu rảy nhẹ ba giọt nước cam lộ xuống biển. Lập tức cuồng phong tắt lịm, sóng biển cuộn trào bỗng trở nên phẳng lặng như gương soi, mây đen tan biến để lộ ánh trăng rằm vằng vặc chiếu soi. Chiếc thuyền vỡ được làn gió mát lành đẩy nhẹ nhàng trôi dạt vào bờ cát an toàn vào sáng sớm hôm sau. Toàn bộ hơn sáu mươi con người quỳ phục trên bờ cát vừa khóc nức nở vừa đảnh lễ cảm tạ ân đức cứu mạng như trời biển của Bồ Tát Quán Thế Âm.","Sự tích Tôn Kính Đức và Kinh Cao Vương Quán Thế Âm được chép trong Pháp Uyển Châu Lâm (quyển 17) và sử sách đời Bắc triều: vào niên hiệu Thiên Bình (534–537) đời Đông Ngụy, ở Định Châu có người lính tên Tôn Kính Đức tự tạc một pho tượng Quán Thế Âm để lễ bái hằng ngày. Về sau ông bị vu oan là giặc cướp, bị kết án tử. Trong ngục, ông chí thành sám hối và mộng thấy một vị Sa-môn dạy tụng một bài kinh cứu khổ đủ một nghìn biến. Ông thức dậy tụng liền không dứt. Đến ngày hành hình, ông vừa tụng đủ số thì lưỡi đao chém xuống ba lần đều gãy mà thân không hề hấn gì. Quan trên tâu lên, ông được tha tội. Khi trở về, ông thấy trên cổ pho tượng Quán Thế Âm có ba vết đao. Bài kinh ấy về sau được lưu truyền với tên Cao Vương Quán Thế Âm Kinh.","Trong các truyện ký về đạo tràng Phổ Đà Sơn ở Trung Hoa, Lương Cao Tăng Truyện và Tống sử ghi lại nhân duyên sư Huệ Ngạc người Nhật Bản vào thời Đường (năm 858–916) thỉnh tôn tượng Bồ Tát Quán Thế Âm từ Ngũ Đài Sơn về nước. Khi thuyền đi ngang vùng biển Chu San thì gặp sóng lớn và hoa sen sắt mọc dày không thể tiến bước. Sư Huệ Ngạc hiểu ý Bồ Tát muốn lưu lại hóa độ nơi đây, liền cung thỉnh tôn tượng lên đảo Phổ Đà lập am Bất Khẳng Khứ Quán Âm Viện; từ đó Phổ Đà Sơn trở thành một trong Tứ đại danh sơn linh ứng bậc nhất của Phật giáo Bắc truyền.","Sự tích Cáp Lị Quán Âm được ghi chép trong sử liệu Phật giáo đời Đường: vua Đường Văn Tông vốn ưa dùng món nghêu sò. Một hôm ngài nhận được con sò lớn, dùng dao cạy mãi không mở được. Vua bèn thắp hương khấn nguyện thì vỏ sò tự hé ra, bên trong hiện tôn tượng Bồ Tát Quán Thế Âm trang nghiêm. Kinh ngạc và tỉnh ngộ, vua thỉnh Thiền sư Duy Chính ở núi Chung Nam vào hỏi đạo, từ đó phát tâm bỏ ăn loài có vỏ và ban chiếu cho các chùa trong nước tôn thờ tượng Bồ Tát Quán Thế Âm.","Bộ Pháp Uyển Châu Lâm của Pháp sư Đạo Thế đời Đường cùng Tân Biên Quán Âm Linh Cảm Lục còn ghi chép hàng loạt trường hợp vượt qua hỏa hoạn, đao binh và ngục tù oan trái nhờ chí thành niệm danh hiệu Bồ Tát Quán Thế Âm. Các bậc cổ đức ví lòng từ bi của Bồ Tát như vầng trăng sáng luôn chiếu rọi, còn tâm người niệm như mặt hồ; khi mặt hồ lắng trong, không xao động vì nghi ngờ hay sân hận, ánh trăng cảm ứng tự nhiên hiển hiện."],"notes":["Truyện thuyền Lưu Bá Hưng trích Tân Biên Quán Âm Linh Cảm Lục; truyện Tôn Kính Đức đối chiếu Pháp Uyển Châu Lâm quyển 17."]}],"references":["Kinh Diệu Pháp Liên Hoa, phẩm Quán Thế Âm Bồ Tát Phổ Môn thứ 25 — HT Thích Trí Tịnh Việt dịch. Nguồn nguyên văn của các đoạn trích trong mục Đại nguyện.","Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, Đại Chính tạng tập 20, số 1060 — Già Phạm Đạt Ma Hán dịch.","Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký — Đàm-vô-sấm dịch, Đại Chính tạng số 157.","Tân Biên Quán Âm Linh Cảm Lục — cư sĩ Lý Viên Tịnh biên soạn, Đại lão Hòa thượng Ấn Quang chứng minh và đề tựa.","Quán Thế Âm Bồ Tát Bổn Tích Cảm Ứng Tụng — dẫn truyện cảm ứng đời Tống và đời Thanh.","Pháp Uyển Châu Lâm, quyển 17 — Đạo Thế soạn đời Đường, Đại Chính tạng tập 53, số 2122.","Pháp Uyển Châu Lâm — Đạo Thế soạn đời Đường, Đại Chính tạng tập 53, số 2122."]},{"id":"dai-the-chi","name":"Đại Thế Chí Bồ Tát","summary":"Bồ Tát Đại Thế Chí (Mahāsthāmaprāpta) là vị Đại Bồ Tát biểu trưng cho Ánh Sáng Trí Tuệ vô biên, dùng năng lực niệm Phật Tam Muội tiếp dẫn chúng sinh vãng sinh Tây Phương Cực Lạc. Ngài cùng Bồ Tát Quán Thế Âm là hai bậc Thượng thủ trợ hóa Đức Phật A Di Đà.","sections":[{"id":"biography","title":"Tiểu sử và tướng hảo quang minh","paragraphs":["Trong truyền thống Phật giáo Đại thừa Đông Á, Bồ Tát Đại Thế Chí (Mahāsthāmaprāpta) cùng với Đức Phật A Di Đà và Bồ Tát Quán Thế Âm được tôn kính phụng thờ là Tây Phương Tam Thánh. Nếu Bồ Tát Quán Thế Âm biểu trưng cho lòng Đại Bi cứu khổ thì Bồ Tát Đại Thế Chí biểu trưng cho Ánh Sáng Đại Trí siêu việt: Ngài dùng ánh sáng trí tuệ chiếu soi khắp cùng mười phương cõi nước, khiến cho chúng sinh rời xa ba đường ác (địa ngục, ngạ quỷ, súc sinh), thành tựu sức mạnh vô thượng để tiến thẳng đến đạo quả Bồ-đề.","Theo Kinh Quán Vô Lượng Thọ, thân tướng của Bồ Tát Đại Thế Chí vô cùng vĩ đại và trang nghiêm rực rỡ: toàn thân tỏa ra ánh sáng trí tuệ màu vàng tử kim chiếu sáng khắp các cõi Phật; trên đỉnh đầu Ngài có nhục kế như hoa sen đỏ, trên nhục kế an trí một chiếc bảo bình quý báu chứa đầy ánh sáng trí tuệ nhiệm mầu chiếu soi khắp Phật sự mười phương; khi Ngài cất bước chân đi thì khắp tam thiên đại thiên thế giới đều chấn động sáu cách thanh tịnh.","Theo Kinh Bi Hoa (phẩm Chư Bồ Tát Bổn Thọ Ký), tiền thân của Ngài là Vương tử Ni-ma, con thứ hai của vua Vô Tranh Niệm (tiền thân Phật A Di Đà) và là em của Thái tử Bất Huyền (tiền thân Bồ Tát Quán Thế Âm). Vương tử đối trước Phật Bảo Tạng phát nguyện dùng trọn vẹn trí tuệ và công đức của mình để giáo hóa dắt dẫn chúng sinh lìa khổ được vui, hộ trì Chánh pháp lâu dài nơi cõi Tịnh độ. Đức Phật Bảo Tạng thọ ký cho Ngài danh hiệu Đại Thế Chí, đời sau khi Phật Quán Thế Âm nhập Niết-bàn thì Ngài sẽ nối ngôi thành Phật với tôn hiệu Thiện Trụ Trân Bảo Sơn Vương Như Lai.","Trong Kinh Thủ Lăng Nghiêm, Bồ Tát Đại Thế Chí xuất hiện giữa pháp hội của Đức Phật Thích Ca Mâu Ni, tuyên thuyết chương Niệm Phật Viên Thông lừng danh, chỉ dạy phương pháp dùng tâm nhớ Phật niệm Phật để thành tựu Tam muội vãng sinh Cực Lạc."],"notes":["Thân tướng và bảo bình y cứ Kinh Quán Vô Lượng Thọ; tiền thân Vương tử Ni-ma y cứ Kinh Bi Hoa; pháp môn niệm Phật y cứ Kinh Lăng Nghiêm."]},{"id":"before-awakening","title":"Phát tâm ban đầu","paragraphs":["Theo chương Đại Thế Chí Bồ Tát Niệm Phật Viên Thông trong Kinh Thủ Lăng Nghiêm, Bồ Tát Đại Thế Chí kể lại rằng vào thuở quá khứ xa xưa vô lượng hằng hà sa kiếp, có Đức Phật ra đời mang danh hiệu Siêu Nhật Nguyệt Quang Như Lai, cùng mười hai Đức Như Lai kế tiếp nhau trong một kiếp giáng trần giáo hóa.","Đức Phật cuối cùng trong mười hai vị ấy đã chỉ dạy cho Ngài pháp môn Niệm Phật Tam Muội: “Mười phương Như Lai thương nhớ chúng sinh như mẹ nhớ con; nếu con trốn tránh, tuy mẹ nhớ nào có ích gì; nếu con nhớ mẹ như mẹ nhớ con, thì mẹ con đời đời không xa nhau”. Vâng theo lời Phật dạy sâu sắc ấy, khi còn ở bậc tu nhân, Ngài đã chuyên tâm nhiếp trọn sáu căn, tịnh niệm nối tiếp nhau không gián đoạn, từ nơi tâm niệm Phật mà ngộ nhập Vô Sanh Pháp Nhẫn, thành tựu Bồ-đề đạo quả.","Bên cạnh pháp hội Niệm Phật Viên Thông trong Kinh Lăng Nghiêm, Kinh Bi Hoa cũng ghi lại một tiền thân khác của Ngài là vương tử thứ hai tên Ni Ma (còn gọi là Đắc Đại Thế), con của Chuyển luân Thánh vương Vô Tránh Niệm dưới thời Đức Phật Bảo Tạng. Sau khi phụ thân (tiền thân Đức Phật A Di Đà) và huynh trưởng Bất Huyền (tiền thân Bồ Tát Quán Thế Âm) phát nguyện trang nghiêm Tịnh Độ, vương tử Ni Ma cũng phát đại nguyện kế thừa sự nghiệp giáo hóa, làm vị Pháp Vương Tử giữ gìn ánh sáng trí tuệ tiếp dẫn chúng sinh về cõi An Lạc."],"notes":["Trích Kinh Thủ Lăng Nghiêm, quyển 5, chương Đại Thế Chí Niệm Phật Viên Thông (Đại Chính tạng T945)."]},{"id":"great-vows","title":"Đại nguyện","paragraphs":["Trích lời Bồ Tát Đại Thế Chí tự thuật về hạnh niệm Phật và tiếp dẫn chúng sinh trong Kinh Thủ Lăng Nghiêm, quyển 5, đoạn Đại Thế Chí Bồ Tát Niệm Phật Viên Thông. Giữ nguyên cách viết của bản kinh trong dự án; chưa xác định dịch giả của dữ liệu này:","Bản-nhân của tôi là dùng tâm niệm Phật mà vào pháp vô-sinh-nhẫn, nay ở cõi nầy tiếp-dẫn những người niệm Phật về cõi Tịnh-độ.","Trong Kinh Thủ Lăng Nghiêm, Bồ Tát Đại Thế Chí chỉ rõ bản nguyện tiếp dẫn người niệm Phật bằng ví dụ tình mẫu tử sâu sắc:","“Mười phương Như Lai thương nhớ chúng sinh như mẹ nhớ con. Nếu con trốn tránh, tuy mẹ nhớ nào có ích gì? Nếu con nhớ mẹ như mẹ nhớ con, mẹ con đời đời chẳng xa nhau. Nếu tâm chúng sinh nhớ Phật niệm Phật, hiện tiền hoặc tương lai nhất định thấy Phật, cách Phật chẳng xa, không cần mượn phương tiện nào khác mà tự mở tỏ tâm trí.”","“Như người ướp hương thì thân có mùi hương, ấy gọi là Hương Quang Trang Nghiêm. Bản nguyện của tôi là lấy tâm niệm Phật làm nhân địa tu hành, đạt đến quả vị Vô Sanh Pháp Nhẫn, nay ở cõi Ta Bà này cùng Đức Quán Thế Âm phò trợ Đức Phật A Di Đà, dẫn dắt tất cả người niệm Phật đồng quy về thế giới Cực Lạc.”"],"notes":[]},{"id":"recitation-benefits","title":"Công đức niệm danh hiệu","paragraphs":["Trong Kinh Quán Vô Lượng Thọ, phần cuối kinh nhấn mạnh rằng người nào được nghe danh hiệu của Đức Phật Vô Lượng Thọ cùng hai vị Đại Bồ Tát Quán Thế Âm và Đại Thế Chí, thì trừ được vô lượng kiếp tội nặng sinh tử luân hồi, huống chi là người chí tâm xưng niệm, lễ bái và quán tưởng thân tướng trang nghiêm của các Ngài.","Bên cạnh việc xưng niệm Phật A Di Đà, việc xưng niệm và quán tưởng Bồ Tát Đại Thế Chí giúp hành giả nuôi dưỡng nguồn ánh sáng trí tuệ, dẹp trừ tà niệm si mê và tâm trí hoảng loạn, củng cố định lực và niềm tin vững chắc trên con đường tu tập Tịnh độ môn.","Thực hành theo lời dạy “Nhiếp trọn sáu căn, tịnh niệm nối tiếp” trong chương Niệm Phật Viên Thông nghĩa là thu giữ mắt, tai, mũi, lưỡi, thân, ý không chạy theo cảnh trần tán loạn, mà giữ câu niệm Phật sáng rõ, liên tục trong từng hơi thở và sinh hoạt hằng ngày. Khi tâm không buông lung theo vọng tưởng, trí tuệ tự nhiên hiển lộ.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đại Thế Chí Bồ Tát”."],"notes":["Dẫn Kinh Quán Vô Lượng Thọ và Kinh Lăng Nghiêm."]},{"id":"mantra-dharani","title":"Thần chú và đà-la-ni","paragraphs":["Trong Mật tạng Đại thừa, Bồ Tát Đại Thế Chí có chân ngôn riêng được lưu truyền để hành giả thọ trì cầu gia hộ tăng trưởng trí tuệ và tiêu trừ ma chướng. Câu chân ngôn Phạn tự thường được ghi là: oṃ saṃ jaṃ jaṃ saḥ svāhā.","Tại Việt Nam, câu chân ngôn của Bồ Tát Đại Thế Chí được phiên âm theo tiếng Việt: “Ôm, sam giam giam xoa xoa-ha” (Âm Hán-Việt: “Án, tán nhẫm nhẫm tát sa-bà-ha”).","Công dụng của Chân ngôn Đại Thế Chí theo kinh điển: Giúp hành giả phá tan màn vô minh tăm tối, tăng cường định lực kiên cố trong công phu niệm Phật, hộ trì thân tâm không bị tà ma ngoại đạo quấy nhiễu và chiêu cảm ánh sáng trí tuệ vô biên của chư Phật gia bị.","Trong nghi thức tu tập Mật tông, việc trì tụng chân ngôn này được kết hợp với việc quán tưởng bảo bình phát quang trên đỉnh đầu Bồ Tát phóng ánh sáng vàng tử kim rót tràn vào đỉnh đầu hành giả, gạn lọc sạch sẽ mọi uế trược nơi thân, khẩu, ý.","Chân ngôn bổ trợ cho pháp môn niệm Phật, giúp hành giả nhiếp tâm vào Chánh niệm; nền tảng căn bản vẫn là sự chí thành, giữ gìn giới luật và nuôi dưỡng tâm khiêm hạ, từ bi."],"notes":["Phiên tự chân ngôn đối chiếu Mật tạng Chân Ngôn tông và hệ Mạn-đà-la Thai Tạng Giới."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Đại sư Ấn Quang (1861–1940), Tổ thứ mười ba của Tịnh Độ tông, suốt đời tự xưng là Thường Tàm Quý Tăng, không nhận đệ tử xuất gia, không trụ trì chùa lớn, chỉ chuyên niệm Phật và viết thư khuyên người tin sâu nhân quả, niệm Phật cầu sinh Tịnh Độ. Lời dạy của ngài nhấn mạnh đúng tinh thần chương Niệm Phật Viên Thông: thu nhiếp sáu căn, tịnh niệm nối nhau. Tập Kỷ Niệm Ấn Quang Đại Sư Vĩnh Tư Tập chép rằng: có một nữ sinh chưa từng học Phật mộng thấy Bồ Tát Quán Thế Âm bảo rằng Bồ Tát Đại Thế Chí đang ở Thượng Hải độ người, đó chính là Pháp sư Ấn Quang. Cô đến gặp và kể lại, Đại sư nghiêm giọng quở trách, dặn không được nói với ai. Mãi đến khi Đại sư viên tịch, chuyện ấy mới được thuật lại, và Phật tử đời sau tôn kính ngài là bậc ứng hiện của Bồ Tát Đại Thế Chí.","Năm 1940, tại chùa Linh Nham Sơn ở Tô Châu, Đại sư Ấn Quang biết trước ngày ra đi. Ngài dặn dò đại chúng giữ gìn đạo tràng, phải niệm Phật cầu sinh Tây Phương, rồi ngồi ngay ngắn hướng về phương Tây, giữa tiếng niệm Phật của đại chúng mà an tường thị tịch. Sau lễ trà tỳ, nhục thân để lại nhiều xá-lợi ngũ sắc. Cuộc đời và sự ra đi của ngài là minh chứng sống động cho lời Bồ Tát Đại Thế Chí: người nhớ Phật niệm Phật, hiện tiền hoặc tương lai nhất định thấy Phật.","Chính nhờ công hạnh hoằng truyền của Tổ thứ mười ba Tịnh Độ tông Ấn Quang Đại Sư, chương Đại Thế Chí Bồ Tát Niệm Phật Viên Thông được đưa vào hợp tuyển cùng Tứ Kinh Tịnh Độ thành “Tịnh Độ Ngũ Kinh Nhất Luận”. Trong các tuyển tập như Tịnh Độ Thánh Hiền Lục, nhiều bậc cao tăng và cư sĩ đời sau nương đúng tôn chỉ nhiếp lục căn của Đại Thế Chí mà hành trì suốt đời, khi lâm chung giữ được chánh niệm sáng suốt, an nhiên niệm Phật vãng sinh."],"notes":["Hành trạng Đại sư Ấn Quang đối chiếu Kỷ Niệm Ấn Quang Đại Sư Vĩnh Tư Tập và Ấn Quang Pháp Sư Văn Sao."]}],"references":["Kinh Thủ Lăng Nghiêm, quyển 5, chương Đại Thế Chí Bồ Tát Niệm Phật Viên Thông — HT Thích Trí Tịnh Việt dịch. Nguồn nguyên văn mục Đại nguyện.","Kinh Quán Vô Lượng Thọ Phật, phép quán thứ 11 về Bồ Tát Đại Thế Chí — Cương-lương-da-xá dịch, Đại Chính tạng số 365.","Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký — Đàm-vô-sấm dịch, Đại Chính tạng số 157.","Kỷ Niệm Ấn Quang Đại Sư Vĩnh Tư Tập — tư liệu hành trạng do môn đồ biên tập sau năm 1940.","Ấn Quang Pháp Sư Văn Sao — tập thư khai thị của Đại sư Ấn Quang."]},{"id":"dia-tang-vuong","name":"Địa Tạng Vương Bồ Tát","summary":"Địa Tạng Vương Bồ Tát (Kṣitigarbha) là vị Đại Bồ Tát của lòng Đại Nguyện sâu dày vô lượng: Địa ngục vị không, thệ bất thành Phật. Ngài là bậc U Minh Giáo Chủ xót thương cứu bạt muôn loài chúng sinh chịu khổ nơi cõi u đồ và dẫn dắt muôn loài thoát khỏi luân hồi sinh tử.","sections":[{"id":"than-the-tien-than","title":"Tiểu sử và bốn câu chuyện tiền thân","paragraphs":["Danh hiệu Địa Tạng trong tiếng Phạn là Kṣitigarbha: Địa là đất dày bền chắc, nâng đỡ và dung chứa muôn vật, tượng trưng cho tâm địa thanh tịnh và đức nhẫn nhục kiên cố; Tạng là kho báu vô tận, chứa đầy muôn vàn bảo vật công đức và trí tuệ để ban phát cho tất cả chúng sinh nghèo cùng khổ nạn. Ngài được xưng tán là U Minh Giáo Chủ, vâng lời phó chúc thiêng liêng của Đức Phật Thích Ca Mâu Ni nơi cung trời Đao Lợi, đảm nhận trọng trách giáo hóa chúng sinh cõi Ta Bà trong thời kỳ từ khi Đức Thế Tôn nhập diệt cho đến khi Bồ Tát Di Lặc giáng trần thành Phật.","Trong Kinh Địa Tạng Bồ Tát Bổn Nguyện do Đức Thế Tôn tuyên thuyết tại cung trời Đao Lợi để báo đáp thâm ân từ mẫu Hoàng hậu Ma-da, Đức Phật đã tuần tự kể lại bốn câu chuyện tiền thân cảm động sâu sắc làm nền tảng phát khởi đại thệ nguyện của Ngài:","Tiền thân thứ nhất là vị Trưởng giả tử: Trông thấy tướng mạo Đức Phật Sư Tử Phấn Tấn Cụ Túc Vạn Hạnh Như Lai ngàn phúc trang nghiêm đẹp đẽ vô cùng, Trưởng giả tử khởi tâm kính ngưỡng bèn thưa hỏi nguyên nhân. Phật dạy muốn chứng thân tướng ấy phải trải qua vô lượng kiếp cứu vớt chúng sinh chịu khổ. Trưởng giả tử liền đối trước Phật phát nguyện: Từ nay đến vô lượng kiếp sau, con vì tất cả chúng sinh chịu khổ trong sáu đường mà lập muôn ngàn phương tiện cứu vớt, khiến cho họ đều thoát khổ thành Phật rồi con mới thành Phật đạo.","Tiền thân thứ hai là người con gái dòng Bà-la-môn: Có mẹ tên là Duyệt-đế-lợi do túc nghiệp mê tín tà đạo, thường khinh chê Tam Bảo nên khi chết đọa vào địa ngục Vô Gián chịu muôn vàn hình phạt thiêu đốt. Người con gái chí hiếu bèn bán hết nhà cửa, mua sắm hương hoa sắm lễ cúng dường trước tháp tượng Đức Phật Giác Hoa Định Tự Tại Vương Như Lai, quỳ khóc ròng rã suốt một ngày một đêm. Nhờ lòng thành hiếu thảo chấn động cõi giới, nàng được Phật dẫn thần thức đến tận cửa địa ngục, thấy Quỷ vương Vô Độc đến chắp tay nghênh đón và báo tin rằng: Nhờ công đức chí hiếu và sự cúng dường của nàng, mẹ nàng cùng tất cả tội nhân trong ngục Vô Gián ngày hôm ấy đều đã được siêu thoát sinh lên cõi trời. Nàng liền đối trước tháp tượng Phật phát đại nguyện đời đời cứu bạt tội nhân chốn u minh.","Tiền thân thứ ba là vị Vua từ bi của một nước nhỏ: Kết bạn cùng vị vua nước láng giềng cùng tu mười điều thiện. Thấy muôn dân trong nước làm nhiều điều ác nghiệp, hai vua cùng phát nguyện cứu độ: một vị vua phát nguyện sớm thành Phật để giáo hóa nhân dân (sau thành tựu là Đức Phật Nhất Thiết Trí Thành Tựu Như Lai), còn vị vua kia phát nguyện cứu vớt muôn dân dứt sạch tội khổ rồi sau mới thành Phật (nay chính là Bồ Tát Địa Tạng).","Tiền thân thứ tư là nàng Quang Mục: Có mẹ mê ăn cá ba ba, ăn nhiều trứng cá sát hại vô số sinh mạng, khi chết đọa vào địa ngục chịu khổ cực hình. Nàng Quang Mục bán của cải vẽ tượng Đức Phật Thanh Tịnh Liên Hoa Mục Như Lai và chí thành cúng dường sám hối. Phật từ bi báo mộng cho biết mẹ nàng nhờ công đức ấy được tái sinh làm con của người tớ gái trong nhà, sinh ra mới được ba ngày đã biết nói, khóc lóc than rằng đời trước chịu khổ trong địa ngục, nay sinh làm kẻ hèn hạ lại mang nghiệp chết yểu năm mười ba tuổi. Thương xót người mẹ chí thân và muôn loài đau khổ, nàng Quang Mục đã đối trước hư không phát lời thề kinh thiên động địa: Nguyện cho mẹ con thoát hẳn địa ngục, và nguyện cho tất cả tội nhân trong ba đường ác nơi mười phương thế giới đều thoát khỏi khổ đau thành Phật rồi con mới thành bậc Chánh Giác."],"notes":["Bốn tiền thân đối chiếu Kinh Địa Tạng Bổn Nguyện, bản dịch của HT Thích Trí Tịnh."]},{"id":"nhan-duyen-phat-tam","title":"Nhân duyên phát tâm","paragraphs":["Bốn câu chuyện tiền thân trong Kinh Địa Tạng làm sáng tỏ cội nguồn sức mạnh tâm linh của Ngài: bắt đầu từ chữ Hiếu đối với cha mẹ trong gia đình, rồi mở rộng lòng hiếu thảo thiêng liêng ấy thành lòng Đại Hiếu và Đại Bi đối với tất cả chúng sinh trong muôn loài, xem mọi chúng sinh nhiều đời nhiều kiếp đều là cha mẹ ruột thịt của mình.","Lời dạy của Bồ Tát Địa Tạng chỉ rõ con đường tu tập vững chắc: muốn chuyển hóa nghiệp chướng sâu dày, người học Phật phải bắt đầu từ lòng hiếu thảo, biết ăn năn sám hối lỗi lầm, giữ gìn giới luật không sát hại sinh linh và rộng lòng bố thí cúng dường tạo phước lành.","Hình tượng tôn tượng Bồ Tát Địa Tạng với đầu tròn cạo tóc đắp y cà-sa tu sĩ, tay phải cầm tích trượng có sáu vòng kim loại biểu thị hạnh nguyện dùng âm thanh Chánh pháp đập tan cửa địa ngục thức tỉnh kẻ u mê, tay trái nâng viên như ý minh châu tỏa ánh sáng rực rỡ soi rọi tan biến bóng đêm u tối nơi cõi địa ngục ngạ quỷ.","Lời thệ nguyện “Địa ngục vị không, thệ bất thành Phật; chúng sinh độ tận, phương chứng Bồ-đề” thể hiện đỉnh cao của tâm đại bi vô ngã: Ngài tự nguyện gánh vác nơi tăm tối và khổ đau nhất trong ba cõi để làm điểm tựa cho những kẻ lầm đường lạc lối. Học theo tâm nguyện ấy, người tu tập không trốn tránh khó khăn hay ghét bỏ người lầm lỗi, mà biết dùng tình thương và sự kiên nhẫn để cảm hóa chính mình và những người chung quanh."],"notes":["Hình tượng và ý nghĩa tích trượng, minh châu theo truyền thống tạo tượng Bắc truyền."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Các đoạn trích dưới đây là lời nguyện trong bốn nhân duyên tu hành của Bồ Tát Địa Tạng, không phải toàn bộ kinh. Kinh Địa Tạng Bồ Tát Bổn Nguyện, phẩm 1: Thần Thông Trên Cung Trời Đao Lợi; phẩm 4: Nghiệp Cảm Của Chúng Sanh. Bản Việt dịch HT Thích Trí Tịnh, theo kinh văn đang lưu trong dự án.","Lời nguyện khi làm Trưởng Giả tử — phẩm 1:","Từ nay đến tột số chẳng thể kể xiết ở đời sau, tôi vì những chúng sanh tội khổ trong sáu đường mà giảng bày nhiều phương tiện làm cho chúng nó được giải thoát hết cả, rồi tự thân tôi mới chứng thành Phật Đạo","Lời nguyện của Thánh nữ Bà-la-môn — phẩm 1:","Tôi nguyện từ nay nhẫn đến đời vị lai những chúng sanh mắc phải tội khổ, thì tôi lập ra nhiều phương chước làm cho chúng đó được giải thoát","Lời nguyện khi làm vị vua — phẩm 4:","Như tôi chẳng trước độ những kẻ tội khổ làm cho đều đặng an vui chứng quả Bồ Đề, thời tôi nguyện chưa chịu thành Phật","Lời nguyện của Quang Mục cứu mẹ và cứu chúng sinh — phẩm 4:","'Nguyện cho thân mẫu tôi khỏi hẳn địa ngục khi mãn mười ba tuổi không còn có trọng tội cùng không còn đọa vào ác đạo nữa.","Xin chư Phật trong mười phương thương xót chứng minh cho tôi, vì mẹ mà tôi phát nguyện rộng lớn như vầy:","Như thân mẫu tôi khỏi hẳn chốn tam đồ và hạng hạ tiện cùng thân gái, cùng kiếp không còn thọ những quả báo xấu đó nữa, tôi đối trước tượng của đức Thanh Tịnh Liên Hoa Mục Như Lai mà phát lời nguyện rằng: Từ ngày nay nhẫn về sau đến trăm nghìn muôn ức kiếp, trong những thế giới nào mà các hàng chúng sanh bị tội khổ nơi địa ngục cùng ba ác đạo, tôi nguyện cứu vớt chúng đó làm cho tất cả đều thoát khỏi chốn ác đạo: địa ngục, súc sanh và ngạ quỉ, v.v...","Những kẻ mắc phải tội báo như thế thành Phật cả rồi, vậy sau tôi mới thành bậc Chánh Giác'."],"notes":[]},{"id":"loi-ich-niem-danh","title":"Công đức niệm danh hiệu","paragraphs":["Trong Kinh Địa Tạng Bổn Nguyện (phẩm thứ sáu và phẩm thứ mười hai), Đức Phật Thích Ca Mâu Ni đã tán thán công đức của Bồ Tát Địa Tạng trước toàn thể pháp hội trời người: nếu có người thiện nam thiện nữ nào trong đời hiện tại hoặc đời vị lai, nghe danh hiệu của Bồ Tát Địa Tạng, chiêm ngưỡng, đảnh lễ, ngợi khen, cúng dường hình tượng Ngài, thì người ấy sẽ được hưởng hai mươi tám điều lợi ích lớn lao.","Hai mươi tám điều lợi ích thù thắng ấy bao gồm: trời rồng thường theo ủng hộ, căn lành ngày càng tăng trưởng, tích lũy nhân duyên Bồ-đề sâu dày, áo cơm no đủ, không mắc các bệnh tật truyền nhiễm, khỏi nạn nước lửa cướp bóc, đêm ngủ không mộng mị hãi hùng, quỷ thần hộ trì, người thân quá vãng được siêu sinh cõi lành, và rốt ráo viên thành quả vị Phật đạo.","Khi trong gia đình có người thân đau ốm liệt giường hoặc lâm chung, Kinh Địa Tạng dạy người nhà nên vì người ấy lớn tiếng niệm danh hiệu Bồ Tát Địa Tạng, đem y phục tài vật của người bệnh cúng dường Tam Bảo hoặc in kinh tạo tượng hồi hướng, thì tội chướng của người bệnh được tiêu trừ, dẫu phải đọa đường ác cũng liền được giải thoát sinh về cõi trời người.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đại Nguyện Địa Tạng Vương Bồ Tát”."],"notes":["Dẫn Kinh Địa Tạng Bổn Nguyện, phẩm 6 và phẩm 12."]},{"id":"chan-ngon-da-la-ni","title":"Thần chú và đà-la-ni","paragraphs":["Trong pháp môn Địa Tạng, câu thần chú diệt định nghiệp được người tu học Phật giáo Bắc truyền thọ trì phổ biến là Địa Tạng Bồ Tát Diệt Định Nghiệp Chân Ngôn.","Câu chân ngôn được truyền tụng theo âm Hán-Việt: “Án, bát-ra mạt-ninh, đà-ninh, ta-bà-ha”.","Công dụng của Thần chú Diệt Định Nghiệp theo kinh điển: Khiến cho mọi tội lỗi ác nghiệp sâu dày tưởng chừng không thể lay chuyển (định nghiệp) của chúng sinh đều nương nhờ vào tha lực đại nguyện của Bồ Tát Địa Tạng và năng lực tự tâm sám hối mà được chuyển hóa tiêu trừ; giải tỏa các oan khiên oán kết nhiều đời, xua đuổi tà ma ám khí quấy phá gia đạo và mang lại sự an ổn tĩnh tại cho tâm hồn.","Truyền thống giải thích rằng định nghiệp tuy khó chuyển bởi quy luật nhân quả khắt khe, nhưng khi tâm niệm của hành giả hoàn toàn thay đổi từ tà ác sang chí thiện, dốc lòng nương tựa vào năng lực từ bi vô lượng của Bồ Tát Địa Tạng, thì dòng chảy nghiệp thức được tịnh hóa tận gốc rễ.","Khi trì tụng chân ngôn này, người học Phật cần kết hợp việc quán tưởng hình tượng Bồ Tát Địa Tạng tay nâng minh châu soi sáng cõi lòng, thành tâm sám hối lỗi lầm xưa và thề nguyện từ nay về sau không tái phạm việc ác hại người."],"notes":["Đối chiếu Địa Tạng Bồ Tát Diệt Định Nghiệp Chân Ngôn trong các nghi quỹ Tịnh Độ và Thủy Lục Chư Thiên."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Theo Tống Cao Tăng Truyện (quyển 20) và Cửu Hoa Sơn Chí, ngài Kim Kiều Giác (696–794) vốn là vương tử nước Tân La (nay thuộc bán đảo Triều Tiên). Ngài xả bỏ vinh hoa, xuất gia, vượt biển sang Trung Hoa đời Đường và chọn núi Cửu Hoa (tỉnh An Huy) làm nơi tu hành. Ngài sống khổ hạnh trong hang đá, ăn uống đạm bạc, có lúc chỉ dùng cơm trộn đất trắng. Dân làng cảm phục đức hạnh, cùng nhau cúng đất dựng chùa, từ đó Cửu Hoa trở thành một đạo tràng lớn.","Năm chín mươi chín tuổi, ngài Kim Kiều Giác gọi đồ chúng đến từ biệt rồi ngồi kiết già thị tịch. Thân ngài được đặt trong khám đá; ba năm sau mở ra, nhục thân vẫn nguyên vẹn, sắc mặt như lúc còn sống, khi di chuyển các đốt xương phát ra tiếng như ngọc khua. Căn cứ kinh điển nói Bồ Tát Địa Tạng an trụ như đất, chứa nhóm như kho báu, Phật tử đời sau tôn ngài là ứng thân của Bồ Tát Địa Tạng, xây tháp thờ nhục thân. Núi Cửu Hoa từ đó trở thành một trong Tứ đại danh sơn của Phật giáo Trung Hoa, đạo tràng của Bồ Tát Địa Tạng.","Trong Kinh Địa Tạng Bồ Tát Bổn Nguyện (phẩm 13: Chúc Lụy Nhân Thiên), Đức Phật Thích Ca Mâu Ni dặn dò Bồ Tát Quán Thế Âm và hàng trời người rằng: nếu có thiện nam tín nữ thấy hình tượng, nghe kinh điển và chí thành lễ bái xưng niệm danh hiệu Bồ Tát Địa Tạng, thì sẽ thành tựu hai mươi tám điều lợi ích thiết thực như được thiên long hộ niệm, thiện căn ngày càng tăng trưởng, bệnh tật và tai nạn dần tiêu trừ, gia đạo bình an và không bị thủy hỏa xâm hại. Lời kinh ấy trở thành nền tảng cho các đàn tràng Địa Tạng cầu siêu và cầu an qua nhiều thế hệ.","Sách Địa Tạng Bồ Tát Bản Tích Linh Cảm Lục (đang lưu trong thư viện ứng dụng) chép sự tích Vương Ký thoát nạn đắm thuyền đời Đường: tại chùa Thiện Tịch ở Hán Châu có bức họa Bồ Tát Địa Tạng do danh họa Trương Tăng Dao đời Lương vẽ, thường tỏa ánh sáng lạ. Năm Lân Đức thứ ba, quan Tư Châu thứ sử Vương Ký vẽ lại bức tượng ấy để thành tâm phụng thờ. Khi đoàn mười chiếc thuyền cùng đi nhậm chức gặp cơn cuồng phong bão lớn, chín chiếc bị đắm, duy chỉ thuyền của Vương Ký bình yên vô sự.","Cũng trong Địa Tạng Bồ Tát Bản Tích Linh Cảm Lục có chuyện cô giáo Tào Tông Thanh (hiệu Tuyết Tài) ở huyện Ngô: mẹ nàng ngoài bảy mươi tuổi mắc bệnh phù thũng nặng (chứng khí hư trung mãn), thầy thuốc đều bó tay. Nàng lập tức phát nguyện ăn chay, chí thành tụng ba mươi bộ Kinh Địa Tạng Bồ Tát Bổn Nguyện hồi hướng cầu cho mẹ. Đến ngày tụng viên mãn, bệnh phù của mẹ nàng bỗng thuyên giảm rõ rệt, ăn uống trở lại bình thường và sống khỏe mạnh thêm nhiều năm."],"notes":["Hành trạng ngài Kim Kiều Giác đối chiếu Tống Cao Tăng Truyện quyển 20 và Cửu Hoa Sơn Chí."]}],"references":["Kinh Địa Tạng Bồ Tát Bổn Nguyện, trọn bộ 13 phẩm — HT Thích Trí Tịnh Việt dịch. Nguồn nguyên văn của mục Đại nguyện và bốn câu chuyện tiền thân.","Thủy Lục Nghi Quỹ: khoa nghi cúng dường U Minh Giáo Chủ Địa Tạng Vương Bồ Tát.","Tống Cao Tăng Truyện, quyển 20: truyện Kim Địa Tạng — Tán Ninh soạn, Đại Chính tạng tập 50, số 2061.","Cửu Hoa Sơn Chí — ghi chép lịch sử đạo tràng Bồ Tát Địa Tạng tại Cửu Hoa Sơn.","Kinh Địa Tạng Bồ Tát Bổn Nguyện, phẩm 13: Chúc Lụy Nhân Thiên — HT Thích Trí Tịnh Việt dịch.","Địa Tạng Bồ Tát Bản Tích Linh Cảm Lục — bản đang có trong thư viện của ứng dụng."]},{"id":"van-thu-su-loi","name":"Văn Thù Sư Lợi Bồ Tát","summary":"Văn Thù Sư Lợi Bồ Tát (Mañjuśrī) là vị Đại Bồ Tát biểu trưng cho Căn Bản Trí Bát-nhã vô thượng, bậc Thầy trí tuệ của chư Phật ba đời. Ngài ngồi trên sư tử xanh dũng mãnh, tay cầm gươm báu Bát-nhã chặt đứt mọi lưới nghi vô minh phiền não của chúng sinh.","sections":[{"id":"than-the","title":"Tiểu sử và biểu tượng Đại Trí","paragraphs":["Danh hiệu Văn Thù Sư Lợi trong tiếng Phạn là Mañjuśrī, dịch nghĩa là Diệu Đức, Diệu Cát Tường hoặc Diệu Âm: Diệu là trí tuệ Bát-nhã mầu nhiệm vượt khỏi mọi phân biệt đối đãi của phàm phu; Đức là muôn vạn phúc đức trang nghiêm tròn đầy viên mãn. Trong kinh điển Đại thừa, Ngài được tôn xưng là Mẫu Thân của chư Phật ba đời, bởi vì tất cả chư Phật trong quá khứ, hiện tại và vị lai đều nương nơi trí tuệ Bát-nhã Ba-la-mật thâm sâu mà thành tựu đạo quả Vô Thượng Chánh Đẳng Chánh Giác.","Trong Kinh Bi Hoa (phẩm Chư Bồ Tát Bổn Thọ Ký), tiền thân của Bồ Tát Văn Thù là Vương tử Vương Chúng, con trai thứ ba của vua Vô Tranh Niệm (tiền thân Phật A Di Đà). Đối trước Đức Phật Bảo Tạng, Vương tử phát khởi đại thệ nguyện sâu dày: Nguyện con đời đời kiếp kiếp thực hành Bồ Tát đạo, giáo hóa vô lượng vô biên chúng sinh khiến cho họ đều phát Bồ-đề tâm và thành tựu Phật quả trước con, khi tất cả chúng sinh hữu duyên đều đã thành Phật viên mãn rồi con mới thành bậc Chánh Giác. Đức Phật Bảo Tạng khen ngợi và thọ ký cho Vương tử danh hiệu Văn Thù Sư Lợi, đời sau sẽ thành Phật nơi thế giới Thanh Tịnh ở phương Nam với tôn hiệu Phổ Hiện Như Lai.","Hình tượng tôn tượng Bồ Tát Văn Thù Sư Lợi trong nghệ thuật Phật giáo mang đầy ý nghĩa biểu pháp thâm sâu: Ngài hiện thân đồng tử thanh tú đắp y báu, ngồi kiết già trên lưng con sư tử xanh dũng mãnh gầm vang biểu thị oai lực của trí tuệ quét sạch mọi tà thuyết ngoại đạo; tay phải giương cao thanh gươm báu Bát-nhã rực lửa biểu thị năng lực chặt đứt tận gốc rễ lưới nghi vô minh phiền não; tay trái cầm cành hoa sen xanh nâng pho kinh Bát Nhã Ba La Mật Đa biểu trưng cho nguồn tuệ giác thanh tịnh không nhiễm bụi trần.","Tại Trung Hoa, đạo tràng hiển linh nổi tiếng nhất của Bồ Tát Văn Thù là rặng núi Ngũ Đài Sơn (Thanh Lương Sơn) ở tỉnh Sơn Tây, nơi quanh năm mây lành bao phủ và ghi dấu muôn vàn sự tích cảm ứng mầu nhiệm của Ngài hóa thân độ hóa nhân thiên."],"notes":["Ý nghĩa danh hiệu và biểu tượng y cứ Kinh Văn Thù Sư Lợi Bát Nhã và Kinh Hoa Nghiêm; tiền thân Vương tử Vương Chúng y cứ Kinh Bi Hoa."]},{"id":"nhan-duyen-phat-tam","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Đại Bảo Tích, Bồ Tát Văn Thù Sư Lợi thuở quá khứ từng là một vị Chuyển luân Thánh vương tên là Dũng Mãnh Đức, đã cúng dường chư Phật và phát Bồ-đề tâm sâu sắc. Trong Kinh Pháp Hoa (phẩm Tựa thứ nhất), Ngài là vị Bồ Tát cổ đức từng làm thầy của tám vị vương tử của Đức Phật Nhật Nguyệt Đăng Minh, trong đó vị vương tử cuối cùng thành Phật chính là Đức Phật Nhiên Đăng, bậc thầy thọ ký cho Đức Phật Thích Ca Mâu Ni.","Tâm nguyện ban đầu của Bồ Tát Văn Thù là dùng ngọn đuốc trí tuệ xé toạc màn đêm vô minh tăm tối, dẫn dắt chúng sinh nhận ra tánh Không của vạn pháp để dứt trừ chấp ngã, chấp pháp. Người học Phật khi quy kính Bồ Tát Văn Thù không chỉ cầu xin sự thông minh chữ nghĩa thế tục, mà chính là khát khao khai mở tuệ giác Bát-nhã nơi tự tâm để nhìn rõ bản chất cuộc đời và sống đời an nhiên tự tại.","Đặc biệt, Kinh Thủ Lăng Nghiêm Tam Muội tiết lộ rằng từ vô lượng A-tăng-kỳ kiếp về trước, Bồ Tát Văn Thù Sư Lợi đã từng thành Phật tại thế giới Bình Đẳng, tôn hiệu là Đức Long Chủng Thượng Tôn Vương Như Lai. Vì lòng đại bi muốn làm bậc trợ hóa cho chư Phật mười phương giáo hóa chúng sinh, Ngài ẩn quả vị Phật mà thị hiện làm Bồ Tát Pháp Vương Tử, được kinh điển Đại thừa tôn xưng là bậc “thầy của chư Phật”."],"notes":["Dẫn Kinh Đại Bảo Tích và Kinh Pháp Hoa phẩm Tựa."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Đại nguyện của Bồ Tát Văn Thù Sư Lợi trong Kinh Bi Hoa là thệ nguyện giáo hóa muôn loài thành Phật trước bản thân mình: “Nếu có chúng sinh nào ở mười phương thế giới, nghe danh hiệu con, thấy thân hình con, cho đến nghe lời nói của con, mà chưa phát Bồ-đề tâm, chưa đoạn trừ phiền não si mê, thì con thề quyết không thành Phật”.","Trong Kinh Hoa Nghiêm (phẩm Nhập Pháp Giới thứ 39), Bồ Tát Văn Thù là bậc đạo sư đầu tiên chỉ dẫn cho Thiện Tài đồng tử lên đường cầu đạo trải qua năm mươi ba chặng tham vấn các bậc thiện tri thức; đồng thời chính Ngài là người phát lời nguyện tha thiết vãng sinh về cõi Tây Phương Cực Lạc của Đức Phật A Di Đà để mau viên thành Phật quả:","“Nguyện con lúc lâm chung\\nDứt trừ mọi chướng ngại\\nTận mặt thấy Di Đà\\nLiền sinh cõi Cực Lạc.\\nĐã sinh cõi kia rồi\\nHiện tiền thành đại nguyện\\nDi Đà thọ ký xong\\nLàm lợi ích muôn loài.”","Ngoài lời nguyện trong Kinh Bi Hoa và kệ vãng sinh, bản Kinh Văn Thù Sư Lợi Phát Nguyện (do ngài Phật-đà-bạt-đà-la dịch đời Đông Tấn) ghi lại hệ thống nguyện lực thực tiễn gồm giữ thân khẩu ý thanh tịnh, chí thành sám hối nghiệp chướng, tùy hỷ mọi công đức của thánh phàm và hồi hướng trọn vẹn cho tất cả chúng sinh đồng chứng Vô Thượng Chánh Đẳng Chánh Giác."],"notes":["Lời nguyện vãng sinh trích Kinh Hoa Nghiêm, phẩm Phổ Hiền Hạnh Nguyện (Đại Chính tạng T293)."]},{"id":"loi-ich-niem-danh","title":"Công đức niệm danh hiệu","paragraphs":["Trong các kinh điển Đại thừa, xưng niệm danh hiệu Bồ Tát Văn Thù Sư Lợi mang lại công đức vô lượng: giúp tiêu trừ chướng ngại học vấn, dẹp tan những hoài nghi si ám trong tâm, khai thông trí nhớ và tăng trưởng định tuệ thâm sâu.","Đối với người học trò, học tăng, hành giả nghiên tầm kinh điển Đại thừa, việc chí thành lễ bái và xưng niệm danh hiệu Ngài trước khi đọc kinh tọa thiền giúp tâm trí trở nên sáng suốt, dễ dàng thấu triệt những nghĩa lý thâm sâu vi diệu của Phật pháp.","Trong đời sống thường nhật, thực hành hạnh Văn Thù là tập dừng lại quán chiếu trước những cơn sân hận, định kiến hay sự vội vã phán xét; dùng “gươm trí tuệ” nhận rõ tính vô thường, duyên sinh của mọi việc để tâm trở nên sáng suốt, điềm tĩnh và bao dung hơn.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đại Trí Văn Thù Sư Lợi Bồ Tát”."],"notes":["Dẫn các nghi thức khai kinh và sám pháp Văn Thù."]},{"id":"chan-ngon-lien-he","title":"Thần chú và đà-la-ni","paragraphs":["Chân ngôn gắn liền với Bồ Tát Văn Thù Sư Lợi được truyền tụng rộng rãi nhất trong Mật tông Tây Tạng và Đông Mật là Văn Thù Ngũ Tự Chân Ngôn (A-RA-PA-CA-NA). Bản phiên tự Phạn văn là: oṃ a ra pa ca na dhīḥ.","Câu chân ngôn được trì tụng theo âm Hán-Việt truyền thống: “Án a-ra-ba-giá-na-đế” (hoặc đọc theo âm chuẩn: “Ôm, a ra pa cha na đi-hi”).","Công dụng của Chân ngôn Văn Thù theo kinh điển: Có năng lực phá tan bóng tối si ám ngàn đời, khai mở trí tuệ Bát-nhã sáng suốt, tăng cường khả năng ghi nhớ kinh điển (tổng trì đà-la-ni), giúp hành giả thông đạt nghĩa lý sâu xa của chư Phật và dứt sạch các tạp niệm xao động nơi tâm.","Năm âm A, RA, PA, CA, NA trong kinh điển tượng trưng cho năm cửa ngõ giải thoát thâm sâu của giáo lý tánh Không: A biểu thị vạn pháp vốn xưa nay bất sinh; RA biểu thị lìa xa mọi trần cấu; PA biểu thị đệ nhất nghĩa đế tối thắng; CA biểu thị muôn pháp không sinh không diệt; NA biểu thị bản chất các pháp lìa xa danh tướng.","Khi trì tụng âm cuối cùng Dhīḥ, hành giả kéo dài âm thanh một cách thanh thoát và quán tưởng luồng ánh sáng màu vàng cam từ bảo kiếm của Bồ Tát rót vào tâm trí, xua tan mọi mờ mịt phiền não."],"notes":["Đối chiếu Kim Cang Đỉnh Du Già Văn Thù Sư Lợi Bồ Tát Kinh (T1171)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích Bần nữ cúng tóc và Tháp Phát được lưu truyền trong Thanh Lương Sơn Chí: vào thời Bắc Ngụy, chùa ở Ngũ Đài Sơn mỗi năm mở đại trai đàn vô già, cúng dường bình đẳng cho mọi người. Một hôm có người phụ nữ nghèo bồng con, dắt theo một con chó đến xin ăn. Vì không có gì cúng dường, bà cắt một lọn tóc dâng lên rồi xin phần cơm cho mình, cho đứa con, cho con chó, và cả cho thai nhi trong bụng. Vị sư phụ trách trai đường bực bội quở rằng thai nhi chưa sinh thì sao ăn được. Lời vừa dứt, người phụ nữ bay lên hư không, hiện thân Bồ Tát Văn Thù cưỡi sư tử xanh, con chó hóa thành sư tử, đứa trẻ hóa thành đồng tử, và để lại bài kệ nhắc nhở rằng tâm phân biệt sang hèn chính là gốc của khổ đau. Đại chúng hối hận sám hối, dựng tháp cất giữ lọn tóc, gọi là Tháp Phát. Sự tích dạy bài học bố thí bình đẳng, không phân biệt người giàu kẻ nghèo.","Sự tích ngài Phật Đà Ba Lợi được chép trong lời tựa Kinh Phật Đảnh Tôn Thắng Đà La Ni (Đại Chính tạng số 967) và Tống Cao Tăng Truyện (quyển 2): năm 676 đời Đường, ngài Phật Đà Ba Lợi, người nước Kế Tân, vượt đường xa đến Ngũ Đài Sơn mong được chiêm bái Bồ Tát Văn Thù. Đến chân núi, ngài năm vóc gieo xuống đất đảnh lễ, rơi lệ khẩn cầu. Bỗng có một ông lão từ trong núi đi ra, hỏi ngài có mang theo Kinh Phật Đảnh Tôn Thắng Đà La Ni để cứu độ chúng sinh nhiều tội nghiệp nơi đây không; nếu không mang kinh đến thì dù gặp cũng không nhận ra Văn Thù. Ngài cúi lạy, ngẩng lên thì ông lão đã biến mất. Ngài liền trở về Thiên Trúc thỉnh bản kinh, rồi mang sang Trường An năm 683 để dịch và lưu truyền. Thần chú Phật Đảnh Tôn Thắng từ đó được tụng đọc rộng khắp các nước Phật giáo Bắc truyền.","Ngoài sự tích ngài Phật Đà Ba Lợi, bộ Thanh Lương Sơn Chí còn ghi chép nhiều thoại tích tại đạo tràng Ngũ Đài Sơn — nơi chư tăng và hành giả tìm về chiêm bái Bồ Tát Văn Thù. Các tích chuyện ấy đều nhấn mạnh một điểm chung: khi người tu giữ tâm thanh tịnh, buông bỏ chấp trước hơn thua thì dễ dàng cảm ứng với trí tuệ sáng suốt nơi tự tâm và nhận được sự khai ngộ đúng lúc trên đường tu học."],"notes":["Truyện Bần nữ cúng tóc đối chiếu Thanh Lương Sơn Chí; truyện Phật Đà Ba Lợi đối chiếu lời tựa Kinh Phật Đảnh Tôn Thắng Đà La Ni (T967) và Tống Cao Tăng Truyện quyển 2."]}],"references":["Kinh Diệu Pháp Liên Hoa, phẩm Tựa thứ nhất — HT Thích Trí Tịnh Việt dịch.","Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký — Đàm-vô-sấm Hán dịch; Đại Chính tạng số 157.","Kinh Hoa Nghiêm, phẩm Phổ Hiền Hạnh Nguyện — Bát Nhã dịch, Đại Chính tạng số 293. Nguồn nguyên văn kệ vãng sinh Cực Lạc.","Thanh Lương Sơn Chí — ghi chép lịch sử đạo tràng Bồ Tát Văn Thù tại Ngũ Đài Sơn.","Kinh Phật Đảnh Tôn Thắng Đà La Ni, lời tựa của Chí Tĩnh — Phật Đà Ba Lợi dịch, Đại Chính tạng số 967.","Kinh Thủ Lăng Nghiêm Tam Muội — Cưu-ma-la-thập Hán dịch, Đại Chính tạng số 642.","Kinh Văn Thù Sư Lợi Phát Nguyện — Phật-đà-bạt-đà-la Hán dịch, Đại Chính tạng số 296."]},{"id":"pho-hien","name":"Phổ Hiền Bồ Tát","summary":"Bồ Tát Phổ Hiền (Samantabhadra) là vị Đại Bồ Tát biểu trưng cho Đại Hạnh và Lý Đức tối cao, bậc Thầy của mười đại nguyện vương dẫn lối muôn loài quy hướng cõi Cực Lạc. Ngài ngồi trên thớt voi trắng sáu ngà dũng mãnh kiên cố, tiêu biểu cho lục độ Ba-la-mật viên thành.","sections":[{"id":"than-the","title":"Tiểu sử và biểu tượng Đại Hạnh","paragraphs":["Danh hiệu Phổ Hiền trong tiếng Phạn là Samantabhadra: Phổ nghĩa là biến khắp cùng hư không pháp giới, không nơi nào không cùng khắp; Hiền nghĩa là đẳng thuận từ bi, trọn vẹn đức hạnh thanh tịnh cao quý nhất. Bồ Tát Phổ Hiền là vị Đại Bồ Tát đại diện cho Đại Hạnh (hành động, thực hành Bồ Tát đạo vô biên) và Lý Đức (bản thể chân như thanh tịnh), cùng với Bồ Tát Văn Thù Sư Lợi đại diện cho Đại Trí hợp thành hai vị thị giả tả hữu của Đức Bổn Sư Thích Ca Mâu Ni Phật, gọi là Hoa Nghiêm Tam Thánh.","Theo Kinh Bi Hoa (phẩm Chư Bồ Tát Bổn Thọ Ký), tiền thân của Bồ Tát Phổ Hiền là Vương tử Năng Đạt Nhất Thiết Quân Bảo, con trai thứ tám của vua Vô Tranh Niệm (tiền thân Phật A Di Đà). Vâng lời vua cha khuyên bảo, Vương tử đã đối trước Đức Phật Bảo Tạng phát đại thệ nguyện sâu dày: Nguyện con trong đời vị lai thực hành vô lượng hạnh lành thanh tịnh, trang nghiêm tất cả các cõi Phật mười phương, dắt dẫn chúng sinh lìa khổ được vui, cứu vớt kẻ trầm luân không lúc nào ngơi nghỉ. Đức Phật Bảo Tạng thọ ký cho Vương tử tôn hiệu Phổ Hiền, đời sau sẽ thành Phật nơi cõi Tri Thừa ở phương Bắc với tôn hiệu Trí Thắng Đức Như Lai.","Hình tượng tôn tượng Bồ Tát Phổ Hiền trong Phật giáo Bắc truyền mang tính biểu pháp vô cùng trang nghiêm hùng vĩ: Ngài ngự trên lưng một thớt voi chúa trắng có sáu ngà nhọn hoắt. Thớt voi trắng biểu trưng cho tâm Bồ-đề thanh tịnh, sức chịu đựng kham nhẫn kiên cố dũng mãnh vượt qua mọi chông gai hiểm nạn; sáu ngà voi nhọn biểu trưng cho sáu pháp Ba-la-mật (Bố thí, Trì giới, Nhẫn nhục, Tinh tấn, Thiền định, Trí tuệ) phá tan mọi ma chướng sinh tử; trên tay Ngài nâng cành hoa sen báu hoặc ngọc như ý phát ra ánh quang minh dịu dàng soi sáng muôn loài.","Đạo tràng hiển linh nổi tiếng nhất của Bồ Tát Phổ Hiền là núi Nga Mi Sơn ở tỉnh Tứ Xuyên (Trung Quốc), một trong Tứ đại danh sơn thiêng liêng nơi ghi nhận muôn vàn hiện tượng cảm ứng màu nhiệm như Phật Quang Nga Mi và Thánh Đăng cúng dường."],"notes":["Ý nghĩa danh hiệu và biểu tượng voi trắng sáu ngà y cứ Kinh Pháp Hoa phẩm Phổ Hiền Khuyến Phát; tiền thân y cứ Kinh Bi Hoa."]},{"id":"bon-nguyen","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Đại Phương Quảng Phật Hoa Nghiêm, phẩm Nhập Pháp Giới thứ 39, Bồ Tát Phổ Hiền là bậc Đại Bồ Tát thượng thủ viên mãn đại hạnh nguyện rộng lớn không thể nghĩ bàn. Ngài chỉ dạy cho thiện nam tử Thiện Tài đồng tử sau khi đã đi qua năm mươi ba chặng đường tham học khắp mười phương, cuối cùng phải quy hướng về Mười Đại Hạnh Nguyện Vương để thâm nhập Pháp thân thanh tịnh của chư Phật.","Bồ-đề tâm ban đầu của Bồ Tát Phổ Hiền thể hiện ở tinh thần dấn thân bất tận: Hư không giới có cùng tận, chúng sinh giới có cùng tận, chúng sinh nghiệp có cùng tận, chúng sinh phiền não có cùng tận, nhưng hạnh nguyện và công phu tu tập của Ngài quyết không bao giờ cùng tận; niệm niệm nối tiếp không gián đoạn, thân khẩu ý không hề mệt mỏi.","Trong Kinh Diệu Pháp Liên Hoa (phẩm 28: Phổ Hiền Bồ Tát Khuyến Phát), khi Đức Phật sắp nói xong bộ kinh, Bồ Tát Phổ Hiền từ phương Đông cưỡi voi trắng sáu ngà cùng vô lượng quyến thuộc đến hội Linh Sơn, phát nguyện hộ trì và bảo vệ những ai thọ trì, đọc tụng, biên chép Kinh Pháp Hoa trong đời ngũ trược sau khi Phật diệt độ, giúp họ không bị ma chướng khuấy nhiễu."],"notes":["Trích Kinh Hoa Nghiêm, phẩm Nhập Pháp Giới (Đại Chính tạng T279 và T293)."]},{"id":"muoi-dai-hanh-nguyen","title":"Đại nguyện","paragraphs":["Nguyên văn phần mười hạnh nguyện và lời giảng từng hạnh nguyện trong Kinh Đại Phương Quảng Phật Hoa Nghiêm, phẩm Nhập Bất Tư Nghì Giải Thoát Cảnh Giới Phổ Hiền Hạnh Nguyện — HT Thích Trí Tịnh Việt dịch. Trích bản kinh đang có trong thư viện của ứng dụng, từ lời Bồ Tát Phổ Hiền nói với Thiện Tài đến hết phần xác nhận mười điều nguyện lớn đầy đủ viên mãn.","Lúc bấy giờ ngài Phổ Hiền đại Bồ Tát khen ngợi công đức thù thắng của đức Như Lai rồi, bèn bảo các vị Bồ Tát và Thiện Tài rằng: “Này Thiện Nam Tử! Công đức của Như Lai, giả sử cho tất cả các đức Phật ở mười phương, trải qua số kiếp nhiều như cực vi trần trong bất khả thuyết bất khả thuyết cõi Phật diễn nói không ngừng, cũng không thể trọn hết được.","Nếu ai muốn trọn nên công đức của Phật, thời phải tu mười điều hạnh nguyện rộng lớn. Những gì là mười điều?","Một là kính lễ các đức Phật.","Hai là khen ngợi đức Như Lai.","Ba là rộng sắm đồ cúng dường.","Bốn là sám hối các nghiệp chướng.","Năm là tùy hỉ các công đức.","Sáu là thỉnh đức Phật thuyết pháp.","Bảy là thỉnh đức Phật ở lại đời.","Tám là thường học tập theo Phật.","Chín là hằng thuận lợi chúng sanh.","Mười là hồi hướng khắp tất cả.","Thiện Tài bạch rằng: “Ðại Thánh! Lễ kính như thế nào? cho đến hồi hướng như thế nào?”.","Phổ Hiền Bồ Tát bảo Thiện Tài rằng: “Này thiện nam tử! Nói “Lễ kính các đức Phật” là như vầy:","Bao nhiêu các đức Phật Thế Tôn nhiều như số cực vi trần trong cõi Phật khắp pháp giới hư không giới mười phương ba đời, tôi do nơi hạnh nguyện của Phổ Hiền thâm tâm tín giải như đối trước mắt, đều dùng thân, khẩu, ý ba nghiệp thanh tịnh thường tu hạnh lễ kính. Nơi mỗi đức Phật đều hóa hiện thân nhiều như số cực vi trần trong bất khả thuyết cõi Phật. Mỗi thân đều khắp lễ kính các đức Phật nhiều như số cực vi trần trong bất khả thuyết bất khả thuyết cõi Phật. Cõi hư không kia hết, sự lễ kính của tôi mới hết. Nhưng cõi hư không chẳng cùng tận nên sự lễ kính của tôi cũng không cùng tận. Nhẫn đến cõi chúng sanh hết, nghiệp chúng sanh hết, phiền não chúng sanh hết, sự lễ kính của tôi mới dứt. Nhưng cõi chúng sanh cho đến phiền não chẳng hết, nên sự lễ kính của tôi cũng không cùng tận, niệm niệm nối luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Khen ngợi đức Như Lai” là như vầy:","Bao nhiêu số cực vi trần trong cõi nước khắp cùng hư không pháp giới mười phương ba đời, trong mỗi cực vi đều có các đức Phật nhiều như số cực vi trong tất cả thế gian.\xA0 Nơi mỗi đức Phật, đều có rất đông Bồ Tát vây quanh nhóm họp. Tôi phải trọn dùng sức thậm thâm thắng giải tri kiến hiện tiền, đều dùng lưỡi vi diệu hơn Biện Tài Thiên Nữ. Mỗi lưỡi phát xuất vô tận âm thinh hải. Mỗi âm thinh phát xuất tất cả ngôn từ hải,\xA0 khen ngợi các công đức hải của tất cả đức Như Lai, ca ngợi đến tột đời vị lai nối luôn không dứt, khắp cả pháp giới, không sót chỗ nào. Như vậy hư không giới, chúng sanh giới, chúng sanh nghiệp, chúng sanh phiền não đều hết, thời sự khen ngợi công đức chư Phật của tôi đây mới cùng tận. Nhưng cõi hư không kia cho đến phiền não của chúng sanh chẳng cùng tận, nên sự khen ngợi của tôi cũng không cùng tận, nên sự khen ngợi của tôi cũng không cùng tận, niệm niệm nối luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Rộng sắm đồ cúng dường” là như vầy:","Bao nhiêu số vi trần trong khắp cõi Phật cùng hư không pháp giới mười phương ba đời, trong mỗi cực vi trần đều có chư Phật như số cực vi trong tất cả thế giới, nơi mỗi đức Phật có vô số Bồ Tát vây quanh nhóm họp. Tôi dùng sức hạnh nguyện của Ngài Phổ Hiền mà khởi lòng tín giải rất sâu và hiện tiền tri kiến, đều đem đồ cúng dường thượng diệu mà cúng dường pháp hội của Phật. Như là mây hoa, mây tràng hoa, mây âm nhạc cõi trời, mây tàn lọng cõi trời, mây y phục cõi trời, các thứ hương trời: hương xoa, hương đốt, hương bột. Các thứ mây trên đây thảy đều nhiều lớn như núi Tu Di. Lại thắp các thứ đèn, đèn tô lạc, đèn dầu, các thứ đèn dầu thơm mỗi tim đèn lớn như núi Tu Di, dầu trong đèn như nước bể cả. Ðem các thứ đồ cúng dường như trên để thường cúng dường.","Thiện nam tử! Trong các thứ cúng dường, pháp cúng dường là hơn hết. Pháp cúng dường là: Tu hành đúng theo lời Phật dạy để cúng dường, làm lợi ích cho chúng sanh để cúng dường, chịu khổ thế cho chúng sanh để cúng dường, nhiếp thọ chúng sanh để cúng dường, siêng năng tu tập căn lành để cúng dường, không bỏ hạnh Bồ Tát để cúng dường, chẳng rời tâm Bồ Ðề để cúng dường.","Thiện nam tử! Như vô lượng công đức của sự cúng dường trước kia sánh với một niệm công đức của pháp cúng dường, thời không bằng một phần trăm, không bằng một phần ngàn, không bằng một phần trăm ngàn, cu chi na do tha, một phần ca la, một phần toán, một phần số, một phần dụ, cũng chẳng bằng một phần ưu ba ni sa đà. Vì sao? Vì các đức Như Lai tôn trọng chánh Pháp. Vì theo đúng như lời Phật dạy mà tu hành thì sanh ra các đức Phật. Nếu các Bồ Tát thật hành pháp cúng dường, thì trọn nên sự cúng dường Phật. Tu hành như vậy mới thật là sự cúng dường. Nên Pháp cúng dường là sự cúng dường rộng lớn hơn tất cả. Cõi hư không cùng tận cõi chúng sanh cùng tận, nghiệp chúng sanh cùng tận, phiền não chúng sanh cùng tận, sự cúng dường của tôi mới cùng tận, nhưng cõi hư không cho đến phiền não chẳng cùng tận nên sự cúng dường của tôi cũng không cùng tận, niệm niệm nối luôn không hở, thân, khẩu, ý nghiệp không hề nhàm mỏi.","Lại này thiện nam tử! Nói “Sám hối nghiệp chướng” là như vầy:","Bồ Tát tự nghĩ rằng: Tôi từ vô thỉ kiếp về qúa khứ, do lòng tham lam, giận dữ, ngu si khiến thân, khẩu, ý tạo vô lượng vô biên nghiệp ác. Nếu các nghiệp ác này mà có hình tướng, thì khắp cõi hư không cũng chẳng thể đựng chứa hết được. Nay tôi đem trọn cả ba nghiệp trong sạch đối trước các đức Phật và chúng Bồ Tát khắp cực vi trần cõi nước trong Pháp giới, thành tâm sám hối, về sau không tái phạm nữa, thường an trụ nơi giới pháp trong sạch đầy đủ công đức lành. Như vậy hư không giới cùng tận, chúng sanh giới cùng tận, chúng sanh nghiệp cùng tận, chúng sanh phiền não cùng tận, thì sự sám hối của tôi mới cùng tận, nhưng hư không giới cho đến chúng sanh phiền não chẳng cùng tận, nên sự sám hối của tôi đây cũng không cùng tận, niệm niệm nối luôn không hở thân, khẩu, ý ba nghiệp không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Tùy hỉ công đức” là như vầy:","Bao nhiêu đức Phật như số vi trần trong tất cả cõi Phật khắp hư không pháp giới mười phương ba đời, từ khi mới phát tâm vì muốn chúng sanh Nhứt thiết trí mà siêng tu cội phước chẳng tiếc thân mạng, trải qua số kiếp như số cực vi trần trong bất khả thuyết bất khả thuyết cõi Phật. Mỗi kiếp đều thí xả đầu, mắt, tay, chân v.v…nhiều như số cực vi trong bất khả thuyết bất khả thuyết cõi Phật, làm tất cả những hạnh khó làm như vậy, đầy đủ các món ba la mật, chứng nhập các trí địa của Bồ Tát, trọn nên qủa Vô Thượng Bồ Ðề của chư Phật, cho đến nhập Niết Bàn phân chia xá lợi. Bao nhiêu căn lành ấy tôi đều tùy hỷ cả.","Ðến các loài lục thú, tứ sanh trong tất cả mười phương thế giới kia có bao nhiều công đức, dầu nhỏ như mảy trần, tôi đều tùy hỷ.","Mười phương ba đời tất cả các vị Thanh Văn, Bích Chi Phật, hữu học và vô học có bao nhiêu công đức tôi đều tùy hỷ.","Tất cả chư Bồ Tát tu hạnh cần khổ khó làm, chí cầu qủa Vô Thượng Chánh Ðẳng Bồ Ðề công đức rộng lớn, tôi đều tùy hỷ. Như vậy, hư không giới cùng tận, chúng sanh giới cùng tận, chúng sanh nghiệp cùng tận, chúng sanh phiền não cùng tận, sự tùy hỷ của tôi đây không có cùng tận, niệm niệm nối luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! Nói “Thỉnh đức Phật thuyết pháp” là thế này:","Trong số cực vi khắp hư không pháp giới mười phương ba đời tất cả cõi Phật. Mỗi cực vi đều có cõi Phật rộng lớn nhiều như số cực vi trong bất khả thuyết bất khả thuyết cõi Phật. Mỗi cõi trong một niệm đều có tất cả chư Phật thành Chánh Ðẳng Chánh Giác số đông như số cực vi trong bất khả thuyết bất khả thuyết cõi Phật, tất cả chúng Bồ Tát nhóm họp vây quanh. Tôi đều đem thân, khẩu, ý ba nghiệp dùng những phương tiện ân cần khuyên mời tất cả Phật nói pháp nhiệm mầu. Như vậy, hư không giới cùng tận, chúng sanh nghiệp cùng tận, chúng sanh phiền não cùng tận, tôi luôn khuyên mời tất cả các đức Phật chuyển pháp luân chơn chánh không cùng tận, niệm niệm nối ý luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Thỉnh Phật ở lại đời” là như vầy:","Các đức Như Lai như số cực vi trong tất cả cõi Phật khắp hư không pháp giới mười phương ba đời toan muốn thị hiện nhập Niết Bàn, cùng các Bồ Tát, Thinh Văn, Duyên Giác, hữu học, vô học, cho đến tất cả các bậc thiện tri thức, tôi đều khuyên mời xin đừng nhập Niết Bàn, xin ở lại đời trải qua số kiếp như vi trần trong tất cả cõi Phật, vì muốn cho tất cả chúng sanh được lợi lạc. Như vậy, cõi hư không cùng tận, cõi chúng sanh cùng tận, nghiệp chúng sanh cùng tận, phiền não chúng sanh cùng tận, sự khuyên mời của tôi đây vẫn không cùng tận, niệm niệm nối luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Thường học tập theo Phật” là như vầy:","Như đấng Tỳ Lô Giá Na Phật ở cõi Ta Bà đây, từ khi mới phát tâm tinh tấn không trễ lui, đem bất khả thuyết bất khả thuyết thân mạng ra mà bố thí. Lột da làm giấy, chẻ xương làm viết, chích máu làm mực, dùng biên chép kinh điển chất cao như núi Tu Di, vì tôn trọng chánh pháp nên Phật không tiếc thân mạng, huống là ngôi vua, thành ấp, cung điện, vườn, rừng v.v..","Cùng thật hành bao nhiều hạnh khó làm khác, nhẫn đến ngồi dưới cây thành qủa đại Bồ Ðề, thị hiện các thứ thần thông, khởi các sự biến hóa, hiện các thân Phật ở trong những chúng hội: hoặc ở trong chúng hội đạo tràng của các vị đại Bồ Tát, hoặc ở trong đạo tràng của chúng hội Thinh Văn, Duyên Giác, hoặc ở trong đạo tràng của Chuyển Luân Vương, các vị Tiểu Vương cùng quyến thuộc, hoặc ở trong đạo tràng của chúng hội Cư Sĩ, Trưởng Giả, Bà La Môn cùng Sát Ðế Lợi, nhẫn đến hoặc ở trong đạo tràng của chúng hội Thiên, Long, Bát Bộ, Nhơn, Phi Nhơn v.v…ở trong các chúng hội như vậy, dùng tiếng viên mãn như đại lôi chấn, tùy theo căn tánh của mỗi loại mà giáo hóa cho chúng sanh đều được thành thục. Nhẫn đến thị hiện nhập Niết Bàn. Cả thảy hạnh đức như thế tôi đều học tập theo. Như đức Thế Tôn Tỳ Lô Giá Na hiện nay, các đức Phật Như Lai như số vi trần trong tất cả cõi Phật khắp hư không pháp giới mười phương ba đời cũng như thế ấy, trong mỗi niệm tôi đều học tập theo. Như vậy, cõi hư không cùng tận, cõi chúng sanh cùng tận, nghiệp chúng sanh cùng tận, phiền não chúng sanh cùng tận, sự tùy học của tôi đây vẫn không cùng tận niệm niệm nối luôn không hở, ba nghiệp thân, khẩu, ý không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Hằng thuận lợi chúng sanh” là như vầy:","Bao nhiêu chúng sanh sai khác trong tất cả cõi ở mười phương pháp giới, hư không giới, chính là những loài noãn sanh, thai sanh, thấp sanh, hóa sanh, các loài nương nơi chất tứ đại mà sanh, có giống nương nơi hư không cùng cây cỏ mà sanh. Các giống sanh loại: các thứ sắc thân, các thứ hình trạng, các thứ tướng mạo, các thứ thọ lượng, các thứ tộc loại, các thứ danh hiệu, các thứ tâm tánh, các thứ tri kiến, các thứ dục lạc, các thứ ý hành, các thứ oai nghi, các thứ y phục, các thứ ăn uống, ở trong các thôn dinh, thành ấp, cung điện, nhẫn đến tất cả Thiên, Long, Bát Bộ, Nhơn, Phi Nhơn v.v…loài không không chân, loài hai chân, bốn chân, nhiều chân, loài có hình sắc, loài không có hình sắc, loài có tâm tưởng, loài không có tâm tưởng, loài chẳng phải có tâm tưởng chẳng phải không tâm tưởng. Các loài như vậy tôi đều tùy thuận tất cả mà thật hành các sự vâng thờ, cúng dường, như kính cha mẹ, như thờ bậc thầy, cùng A La Hán, nhẫn đến như đức Như Lai đồng nhau không khác. Trong các loài ấy, nếu là kẻ có bịnh thì tôi vì họ mà làm lương y, nếu ai bị lạc đường thì tôi vì họ mà chỉ cho con đường chánh, nơi đêm tối tôi vì họ mà làm ngọn đuốc sáng, người nghèo thiếu tôi làm cho được của báu. Bồ Tát bình đẳng lợi ích cho chúng sanh như vậy.","Vì sao thế? Vì Bồ Tát nếu có thể tùy thuận chúng sanh, thì chính là tùy thuận cúng dường các đức Phật. Còn tôn trọng và thừa sự chúng sanh thì chính là tôn trọng và thừa sự các đức Như Lai. Nếu làm cho chúng sanh vui mừng thì chính là làm cho tất cả đức Như Lai vui mừng. Vì sao thế? Vì các đức Như Lai dùng tâm đại bi mà làm thể. Nhơn nơi chúng sanh mà sanh lòng đại bi, nhơn lòng đại bi mà phát tâm bồ đề, nhơn vì nơi tâm bồ đề mà thành bậc Vô Thượng Chánh Ðẳng Chánh Giác.","Ví như giữa chốn sa mạc có cây thọ vương to lớn, nơi gốc cây ấy được nước rưới nhuần, thì cành lá hoa qủa thảy đều sum suê tươi tốt.","Cây thọ vương Bồ đề ở chốn sá mạc sanh tử rộng lớn cũng như vậy: tất cả chúng sanh là gốc rễ, Bồ Tát là hoa, Phật là qủa. Dùng nước đại bi đượm nhuần gốc rễ chúng sanh thì có thể trổ bông Bồ Tát trí huệ kết thành qủa Phật toàn giác.","Vì sao thế? Bởi các Bồ Tát dùng nước đại bi làm lợi ích chúng sanh, thì có thể thành tựu qủa Vô Thượng Chánh Ðẳng Chánh Giác. Cho nên qủa Bồ Ðề thuộc về chúng sanh, vì nếu không chúng sanh, tất cả Bồ Tát trọn không thể thành đạo Vô Thượng Chánh Ðẳng Chánh Giác.","Này thiện nam tử! Ông ở nơi nghĩa ấy nên hiểu như thế.","Bởi đối với chúng sanh mà tâm bình đẳng thì có thể sanh lòng đại bi đầy đủ hoàn toàn. Dùng tâm đại bi mà tùy thuận chúng sanh thì có thể thành tựu pháp cúng dường Như Lai. Bồ Tát tùy thuận chúng sanh như thế ấy.","Cõi hư không cùng tận, cõi chúng sanh cùng tận, nghiệp chúng sanh cùng tận, phiền não chúng sanh cùng tận, sự tùy thuận chúng sanh của tôi vẫn không cùng tận, niệm niệm nối luôn không hở, thân khẩu, ý ba nghiệp không hề nhàm mỏi.","Lại này thiện nam tử! “Nói “Hồi hướng khắp tất cả” là như vầy:","Từ sự lễ kính ban đầu nhẫn đến tùy thuận có bao nhiêu công đức, thảy đều đem hồi hướng cho tất cả chúng sanh khắp trong hư không pháp giới. Nguyện cho tất cả chúng sanh thường được an lạc, không các bịnh khổ, muốn thật hành pháp ác thảy đều không thành, còn tu nghiệp lành thì đều mau thành tựu. Ðóng chặt cửa của tất cả các ác thú, mở bày đường chánh Nhơn Thiên Niết Bàn. Nếu các chúng sanh nhơn vì trước kia chứa nhóm các nghiệp ác nên chiêu cảm tất cả qủa rất khổ, tôi đều chịu thế cho, khiến chúng sanh đều được giải thoát, rốt ráo thành tựu qủa Vô Thượng Bồ Ðề. Bồ Tát tu hạnh hồi hướng như vậy. Cõi hư không cùng tận, cõi chúng sanh cùng tận, nghiệp chúng sanh cùng tận, phiền não chúng sanh cùng tận, sự hồi hướng của tôi vẫn không cùng tận, niệm niệm nối luôn không hở, thân khẩu, ý ba nghiệp không hề nhàm mỏi.","Này thiện nam tử! Ấy là mười điều nguyện lớn đầy đủ viên mãn của đại Bồ Tát. Nếu các vị Bồ Tát ở nơi mười điều nguyện lớn này mà tùy thuận tu hành, thì có thể thuần phục tất cả chúng sanh, thì có thể tùy thuận đạo Vô Thượng Chánh Ðẳng Chánh Giác, thì có thể trọn đủ các hạnh nguyện hải của ngài Phổ Hiền Bồ Tát. Này thiện nam tử! Do cớ ấy ở nơi các nghĩa trên đây ông nên hiểu biết như vậy."],"notes":[]},{"id":"loi-ich-va-cach-thuc-hanh","title":"Công đức niệm danh hiệu","paragraphs":["Theo phẩm Phổ Hiền Hạnh Nguyện trong Kinh Hoa Nghiêm, người nào đối với Mười Đại Nguyện Vương này mà sinh lòng tin sâu sắc, thọ trì, đọc tụng, biên chép và giảng giải cho người khác nghe, thì công đức ấy không thể nghĩ bàn: khi lâm chung, tất cả các căn thân quyến thuộc, tiền tài danh vọng thế gian đều phải bỏ lại, duy chỉ có Mười Đại Nguyện Vương này là không rời bỏ, luôn ở phía trước dẫn đường đưa lối, trong khoảng một sát-na liền vãng sinh về cõi Cực Lạc phương Tây, hoa sen đón rước, thấy Phật A Di Đà thọ ký thành Phật.","Học theo hạnh nguyện Phổ Hiền là học cách đem giáo lý Phật đà ứng dụng vào từng hành động cụ thể mỗi ngày: biết cung kính người khác (Lễ kính chư Phật), biết nói lời hay ái ngữ (Xưng tán Như Lai), biết sẻ chia rộng lượng (Quảng tu cúng dường), biết nhìn lại nhận lỗi sửa mình (Sám hối nghiệp chướng) và vui với niềm vui của người khác (Tùy hỷ công đức).","Năm đại nguyện tiếp theo — Thỉnh chuyển pháp luân, Thỉnh Phật trụ thế, Thường tùy Phật học, Hằng thuận chúng sinh và Phổ giai hồi hướng — giúp người tu biến trí tuệ thành hành động phục vụ xã hội: biết tôn trọng lắng nghe hoàn cảnh của mọi người, kiên trì học hỏi chánh pháp và đem mọi công đức nhỏ bé hàng ngày hồi hướng cho sự an vui chung của muôn loài.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đại Hạnh Phổ Hiền Bồ Tát”."],"notes":["Dẫn Kinh Hoa Nghiêm, phẩm Phổ Hiền Hạnh Nguyện."]},{"id":"da-la-ni-lien-quan","title":"Thần chú và đà-la-ni","paragraphs":["Trong Kinh Diệu Pháp Liên Hoa, phẩm Phổ Hiền Bồ Tát Khuyến Phát thứ 28, sau khi đối trước Đức Phật phát nguyện đời sau bảo hộ những người thọ trì Kinh Pháp Hoa, Bồ Tát Phổ Hiền đã tuyên thuyết một bài đà-la-ni thâm sâu để giữ gìn hành giả không bị ma quỷ quấy nhiễu.","Nguyên văn phiên âm Hán-Việt của bài đà-la-ni trong Kinh Pháp Hoa: “A-đàn-địa, đàn-đà-bà-địa, đàn-đà-bạt-đế, đàn-đà-cưu-xá-lệ, đàn-đà-tam-bạt-nhi, tha-la-nê, tha-la-nê, bà-la-nê, át-đàm-bạt-đế, tôn-đà-la-bạt-đế, tha-la-nê, tỳ-na-mông, vi-nặc-đế, bà-la-nê, tha-la-nê, a-nậu-bà-đế, sa-bà-ha”.","Công dụng của Đà-la-ni Phổ Hiền theo kinh điển: Khiến cho người thọ trì Kinh Pháp Hoa không bị các loài ma quỷ, dạ-xoa, la-sát hay người xấu tìm cách rình rập hãm hại; tâm trí luôn kiên định trong Chánh pháp, nếu có chỗ nào quên sót câu chữ trong kinh liền được Bồ Tát hiện thân chỉ dạy nhắc nhở.","Kinh dạy rằng nếu người hành trì đúng pháp trong hai mươi mốt ngày tinh tấn tu hành, Bồ Tát Phổ Hiền sẽ cỡi thớt voi trắng sáu ngà cùng vô lượng quyến thuộc hiện ra trước mặt người ấy để an ủi, tán thán và xoa đầu thọ ký.","Việc trì tụng thần chú của Bồ Tát Phổ Hiền phải gắn chặt với hạnh nguyện thực tế, lấy giới luật làm nền tảng và lấy việc phụng sự muôn loài làm đạo tràng tu học."],"notes":["Đối chiếu Kinh Pháp Hoa, phẩm Phổ Hiền Bồ Tát Khuyến Phát thứ 28."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích Thiền sư Nam Nhạc Tuệ Tư (515–577), thầy của Đại sư Trí Giả, được chép trong Tục Cao Tăng Truyện (quyển 17): ngài chuyên tụng Kinh Pháp Hoa và các kinh Đại thừa, từng mộng thấy Bồ Tát Phổ Hiền cưỡi voi trắng đến xoa đầu, từ đó chỗ được xoa nổi lên như nhục kế. Ngài tinh tấn tọa thiền suốt mùa an cư, có lúc bệnh nặng, bèn quán chiếu rằng bệnh khởi từ nghiệp, nghiệp khởi từ tâm, tâm vốn không thật thì bệnh cũng không có chỗ đứng. Cuối mùa an cư, khi vừa định tựa lưng vào vách nghỉ ngơi, lưng chưa chạm vách thì ngài bỗng đại ngộ, chứng Pháp Hoa Tam Muội. Về sau ngài truyền pháp tu này cho Đại sư Trí Giả, đặt nền tảng cho Thiên Thai tông.","Hiện tượng mầu nhiệm Nga Mi Bảo Quang và Thánh Đăng trên đỉnh Kim Đỉnh được ghi chép trong Nga Mi Sơn Chí (quyển 2): Núi Nga Mi tại Tứ Xuyên là đạo tràng thiêng liêng của Bồ Tát Phổ Hiền. Từ ngàn năm qua, các đoàn hành hương thuần thành khi lên đỉnh Kim Đỉnh chiêm bái tượng Bồ Tát thường xuyên chứng kiến hiện tượng kỳ diệu gọi là “Phật Quang Nga Mi” (Nga Mi Bảo Quang): giữa biển mây trắng xóa cuồn cuộn dưới thung lũng sâu, bỗng xuất hiện một vầng hào quang tròn bảy sắc lộng lẫy như cầu vồng bao quanh bóng dáng người hành hương, hễ người cử động thì bóng quang minh cử động theo, người này chỉ thấy bóng quang minh của chính mình mà không thấy bóng của người bên cạnh. Vào những đêm thanh vắng không trăng sao, giữa vực thẳm bỗng bay lên muôn ngàn đốm sáng lấp lánh như ngọn đèn lơ lửng bay lượn trước Phật điện rồi từ từ biến mất, dân gian gọi là “Thánh Đăng triều bái Phổ Hiền”, minh chứng cho linh khí thiêng liêng bất khả tư nghì của Bồ Tát Phổ Hiền ngự trị chốn nhân gian.","Theo Nga Mi Sơn Chí (quyển 2), núi Nga Mi ở Tứ Xuyên là đạo tràng ứng hóa của Bồ Tát Phổ Hiền. Từ xưa, chư Tăng và Phật tử hành hương lên đỉnh Kim Đính lễ bái Ngài thường chiêm ngưỡng hiện tượng quang minh năm sắc gọi là Phật quang. Truyền thống hành trì pháp Phổ Hiền tại đây cũng gắn liền với hành trạng các bậc cao tăng như Thiền sư Nam Nhạc Tuệ Tư trong Tục Cao Tăng Truyện (quyển 17), luôn nhắc nhở người tu rằng ánh sáng linh ứng chân thật nhất chính là giữ giới thanh tịnh và thực hành Mười Đại Nguyện Vương giữa đời thường."],"notes":["Truyện Thiền sư Tuệ Tư đối chiếu Tục Cao Tăng Truyện quyển 17 (T2060); hiện tượng Phật quang đối chiếu Nga Mi Sơn Chí quyển 2."]}],"references":["Kinh Diệu Pháp Liên Hoa, phẩm Phổ Hiền Bồ Tát Khuyến Phát thứ 28 — HT Thích Trí Tịnh Việt dịch.","Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký — Đàm-vô-sấm Hán dịch, Đại Chính tạng số 157.","Kinh Hoa Nghiêm, phẩm Phổ Hiền Hạnh Nguyện — Bát Nhã dịch, Đại Chính tạng số 293. Nguồn nguyên văn của mục Mười Đại Hạnh Nguyện.","Nga Mi Sơn Chí, quyển 2 — ghi chép lịch sử đạo tràng Phổ Hiền Bồ Tát tại Nga Mi Sơn.","Tục Cao Tăng Truyện, quyển 17: truyện Nam Nhạc Tuệ Tư — Đạo Tuyên soạn, Đại Chính tạng tập 50, số 2060."]},{"id":"di-lac","name":"Bồ Tát Di Lặc","summary":"Bồ Tát Di Lặc (Maitreya) là vị Đại Bồ Tát Đương Lai Hạ Sanh, bậc Nhất Sanh Bổ Xứ biểu trưng cho tâm Từ Bi hỷ xả vô biên. Ngài hiện đang thuyết pháp tại Thiên cung Đâu Suất Nội Viện và đời sau sẽ thị hiện thành Phật nơi cõi Ta Bà, mở Ba Hội Long Hoa độ thoát muôn loài.","sections":[{"id":"than-the","title":"Tiểu sử và cảnh giới Thiên cung Đâu Suất","paragraphs":["Danh hiệu Di Lặc trong tiếng Phạn là Maitreya, phiên âm Hán-Việt là Di-lặc, dịch nghĩa là Từ Thị, tức người mang chủng tính từ bi yêu thương muôn loài. Tên riêng của Ngài là A-dật-đa (Ajita), nghĩa là Bất Khả Thắng, tức đức từ bi và trí tuệ vô thượng không có bất kỳ sức mạnh tà ác nào có thể chiến thắng được. Ngài là bậc Đại Bồ Tát Nhất Sanh Bổ Xứ, vị Phật tương lai kế tiếp Đức Bổn Sư Thích Ca Mâu Ni nơi cõi Ta Bà, nên thường được muôn đời tôn xưng là Đương Lai Hạ Sanh Di Lặc Tôn Phật.","Theo Kinh Di Lặc Thượng Sanh Đâu Suất Đà Thiên, Bồ Tát Di Lặc sau khi xả bỏ báo thân nơi cõi Ta Bà đã sinh lên cõi trời Đâu Suất Đà, ngự tại Đâu Suất Nội Viện thanh tịnh. Nơi ấy là một cõi Tịnh độ vi diệu trang nghiêm bằng thất bảo: cung điện nguy nga, lan can lưới ngọc, cây báu nở hoa thơm ngát; Bồ Tát Di Lặc ngự trên tòa sư tử thất bảo kết hoa sen ngọc, ngày đêm thuyết giảng giáo pháp Bất thoái chuyển cho chư thiên và hàng Bồ Tát nghe, chuẩn bị đầy đủ nhân duyên để giáng trần cứu độ muôn loài.","Theo Kinh Di Lặc Hạ Sanh, trải qua năm mươi sáu ức bảy mươi triệu năm nữa, khi cõi Ta Bà bước vào thời kỳ cực thịnh, thọ mạng con người tăng dài và đất đai bằng phẳng thanh tịnh, Bồ Tát Di Lặc sẽ từ cung trời Đâu Suất giáng sinh chốn nhân gian, xuất gia tầm đạo và thành tựu Phật quả dưới cội cây hoa Long Hoa (Long Hoa thụ). Ngài sẽ khai mở Ba Hội Long Hoa vĩ đại: hội thứ nhất độ chín mươi sáu ức người, hội thứ hai độ chín mươi bốn ức người, hội thứ ba độ chín mươi hai ức người, cứu vớt toàn bộ chúng sinh còn sót lại từ thời Đức Phật Thích Ca Mâu Ni đồng chứng quả giải thoát.","Hình tượng Bồ Tát Di Lặc trong nghệ thuật Phật giáo Đông Á thường gắn liền với hóa thân Bố Đại Hòa Thượng (Hòa thượng túi vải) với nụ cười hoan hỷ rạng rỡ, bụng to tròn dung chứa mọi sự đời, biểu trưng cho đức tính hỷ xả, bao dung và niềm an lạc tự tại giữa nhân gian."],"notes":["Tiểu sử và cõi Đâu Suất y cứ Kinh Di Lặc Thượng Sanh (T452) và Kinh Di Lặc Hạ Sanh (T453)."]},{"id":"phat-nguyen-ban-dau","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Bổn Sinh và các bản kinh truyện cổ Phật giáo, thuở quá khứ khi mới bắt đầu phát tâm tu Bồ Tát đạo, Bồ Tát Di Lặc đã phát đại thệ nguyện sâu xa: Nguyện tu tập Từ tâm tam muội (Mettā-samādhi), thương xót sinh mạng muôn loài như con một, thề đời đời kiếp kiếp không ăn thịt chúng sinh, không làm tổn hại bất kỳ loài hữu tình nào. Chính vì bản nguyện từ ái ấy mà chư Phật mười phương đều xưng tán Ngài bằng tôn hiệu Từ Thị.","Trong Kinh Hiền Ngu có kể câu chuyện tiền thân Ngài là một vị vương tử giàu lòng nhân từ, khi quốc gia gặp nạn hạn hán đói kém ngặt nghèo, Ngài đã tình nguyện xả bỏ của cải và cả thân mạng mình để cứu đói cho muôn dân. Tinh thần phát tâm ban đầu của Bồ Tát Di Lặc dạy cho người tu học bài học căn bản: muốn thành Phật trước hết phải mở rộng lòng từ bi không sát hại, biết đem niềm vui và sự tha thứ chia sẻ cho những người chung quanh.","Theo Kinh Đại Bảo Tích (phẩm Di Lặc Bồ Tát Sở Vấn), thuở quá khứ xa xưa Bồ Tát Di Lặc và Đức Thích Ca Mâu Ni từng đồng tu dưới thời Đức Phật Phất Sa. Đức Thích Ca vì tâm bi mẫn bức thiết muốn sớm cứu độ chúng sinh cõi Ta-bà ngũ trược nên tinh tấn dõng mãnh thành Phật trước, còn Bồ Tát Di Lặc chuyên tu Từ Tâm Tam Muội, nhẫn nại bồi đắp căn lành cho chúng sinh chờ đến hội Long Hoa khi nhân duyên chín muồi sẽ hạ sinh thành Phật."],"notes":["Hạnh Từ tâm tam muội trích Kinh Hiền Ngu và Đại Trí Độ Luận."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Đại nguyện cốt tủy của Bồ Tát Di Lặc là thệ nguyện cứu độ trọn vẹn những người đệ tử của Đức Phật Thích Ca Mâu Ni chưa kịp giải thoát trong thời mạt pháp: bất kỳ ai từng gieo một căn lành nhỏ nơi Tam Bảo thời Phật Thích Ca (như niệm một câu Phật, lạy một lạy, thọ một giới, cúng dường một nén hương hoa), Ngài đều thề nguyện sẽ tiếp độ trọn vẹn trong Ba Hội Long Hoa tương lai, khiến cho tất cả đều đắc quả A-la-hán hoặc chứng Vô Sanh Pháp Nhẫn.","Bên cạnh đó, Ngài còn lập đại thệ nguyện tiếp dẫn tất cả chúng sinh chí thành tu tập mười điều thiện, giữ gìn giới luật thanh tịnh và phát nguyện vãng sinh lên Thiên cung Đâu Suất Nội Viện để đồng tu học với Ngài, cùng theo Ngài giáng trần trong đời vị lai để tham dự Long Hoa Tam Hội.","Kinh Di Lặc Hạ Sanh mô tả ba hội thuyết pháp dưới cội Long Hoa: những ai từng quy y Tam Bảo, giữ năm giới, tám giới, cúng dường, xây chùa, tạo tượng, đọc tụng kinh điển trong pháp hội của Đức Thích Ca đều có nhân duyên được gặp Đức Di Lặc và được độ thoát. Lời kinh ấy khích lệ người tu học trân quý từng việc lành nhỏ hôm nay.","Hạnh nguyện của Ngài là Từ tâm: nuôi lớn lòng thương bình đẳng, không sát hại, không oán hận. Hình ảnh nụ cười hoan hỷ và chiếc bụng lớn bao dung trong tranh tượng nhắc người học Phật thực tập Tứ Vô Lượng Tâm gồm từ, bi, hỷ, xả ngay trong gia đình và nơi làm việc."],"notes":["Đại nguyện Long Hoa và tiếp dẫn Đâu Suất y cứ Kinh Di Lặc Hạ Sanh Thành Phật Kinh."]},{"id":"loi-ich-xung-danh","title":"Công đức niệm danh hiệu","paragraphs":["Theo Kinh Di Lặc Thượng Sanh, người nào nghe được danh hiệu của Bồ Tát Di Lặc, chí thành xưng niệm, lễ bái và sám hối nghiệp chướng, thì người ấy trừ được tội nặng sinh tử trong một ngàn hai trăm kiếp; nếu người nào chí tâm phát nguyện sinh về Đâu Suất Nội Viện thì khi lâm chung sẽ được Bồ Tát phóng ánh bạch hào quang minh tiếp dẫn.","Xưng niệm danh hiệu Bồ Tát Di Lặc giúp người tu học nuôi dưỡng tâm hỷ xả, mở rộng nụ cười tha thứ, buông bỏ những oán hờn tị hiềm nhỏ nhen, đem lại sự hòa ái an vui trong gia đình và xã hội.","Người tu theo pháp môn Đâu Suất thường kết hợp xưng niệm danh hiệu với việc giữ giới, tụng Kinh Di Lặc Thượng Sanh và hồi hướng nguyện được gặp Ngài. Đây cũng là pháp môn mà các bậc cao tăng như ngài Đạo An, ngài Huyền Trang và ngài Khuy Cơ từng phát nguyện thực hành.","Thực hành hạnh Di Lặc ngay trong hiện tại là tập pháp Từ Tâm Quán: mỗi ngày dành vài phút lắng tâm rải lòng từ ái đến bản thân, người thân, người xa lạ và cả những người từng làm mình phiền lòng; tập mỉm cười trước nghịch cảnh và nói lời hòa giải để gieo nhân duyên lành với hội Long Hoa tương lai.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Đương Lai Hạ Sanh Di Lặc Tôn Phật”."],"notes":["Dẫn Kinh Di Lặc Thượng Sanh (Đại Chính tạng T452)."]},{"id":"than-chu-da-la-ni","title":"Thần chú và đà-la-ni","paragraphs":["Trong Mật tạng Đại thừa, Bồ Tát Di Lặc có bài thần chú tâm chân ngôn thâm sâu giúp hành giả kết nối năng lượng từ bi và gieo duyên sâu dày với hội Long Hoa. Bản phiên tự Phạn văn thường được ghi là: oṃ maitreya svāhā (hoặc bài Đại Chú: oṃ maitri maitri mahāmaitri maitrīya svāhā).","Câu thần chú của Bồ Tát Di Lặc được phiên âm theo tiếng Việt: “Ôm, mai-tri mai-tri, ma-ha mai-tri, mai-tri-dê xoa-ha” (Âm Hán-Việt: “Án, nặc-lặc nặc-lặc, ma-ha nặc-lặc, nặc-lặc-dã, sa-bà-ha”).","Công dụng của Thần chú Di Lặc theo kinh điển: Khơi dậy hạt giống Từ bi tam muội nơi tâm thức, tiêu trừ nghiệp chướng sân hận và hờn giận nhiều đời; đem lại dung mạo hoan hỷ rạng ngời, chiêu cảm sự thương yêu quý kính của mọi người chung quanh và gieo nhân duyên chắc chắn được diện kiến Đức Phật Di Lặc trong hội Long Hoa.","Khi trì tụng chân ngôn này, người học Phật quán tưởng tôn nhan Bồ Tát Di Lặc mỉm cười rạng rỡ tỏa ánh sáng vàng ấm áp, tự nhắc nhở mình học theo hạnh bao dung: “Bụng lớn dung nạp những điều khó dung nạp trong cõi đời; Miệng cười hoan hỷ đón nhận mọi sự thị phi nhân gian”."],"notes":["Đối chiếu Mật tạng Chân Ngôn thừa và nghi quỹ Di Lặc Bồ Tát Du Già Pháp."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích hóa thân Bố Đại Hòa Thượng tại đất Minh Châu được ghi chép trong Tống Cao Tăng Truyện (quyển 21) và Cảnh Đức Truyền Đăng Lục: Vào thời Ngũ Đại Hậu Lương tại vùng Phụng Hóa thuộc đất Minh Châu (Trung Hoa), có một vị hòa thượng kỳ dị tự xưng hiệu là Khế Thử. Ngài dáng người mập mạp béo tốt, chiếc bụng to tròn phốp pháp để hở, nét mặt luôn nở nụ cười rạng rỡ hoan hỷ vô biên, trên vai luôn vắt một chiếc túi vải lớn bằng bao bố thô sơ đi lang thang khắp phố chợ làng mạc (người đời bèn gọi ngài là Bố Đại Hòa Thượng, nghĩa là Hòa thượng túi vải). Bất kể ai cho thứ gì, từ cơm bánh, hoa quả cho đến củi nước, ngài đều hoan hỷ bỏ hết vào trong túi vải ấy; khi gặp những đứa trẻ con nghèo khó hay những người hành khất đói lả bên đường, ngài liền ngồi bệt xuống đất, mở túi vải lấy ra chia phát hết cho họ mà cười ha hả. Ngài có tài tiên tri thời tiết kỳ diệu: hễ thấy ngài đi guốc gỗ ướt sũng bước nhanh là trời sắp nắng ráo, còn hễ thấy ngài mang dép cỏ tìm hiên nhà nằm ngủ là trời sắp đổ mưa bão lớn, trăm lần ứng nghiệm không sai một lần. Đến năm Trinh Minh thứ ba (năm 917) đời nhà Lương, ngài đến trước hiên chùa Nhạc Lâm, ngồi kiết già ngay ngắn trên một tảng đá phẳng lớn, an nhiên tuyên thuyết một bài kệ bốn câu bất hủ trước khi thị tịch: “Di Lặc chân Di Lặc, phân thân thiên bách ức. Thời thời thị thời nhân, thời nhân giai bất thức” (Nghĩa là: Di Lặc thật Di Lặc, phân thân trăm ngàn ức. Thường hiện trước người đời, người đời đều chẳng biết). Đọc xong bài kệ vi diệu ấy, ngài an nhiên nhắm mắt trút hơi thở cuối cùng trong tư thế ngồi thiền thanh thản. Mọi người chung quanh lúc ấy mới giật mình bàng hoàng ngộ ra vị hòa thượng túi vải hoan hỷ kia chính là kim thân Bồ Tát Di Lặc thị hiện cõi Ta Bà để ban rải lòng từ bi hỷ xả. Về sau, hình ảnh Bố Đại Hòa Thượng với nụ cười bất diệt trở thành biểu tượng thân thương của Bồ Tát Di Lặc trong lòng hàng triệu Phật tử khắp muôn nơi.","Sự tích chiêm bái Đâu Suất Tịnh Độ của Đại sư Huyền Trang và Đại sư Hư Vân: Đại sư Huyền Trang (thời Đường) cả đời dịch kinh hoằng pháp, luôn giữ gìn lời thệ nguyện thiết tha được vãng sinh lên Thiên cung Đâu Suất Nội Viện để làm đệ tử hầu cận Bồ Tát Di Lặc. Đến ngày mùng năm tháng hai năm Lân Đức nguyên niên (năm 664), trước giờ thị tịch, ngài bảo môn đồ chắp tay niệm danh hiệu Đức Di Lặc Như Lai. Khi thần thức sắp lìa thân, ngài mở mắt mỉm cười thanh thản bảo đồ chúng: “Ta đã nhìn thấy hoa sen trắng báu nở rộ giữa ao thất bảo, Bồ Tát Di Lặc tướng hảo quang minh đang mỉm cười đưa tay đón rước ta!”. Nói xong lời ấy ngài an nhiên thị tịch. Hòa thượng Hư Vân vào năm 1951 (khi ngài đã 112 tuổi), trong biến cố Vân Môn bị tra tấn ngất lịm chết lâm sàng suốt chín ngày đêm. Đồ chúng ngỡ ngài đã viên tịch nhưng thân thể vẫn ấm. Đến ngày thứ mười ngài tỉnh lại và kể cho các đệ tử nghe: trong lúc chết lâm sàng, thần thức ngài bay thẳng lên Đâu Suất Nội Viện, thấy lầu các trang nghiêm lộng lẫy phi thường, Bồ Tát Di Lặc ngồi trên tòa báu thuyết pháp cùng đại chúng; Bồ Tát quay sang bảo ngài: “Thời cơ của ngươi nơi cõi Ta Bà chưa hết, nghiệp duyên chưa trọn, ngươi phải trở về hoằng pháp độ sinh!”. Sau khi trở lại thân xác, ngài tiếp tục thọ mạng sống đến 120 tuổi, lưu lại tấm gương đạo hạnh sáng ngời.","Sự tích ngài Vô Trước gặp Bồ Tát Di Lặc được lưu truyền trong Bà Tẩu Bàn Đậu Pháp Sư Truyện và Đại Đường Tây Vực Ký: ngài Vô Trước (khoảng thế kỷ IV) vào núi tu tập nhiều năm mong được gặp Bồ Tát Di Lặc để thưa hỏi nghĩa Đại thừa nhưng chưa thấy cảm ứng. Theo truyền thống Tây Tạng kể thêm, một lần xuống núi ngài gặp con chó bị thương, vết thương đầy giòi. Thương con vật mà cũng không nỡ hại giòi, ngài định dùng lưỡi nhẹ nhàng gỡ chúng ra; vừa cúi xuống thì con chó biến mất, Bồ Tát Di Lặc hiện ra và cho biết Ngài vẫn luôn ở bên, chỉ vì nghiệp chướng mà chưa thấy được, nay lòng đại bi đã gột sạch chướng ngại. Sau đó Bồ Tát Di Lặc truyền dạy các bộ luận như Du Già Sư Địa Luận, làm nền tảng cho Duy Thức học. Sự tích nhắc rằng tâm từ bi là cánh cửa để gặp được Phật và Bồ Tát."],"notes":["Truyện Bố Đại Hòa Thượng trích Tống Cao Tăng Truyện quyển 21; truyện Huyền Trang trích Đại Từ Ân Tự Tam Tạng Pháp Sư Truyện quyển 10; truyện Hư Vân trích Hư Vân Niên Phổ; truyện Vô Trước đối chiếu Bà Tẩu Bàn Đậu Pháp Sư Truyện (T2049), Đại Đường Tây Vực Ký quyển 5 và truyền thống Tây Tạng."]}],"references":["Kinh Di Lặc Thượng Sanh Đâu Suất Đà Thiên — Thư Cừ Kinh Thanh Hán dịch, Đại Chính tạng số 452.","Kinh Di Lặc Hạ Sanh Thành Phật — Trúc Pháp Hộ dịch, Đại Chính tạng số 453.","Tống Cao Tăng Truyện, quyển 21: truyện Hòa thượng Bố Đại Khế Thử — Ninh Cát soạn, Đại Chính tạng tập 50, số 2061.","Đại Đường Đại Từ Ân Tự Tam Tạng Pháp Sư Truyện, quyển 10 — Tuệ Lập và Ngạn Tông soạn.","Hư Vân Trưởng Lão Tự Thuật Niên Phổ — Sầm Học Lữ biên tập.","Bà Tẩu Bàn Đậu Pháp Sư Truyện — Chân Đế dịch, Đại Chính tạng số 2049.","Đại Đường Tây Vực Ký, quyển 5 — Huyền Trang thuật, Biện Cơ soạn, Đại Chính tạng số 2087."]},{"id":"duoc-vuong","name":"Dược Vương Bồ Tát","summary":"Bồ Tát Dược Vương (Bhaiṣajyarāja) là vị Đại Bồ Tát biểu trưng cho hạnh nguyện Y Vương cứu độ muôn loài, chữa lành mọi tật bệnh đau đớn nơi thân xác và tâm hồn. Ngài nổi bật trong Kinh Pháp Hoa với công hạnh dũng mãnh xả thân cúng dường Chánh pháp và hộ trì người trì kinh.","sections":[{"id":"than-the-tien-than","title":"Tiểu sử và tiền thân Tinh Túc Quang","paragraphs":["Trong Phật giáo Đại thừa, Bồ Tát Dược Vương mang danh hiệu tiếng Phạn là Bhaiṣajyarāja, nghĩa là vị Y Vương tối thượng trong tất cả các bậc thầy thuốc. Ngài cùng người em ruột là Bồ Tát Dược Thượng (Bhaiṣajyasamudgata) là hai vị Bồ Tát đại biểu cho tinh thần chữa trị hai thứ bệnh hiểm nghèo của chúng sinh: bệnh nơi thân thể (tật bệnh ung nhọt, phong hàn, nóng sốt, lục phủ ngũ tạng suy thoái) và bệnh nơi tâm thức (tam độc tham lam, sân hận, si mê phiền não).","Theo Kinh Phật Thuyết Quán Dược Vương Dược Thượng Nhị Bồ Tát, vào thời tượng pháp của Đức Phật Lưu Ly Quang Chiếu Như Lai thuở quá khứ, có một vị trưởng giả tên là Tinh Túc Quang, học rộng biết nhiều, lòng từ bi rộng lớn. Khi nghe chư tăng trong chùa ngã bệnh thiếu thốn thuốc men, trưởng giả Tinh Túc Quang cùng em trai là Điện Quang Minh đã phát tâm dốc hết tài sản quý giá lên rừng sâu hái các thứ thần dược quý nhất cúng dường lên Đức Phật và chư Tăng suốt nhiều tháng liền, lại đem thuốc men và thực phẩm chữa lành bệnh tật cho muôn dân nghèo khó.","Đối trước Đức Phật Lưu Ly Quang Chiếu, trưởng giả Tinh Túc Quang phát đại thệ nguyện sâu dày: Nguyện con đời đời kiếp kiếp đem thân thể và trí tuệ làm vị Đại Y Vương, gom góp mọi thứ linh dược trong trời đất để cứu trị tất cả bệnh khổ của chúng sinh; dẫu chúng sinh mắc phải bệnh nan y hay tà khí quấy phá, nghe danh hiệu con đều được lành lặn thân tâm. Đức Phật khen ngợi và thọ ký cho trưởng giả đời sau sẽ thành Phật mang tôn hiệu Tịnh Nhãn Như Lai, còn em trai thành Phật hiệu Tịnh Tạng Như Lai.","Trong Kinh Diệu Pháp Liên Hoa (phẩm Dược Vương Bồ Tát Bổn Sự thứ 23), tiền thân của Ngài là Bồ Tát Nhất Thiết Chúng Sinh Hỷ Kiến, tu tập khổ hạnh dưới thời Phật Nhật Nguyệt Tịnh Minh Đức, đã chứng đắc Hiện Nhất Thiết Sắc Thân Tam Muội và dũng mãnh xả thân cúng dường Chánh pháp vô thượng."],"notes":["Tiền thân Tinh Túc Quang y cứ Kinh Quán Dược Vương Dược Thượng (Đại Chính tạng T1161); tiền thân Nhất Thiết Chúng Sinh Hỷ Kiến y cứ Kinh Pháp Hoa phẩm 23."]},{"id":"nhan-duyen-phat-tam","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Quán Dược Vương Dược Thượng Nhị Bồ Tát, nhân duyên phát tâm Bồ-đề của Bồ Tát Dược Vương khởi nguồn từ lòng thương xót thấu tận can tràng khi chứng kiến nỗi quằn quại rên siết của người mắc bệnh tật hiểm nghèo. Ngài nhận thấy thân xác tứ đại giả hợp vốn mong manh, hễ một đại bất an là trăm bệnh cùng phát; nhưng nỗi đau nơi thân xác vẫn không đáng sợ bằng căn bệnh vô minh si ám đẩy chúng sinh vào chốn trầm luân địa ngục muôn kiếp.","Từ nhận thức sâu sắc ấy, Ngài phát tâm không chỉ làm người thầy thuốc chữa trị thân bệnh thế gian, mà quyết tâm tu tập chứng đắc Chánh pháp để làm vị Đại Y Vương chữa dứt căn bệnh phiền não chấp ngã nơi tâm thức, ban rải linh dược Bát-nhã Ba-la-mật cho muôn loài.","Tinh thần phát tâm của Bồ Tát Dược Vương dạy cho người tu học: chăm sóc sức khỏe thân thể và rèn luyện đạo đức tâm linh là hai mặt không thể tách rời; người đệ tử Phật phải biết thương yêu chăm sóc người đau ốm, đồng thời chuyên cần uống linh dược giáo pháp để gạn lọc tâm hồn.","Trong phẩm Dược Vương Bồ Tát Bổn Sự của Kinh Pháp Hoa, tiền thân của Ngài là Bồ Tát Nhất Thiết Chúng Sinh Hỷ Kiến. Dưới thời Đức Phật Nhật Nguyệt Tịnh Minh Đức, để báo đền ơn giáo pháp vi diệu, Ngài đã nhập định Hiện Nhất Thiết Sắc Thân, tẩm hương đốt thân và sau đó đốt hai cánh tay cúng dường xá-lợi Phật; tinh thần ấy biểu trưng cho sự xả bỏ chấp ngã thô lậu vì lý tưởng giác ngộ."],"notes":["Dẫn Kinh Quán Dược Vương Dược Thượng Nhị Bồ Tát (T1161)."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Trong Kinh Diệu Pháp Liên Hoa, phẩm Trì thứ 13, Bồ Tát Dược Vương cùng Bồ Tát Đại Nhạo Thuyết và hai muôn vị Bồ Tát phát lời thệ giữ gìn, đọc tụng và giảng nói kinh sau khi Đức Phật diệt độ. Đây là lời thệ chung của các vị trong pháp hội. Bản Việt dịch HT Thích Trí Tịnh:","Cúi mong đức Thế-Tôn chớ lo, sau khi Phật diệt độ chúng con sẽ phụng trì đọc tụng nói kinh điển này, đời ác sau, chúng sanh căn lành càng ít, nhiều kẻ tăng-thượng mạn tham lợi dưỡng cúng-dường, thêm lớn căn chẳng lành, xa lìa đạo giải thoát, dầu khó có thể giáo hóa, chúng con sẽ khởi sức nhẫn lớn đọc tụng kinh này, thọ-trì giải nói biên chép, dùng các món cúng dường cho đến chẳng tiếc thân mạng","Trong Kinh Diệu Pháp Liên Hoa, phẩm Dược Vương Bồ Tát Bổn Sự thứ 23, Đức Phật Thích Ca chỉ rõ hạnh nguyện đặc thù của Bồ Tát Dược Vương: Tiền thân Ngài là Bồ Tát Nhất Thiết Chúng Sanh Hỷ Kiến, thệ nguyện xả bỏ thân mạng, đốt thân và cánh tay để cúng dường Phật Nhật Nguyệt Tịnh Minh Đức và Chánh pháp Pháp Hoa vô thượng.","Bản nguyện Đại Y Vương của Ngài là phát nguyện làm vị thầy thuốc đại từ bi, đem diệu dược Chánh pháp cứu chữa tận gốc rễ mọi thân bệnh hiểm nghèo và tâm bệnh tham, sân, si, tà kiến cho tất cả chúng sinh, khiến cho thân tâm muôn loài đều được an ổn, thanh tịnh và chứng đắc quả giác ngộ."],"notes":[]},{"id":"loi-ich-tri-danh","title":"Công đức niệm danh hiệu","paragraphs":["Theo Kinh Phật Thuyết Quán Dược Vương Dược Thượng Nhị Bồ Tát, để gieo nhân duyên lành được thường xuyên gặp Phật và tiêu trừ nghiệp chướng, người tu học nên chí thành quán tưởng và xưng niệm danh hiệu Bồ Tát Dược Vương. Lời kinh dạy rằng người nào nghe được danh hiệu của Ngài, một lòng kính tin không nghi ngờ, thì đời đời không đọa vào ba đường ác, thường sinh ra nơi cõi Phật thanh tịnh.","Kinh cũng nhấn mạnh rằng người niệm danh hiệu Bồ Tát Dược Vương cần nuôi dưỡng tâm từ bi bình đẳng, tránh làm hại sinh linh, thực hành bố thí thuốc men và chăm sóc bệnh nhân; sự kết hợp giữa niềm tin thanh tịnh và hành động cứu người cụ thể mới là phương cách cúng dường chân chính lên Bồ Tát.","Đức Phật Thích Ca dạy trong phẩm Dược Vương rằng giáo pháp Đại thừa như vị đại lương dược chữa lành bệnh khổ cõi Diêm Phù Đề. Do đó, người trì niệm danh hiệu Bồ Tát Dược Vương cần giữ thân khẩu ý thanh tịnh, thực hành bố thí không sợ hãi và tận tâm chăm sóc người đau yếu bằng lòng từ ái chân thành.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Dược Vương Bồ Tát”."],"notes":["Dẫn Kinh Quán Dược Vương Dược Thượng và Kinh Pháp Hoa."]},{"id":"than-chu-lien-quan","title":"Thần chú và đà-la-ni","paragraphs":["Trong Kinh Diệu Pháp Liên Hoa, phẩm Đà-la-ni thứ 26, Bồ Tát Dược Vương đã đối trước Đức Phật phát tâm dõng mãnh tuyên thuyết một bài thần chú để ủng hộ và bảo vệ những người thọ trì, đọc tụng và biên chép Kinh Pháp Hoa.","Bài thần chú được tuyên tụng theo âm Hán-Việt truyền thống: “An-nhĩ, mẫn-nhĩ, ma-ninh, mẫn-ninh, ma-lệ, chỉ-lệ, trí-lệ, xa-mê, xa-lý, đa-vĩ, thiền-đế, mục-đế, mục-đa-lý, ta-lý, a-vi-xa-lý, tang-lý, sa-mê, sa-bà-đa-nhi, mẫu-đà-lý, ô-ca-lý, thấu-ca-lý, tỳ-thập-phược, bát-la-thiền-đế, a-mâu-cát-đa-lý, bà-la-thiền-đế, la-xoa, la-xoa-mê, sa-bà-ha”.","Công dụng của Thần chú Dược Vương theo kinh điển: Bảo vệ người tu trì Chánh pháp không bị các loài ma quỷ, dạ-xoa, la-sát, quỷ cướp tinh khí hay kẻ ác tìm cơ hội hãm hại; tiêu trừ các thứ bệnh dịch độc hại, phong hàn, ung nhọt và giữ cho thân tâm hành giả luôn được an ổn thanh tịnh.","Kinh khẳng định rằng oai lực của bài thần chú này được chư Phật nhiều như cát sáu mươi hai ức sông Hằng đồng thanh hộ trì; kẻ nào xâm phạm hay quấy nhiễu người trì chú tức là xúc phạm và quấy nhiễu chư Phật mười phương.","Việc trì tụng thần chú Dược Vương đem lại sự che chở tinh thần vững chắc, giúp hành giả vượt qua nỗi sợ hãi bệnh tật và kiên định trên con đường tu học giải thoát."],"notes":["Đối chiếu Kinh Pháp Hoa, phẩm Đà-la-ni thứ 26."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích Đại sư Trí Giả ngộ đạo khi tụng phẩm Dược Vương được chép trong Tùy Thiên Thai Trí Giả Đại Sư Biệt Truyện: ngài Trí Giả (538–597) đến núi Đại Tô học đạo với Thiền sư Tuệ Tư, được dạy tu Pháp Hoa Tam Muội. Ngài tinh tấn tụng Kinh Pháp Hoa ngày đêm. Khi tụng đến câu trong phẩm Dược Vương Bồ Tát Bổn Sự: đây là chân tinh tấn, đây gọi là chân pháp cúng dường Như Lai, thân tâm ngài bỗng lắng yên, nhập định, thấy pháp hội Linh Sơn vẫn còn đó chưa tan. Thiền sư Tuệ Tư ấn chứng rằng ngài đã đắc Pháp Hoa Tam Muội tiền phương tiện. Sự tích cho thấy cúng dường chân thật nhất mà Bồ Tát Dược Vương dạy là tu hành đúng pháp.","Lương Cao Tăng Truyện (quyển 12, phần Vong Thân) chép về Pháp sư Huệ Ích đời Tống thuộc Nam triều: ngài phát nguyện noi theo hạnh xả thân của Bồ Tát Dược Vương để cúng dường Chánh pháp, ròng rã nhiều năm giữ giới khổ hạnh rồi vừa tụng phẩm Dược Vương vừa hiến thân. Người đương thời cảm phục, dựng chùa Dược Vương nơi ấy. Truyền thống Phật giáo về sau luôn giảng rằng hạnh đốt thân trong kinh mang nghĩa biểu pháp, tức buông bỏ chấp ngã; người tu học không nên bắt chước làm tổn hại thân thể, mà nên dùng thân này giữ giới, tụng kinh, chăm sóc người bệnh để cúng dường Phật.","Ngoài tích trong Kinh Pháp Hoa, Kinh Quán Dược Vương Dược Thượng Nhị Bồ Tát còn kể tiền thân khác của Ngài là chàng Tinh Tú Quang cùng em trai là Điện Quang Minh. Thuở Đức Phật Lưu Ly Quang Chiếu, hai anh em dốc lòng hái các thứ hoa thơm quả quý và thượng dược nơi núi Tuyết đem cúng dường chư Tăng, rồi phát đại nguyện đời đời trị lành thân bệnh và tâm bệnh cho hết thảy chúng sinh; nhờ công đức ấy mà được chư Phật thọ ký tôn hiệu Dược Vương và Dược Thượng."],"notes":["Truyện Đại sư Trí Giả đối chiếu Tùy Thiên Thai Trí Giả Đại Sư Biệt Truyện (T2050); truyện Pháp sư Huệ Ích đối chiếu Lương Cao Tăng Truyện quyển 12 (T2059)."]}],"references":["Kinh Diệu Pháp Liên Hoa, phẩm Trì thứ 13 và phẩm Dược Vương Bồ Tát Bổn Sự thứ 23 — HT Thích Trí Tịnh Việt dịch. Nguồn nguyên văn của mục Đại nguyện.","Kinh Phật Thuyết Quán Dược Vương Dược Thượng Nhị Bồ Tát, Đại Chính tạng tập 20, số 1161 — Cương-lương-da-xá dịch.","Tùy Thiên Thai Trí Giả Đại Sư Biệt Truyện — Quán Đảnh soạn, Đại Chính tạng tập 50, số 2050.","Lương Cao Tăng Truyện, quyển 12: phần Vong Thân — Huệ Hạo soạn, Đại Chính tạng tập 50, số 2059."]},{"id":"hu-khong-tang","name":"Hư Không Tạng Bồ Tát","summary":"Hư Không Tạng Bồ Tát (Ākāśagarbha) là vị Đại Bồ Tát sở hữu kho tàng trí tuệ và công đức bao la vô tận như hư không, luôn ban phát vô lượng pháp bảo cứu giúp kẻ nghèo cùng khổ nạn. Ngài tiêu biểu cho diệu pháp Cầu Văn Trì, tăng cường trí nhớ siêu việt và tiêu trừ nghiệp chướng.","sections":[{"id":"biography","title":"Tiểu sử và cõi Ta Bà biến hiện trang nghiêm","paragraphs":["Danh hiệu Hư Không Tạng trong tiếng Phạn là Ākāśagarbha: Hư Không (Ākāśa) nghĩa là bầu trời bao la vô tận, không ngằn mé, không vướng bận, dung chứa vạn vật mà không bị bất kỳ vật gì làm hoại diệt; Tạng (Garbha) nghĩa là kho tàng chứa đầy muôn vàn bảo báu công đức và trí tuệ vi diệu. Bồ Tát Hư Không Tạng là vị Đại Bồ Tát có tâm lượng rộng lớn bao trùm khắp pháp giới, sẵn sàng ban phát vô lượng vô biên của báu thế gian và xuất thế gian cho tất cả chúng sinh nghèo cùng, thiếu thốn và túng quẫn.","Theo Kinh Hư Không Tạng Bồ Tát (Đại Chính tạng T405, do Phật-đà-bạt-đà-la dịch), khi Đức Phật Thích Ca Mâu Ni đang thuyết pháp tại núi Kha-la-đế-gia (Khalatika), Bồ Tát Hư Không Tạng từ thế giới phương Tây xa xôi ngự giá đến Ta Bà. Để biểu thị diệu lực trang nghiêm thanh tịnh, Ngài đã vận dụng thần lực biến cõi Ta Bà uế trược thành một cảnh giới thất bảo tuyệt mỹ: mặt đất gồ ghề đầy chông gai sỏi đá bỗng biến thành bằng phẳng như lòng bàn tay bằng ngọc lưu ly trong suốt, cây báu nở hoa thơm ngát, đường sá rải đầy hoa trời, cung điện thất bảo lộng lẫy hiện ra hai bên, tiếng nhạc trời du dương trầm bổng chấn động nhân gian.","Đến trước Đức Phật, Bồ Tát Hư Không Tạng an tọa kiết già trên một đóa hoa sen báu nghìn cánh khổng lồ với thân sen bằng bạc ròng, cánh sen bằng vàng ngọc và nhụy sen bằng ngọc lục bảo biếc; trên đỉnh đầu Ngài có viên ngọc như ý bảo châu (Như Ý Châu) tỏa ra ánh quang minh ngũ sắc rực rỡ chiếu soi khắp mười phương cõi Phật, làm dịu mát nỗi khổ của chúng sinh trong các chốn địa ngục u đồ.","Trong Mật tạng Chân Ngôn thừa, Ngài là vị Bồ Tát chủ quản Viện Hư Không Tạng trong Thai Tạng Giới Mạn-đà-la, bắt ấn Phúc Trí đồng thời và tay cầm gươm báu Bát-nhã nâng ngọc như ý tỏa sáng."],"notes":["Cảnh giới Ta Bà biến hiện và đóa sen báu y cứ Kinh Hư Không Tạng Bồ Tát (T405, §§1.21–1.27)."]},{"id":"initial-vows","title":"Phát tâm ban đầu","paragraphs":["Kinh Hư Không Tạng ghi nhận rằng thuở quá khứ xa xưa khi mới phát Bồ-đề tâm, Ngài quán sát thấy chúng sinh trong cõi đời nhiều người sinh ra trong cảnh nghèo hèn bần hàn, thiếu ăn thiếu mặc, lại có kẻ do túc nghiệp đời trước che lấp mà đầu óc đần độn tối tăm, học hành hay quên, tâm trí loạn động, tạo muôn ngàn điều tội lỗi ngũ nghịch không biết sám hối.","Ngài liền đối trước chư Phật phát đại thệ nguyện sâu dày: Nguyện con tu tập Bồ Tát đạo thành tựu kho báu vô tận như hư không, bất kỳ ai thiếu thốn của cải vật chất con đều ban cho no đủ, bất kỳ ai tối tăm đần độn muốn cầu trí nhớ và trí tuệ học Phật con đều gia hộ cho thông suốt, và bất kỳ ai lỡ phạm tội lỗi nặng nề nếu biết chí tâm sám hối con đều phóng quang minh tiêu trừ tội chướng cho họ.","Theo Kinh Đại Tập Đại Hư Không Tạng Bồ Tát Sở Vấn (do ngài Bất Không Hán dịch đời Đường), Ngài là vị Đại Bồ Tát nắm giữ kho tàng công đức, trí tuệ và phương tiện thiện xảo vô biên rộng lớn như hư không. Tùy theo căn cơ và tâm nguyện thanh tịnh của từng người, Ngài mở kho pháp bảo ban phát phương tiện cứu giúp, giúp người cầu đạo vượt qua cảnh nghèo túng vật chất lẫn chướng ngại ngu tối về trí tuệ."],"notes":["Nhân duyên phát tâm trích Kinh Hư Không Tạng Bồ Tát (T405)."]},{"id":"great-vows","title":"Đại nguyện","paragraphs":["Theo Kinh Hư Không Tạng Bồ Tát (Đại Chính tạng T405), đại nguyện của Bồ Tát Hư Không Tạng ví như biển cả dung nạp muôn sông: Ngài thề nguyện ban phát vô lượng pháp bảo giải thoát cho tất cả những ai chí thành cầu đạo; dùng ánh sáng ngọc như ý trên đảnh đầu chiếu soi gạn lọc mọi tội nghiệp sâu dày của chúng sinh, khiến cho tội nhân phá giới phạm trọng tội ngũ nghịch vô gián đều được ăn năn sám hối thanh tịnh.","Đặc biệt, đại nguyện của Ngài gắn liền với pháp môn Cầu Văn Trì (Gumonjihō): nguyện gia hộ cho người tu học Phật pháp có được trí nhớ siêu việt, nghe một lần là nhớ mãi không quên (nhất văn năng trì), thấu suốt toàn bộ kinh điển tam tạng và thành tựu biện tài vô ngại để hoằng dương Chánh pháp.","Kinh Hư Không Tạng Bồ Tát dạy rằng người lỡ phạm lỗi nặng, nếu biết hổ thẹn, đến đầu đêm và cuối đêm hướng về phương Đông khi sao mai vừa mọc, chí thành xưng danh hiệu Bồ Tát và sám hối, thì Bồ Tát sẽ tùy duyên hiện thân, hoặc hiện trong giấc mộng, chỉ bày cách sám hối để tội chướng được thanh tịnh. Vì vậy Ngài được xem là vị Bồ Tát chủ về pháp sám hối và tịnh hóa.","Trong tranh tượng, Ngài tay phải cầm kiếm trí tuệ, tay trái nâng ngọc như ý: kiếm cắt đứt phiền não, ngọc ban phước đức. Hai pháp khí biểu trưng cho phước và trí cùng tu, nhắc người học Phật vừa bố thí làm lành, vừa học hỏi để sáng tỏ chánh kiến."],"notes":["Đại nguyện y cứ Kinh Hư Không Tạng Bồ Tát và nghi quỹ Cầu Văn Trì Pháp (T1145)."]},{"id":"name-recitation-benefits","title":"Công đức niệm danh hiệu","paragraphs":["Trong nghi thức tu tập, người học Phật hướng về Ngài để xưng niệm tôn danh: Nam Mô Đại Bi Hư Không Tạng Bồ Tát. Việc xưng niệm danh hiệu Ngài giúp tâm trí mở rộng dung lượng bao la, phá vỡ sự ích kỷ hẹp hòi và dẹp trừ những xao động lo âu nơi cuộc sống thường nhật.","Theo Kinh Quán Hư Không Tạng Bồ Tát, người nào chí thành đảnh lễ và niệm danh hiệu Ngài thì tiêu trừ được nghiệp chướng si ám nhiều đời, tăng trưởng trí nhớ, trí tuệ minh mẫn sáng suốt, học hành thi cử hanh thông và được Bồ Tát che chở thân tâm an định.","Việc xưng niệm cần kết hợp với tâm chí thành sám hối lỗi lầm và thực hành hạnh bố thí giúp đỡ người nghèo khó; có như vậy hành giả mới tương ưng trọn vẹn với đức hạnh bao la như hư không của Bồ Tát.","Trong truyền thống Chân Ngôn tông và Phật giáo Đông Á, hành giả thường thực hành Cầu Văn Trì Pháp (Gumonji-hō) bằng cách giữ giới thanh tịnh, sám hối lỗi lầm trước khi học hỏi kinh điển rồi chuyên tâm trì niệm danh hiệu hoặc thần chú Hư Không Tạng Bồ Tát. Phương pháp này giúp tâm lắng sâu, tăng trưởng định lực và khả năng ghi nhớ bền vững."],"notes":["Dẫn Kinh Quán Hư Không Tạng Bồ Tát (T409)."]},{"id":"related-mantra","title":"Thần chú và đà-la-ni","paragraphs":["Trong văn bản Hư Không Tạng Bồ Tát Năng Mãn Chư Nguyện Tối Thắng Tâm Đà-la-ni Cầu Văn Trì Pháp thuộc Mật tạng (Đại Chính tạng số 1145, do Thiện Vô Úy dịch), bài thần chú Cầu Văn Trì được lưu truyền để hành giả chuyên tâm tu tập khai mở trí nhớ và trí tuệ.","Bài thần chú được xưng tụng theo âm Hán-Việt truyền thống: “Nam-mô a-kiêm-bà các-bà-gia, Án a-ly, ca-ma-lỵ, mộ-cật, ta-bà-ha” (Phiên tự Phạn văn: namo ākāśagarbhāya, oṃ ārya kamari mauli svāhā).","Công dụng của Thần chú Hư Không Tạng theo kinh điển: Giúp khai mở tiềm năng trí tuệ vô biên, gia tăng năng lực ghi nhớ và thấu suốt kinh điển giáo pháp, khiến cho người trì tụng có trí nhớ phi phàm không bao giờ quên sót; tiêu trừ mọi chướng ngại ngu si đần độn và tịnh hóa tội nghiệp sâu dày.","Kinh điển chỉ dạy phương pháp hành trì: hành giả giữ gìn thân tâm thanh tịnh, thắp hương đảnh lễ tôn tượng Bồ Tát Hư Không Tạng, chuyên tâm trì tụng thần chú với số lượng lớn (như mười ngàn hoặc một triệu biến) với tâm chí thành không xao lãng, sẽ cảm ứng được ánh sáng trí tuệ của Bồ Tát gia hộ.","Việc trì tụng thần chú phải luôn đi kèm với sự chăm chỉ học tập, tư duy đúng đắn (văn, tư, tu) và áp dụng giáo lý vào cuộc sống, không nên xem chú ngữ như một phép màu thay thế cho sự nỗ lực tự thân."],"notes":["Đối chiếu Cầu Văn Trì Pháp (T1145) do Thiện Vô Úy Hán dịch."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích Hoằng Pháp Đại Sư Không Hải đắc Cầu Văn Trì Pháp tại hang đá Mũi Muroto được ghi chép trong Tam Giáo Chỉ Quy (Sango Shiki) và Mật Tông Khai Tổ Truyện: Vào thời Heian tại Nhật Bản, Hoằng Pháp Đại Sư Không Hải (Kūkai, 774–835) khi còn là một thanh niên trẻ tuổi tài hoa xuất chúng tên là Mao Ngư, lòng ôm ấp chí nguyện thấu triệt biển học chân lý vũ trụ để cứu độ nhân sinh. Ngài được vị cao tăng Cần Tố (Gonzō) truyền trao bí pháp Hư Không Tạng Bồ Tát Năng Mãn Chư Nguyện Tối Thắng Tâm Đà La Ni Cầu Văn Trì Pháp. Năm mười chín tuổi, ngài quyết định xả bỏ con đường công danh thế tục, một mình lặn lội vào vùng núi hiểm trở hoang sơ tại hang đá Mikurodo ở Mũi Muroto (tỉnh Tosa, nay là tỉnh Kochi) — nơi ngày đêm chỉ có tiếng sóng biển Thái Bình Dương gầm réo cuộn trào đập vào vách đá dựng đứng. Tại nơi hang đá lạnh lẽo hoang vu ấy, Không Hải ngồi kiết già ngay ngắn trên tảng đá phẳng, ăn lá cây rừng uống nước suối, dốc trọn tính mạng ngày đêm trì tụng thần chú Hư Không Tạng một triệu biến suốt một trăm ngày đêm không rời khỏi hang. Đến canh năm của đêm cuối cùng tròn một triệu biến, khi tâm thức ngài đạt đến trạng thái thanh tịnh rỗng rang, tâm thể hòa nhập tuyệt đối cùng hư không pháp giới, bỗng nhiên một hiện tượng chấn động diễn ra: từ trên bầu trời phương Đông rực rỡ, ngôi sao Mai (sao Kim, biểu thị cho hóa thân quang minh của Bồ Tát Hư Không Tạng) vụt bay thẳng xuống với tốc độ sao băng, tỏa ánh hào quang chói lòa khắp đất trời rồi bay chui thẳng vào miệng ngài. Ngay giây phút sao Mai nhập vào thân tâm, Không Hải cảm nhận nguồn tuệ giác vô lượng vô biên bừng sáng rực rỡ, ngài đắc được trí nhớ siêu phàm tột đỉnh gọi là Nhất Văn Năng Trì: toàn bộ kinh điển tam tạng thế gian và xuất thế gian hễ nghe qua hay đọc qua một lần là nhớ như in từng câu từng chữ suốt đời không quên, thấu triệt nguồn gốc vạn pháp. Trải nghiệm cảm ứng thiêng liêng rúng động trời đất ấy đã đưa ngài sang Trường An tiếp nhận trọn vẹn y bát Mật giáo từ Huệ Quả quốc sư và trở thành bậc Tổ sư khai sáng Chân Ngôn Tông lừng danh ngàn đời.","Kinh Quán Hư Không Tạng Bồ Tát (Đại Chính tạng số 409) ghi lại phương pháp sám hối thù thắng: người tu đến cuối đêm hướng về sao mai, chí thành đảnh lễ, xưng danh hiệu Bồ Tát và phát lồ lỗi lầm. Nếu thấy Bồ Tát hiện thân, hoặc mộng thấy Bồ Tát dùng ngọc như ý ấn lên tay, thì đó là dấu hiệu tội chướng được tiêu trừ. Chính lời kinh này giải thích vì sao trong sự tích Đại sư Không Hải, sao mai được xem là biểu tượng hiện thân của Bồ Tát Hư Không Tạng. Pháp sám hối ấy đến nay vẫn được các chùa Chân Ngôn tông tại Nhật Bản gìn giữ.","Trong Kinh Hư Không Tạng Bồ Tát (Đại Chính tạng số 405), khi Đức Phổ Quang Minh Vương Như Lai tại thế, Bồ Tát từng là vương tử Sư Tử Tiến, con của Chuyển luân Thánh vương Công Đức Trang Nghiêm. Sau khi xuất gia tu đạo, Ngài hiện thần lực khiến từ giữa hư không tuôn mưa trân bảo, hoa thơm và nhạc trời cúng dường khắp đại thiên thế giới, làm thỏa mãn mọi ước nguyện chính đáng của chúng sinh; từ đó chư thiên và nhân loại đồng tôn xưng Ngài là Hư Không Tạng."],"notes":["Truyện Không Hải đối chiếu Tam Giáo Chỉ Quy (Sangō Shiiki) và các bản hành trạng Hoằng Pháp Đại Sư; phép sám hối hướng về sao mai đối chiếu Kinh Quán Hư Không Tạng Bồ Tát (T409)."]}],"references":["Kinh Hư Không Tạng Bồ Tát, Đại Chính tạng tập 13, số 405 — Phật-đà-bạt-đà-la dịch.","Kinh Quán Hư Không Tạng Bồ Tát, Đại Chính tạng số 409 — Đàm-ma-mật-đa dịch.","Hư Không Tạng Bồ Tát Năng Mãn Chư Nguyện Tối Thắng Tâm Đà-la-ni Cầu Văn Trì Pháp, Đại Chính tạng tập 20, số 1145 — Thiện Vô Úy dịch.","Tam Giáo Chỉ Quy (Sango Shiki) — trước tác của Hoằng Pháp Đại Sư Không Hải (Kūkai).","Kinh Đại Tập Đại Hư Không Tạng Bồ Tát Sở Vấn — Bất Không Hán dịch, Đại Chính tạng tập 13, số 404."]},{"id":"nhat-quang","name":"Nhật Quang Biến Chiếu Bồ Tát","summary":"Bồ Tát Nhật Quang Biến Chiếu (Sūryaprabha) là vị đại Bồ Tát thượng thủ đứng đầu chúng hội tại cõi Tịnh Lưu Ly phương Đông, cùng với Bồ Tát Nguyệt Quang trợ hóa Đức Phật Dược Sư. Ngài tiêu biểu cho ánh sáng mặt trời của trí tuệ sáng suốt, xua tan bóng tối vô minh và gìn giữ kho tàng Chánh pháp.","sections":[{"id":"tieu-su","title":"Tiểu sử và vị thế Thượng thủ cõi Tịnh Lưu Ly","paragraphs":["Danh hiệu Nhật Quang trong tiếng Phạn là Sūryaprabha, thường được tôn xưng đầy đủ là Nhật Quang Biến Chiếu Bồ Tát, mang ý nghĩa là ánh sáng mặt trời trí tuệ chiếu soi khắp muôn phương vô lượng cõi nước. Trong Kinh Dược Sư Lưu Ly Quang Như Lai Bản Nguyện Công Đức, Ngài là bậc Đại Bồ Tát thượng thủ ngự bên cánh tả của Đức Phật Dược Sư nơi cõi thế giới Tịnh Lưu Ly ở phương Đông.","Theo kinh điển, cõi Tịnh Lưu Ly có vô lượng vô số trăm ngàn muôn ức Bồ Tát tu hành, nhưng đứng đầu trong hàng đại chúng chỉ có hai vị Bồ Tát có đầy đủ oai đức và năng lực trợ hóa Phật sự: bậc thứ nhất là Bồ Tát Nhật Quang Biến Chiếu và bậc thứ hai là Bồ Tát Nguyệt Quang Biến Chiếu. Hai Ngài là bậc Nhất sanh bổ xứ, đời sau sẽ nối tiếp ngôi vị Phật tại cõi Tịnh Lưu Ly để giữ gìn kho tàng Chánh pháp của chư Phật không bao giờ dứt đoạn.","Hình tượng Bồ Tát Nhật Quang Biến Chiếu trong nghệ thuật tạo tượng Phật giáo thường được khắc họa với thân sắc đỏ hồng trang nghiêm hoặc thân sắc vàng ròng rực rỡ, tay cầm đóa hoa sen đỏ nở rộ, trên hoa sen an trí một đĩa mặt trời (Nhật luân) phát ra muôn ngàn tia sáng ấm áp, biểu trưng cho trí tuệ sáng suốt xua tan mọi tăm tối khổ đau.","Đức Phật Dược Sư cùng hai vị Bồ Tát Nhật Quang và Nguyệt Quang được tôn xưng là Đông Phương Tam Thánh. Trong cách bày tượng truyền thống, Bồ Tát Nhật Quang đứng bên trái Đức Phật, Bồ Tát Nguyệt Quang đứng bên phải; ánh sáng mặt trời và mặt trăng biểu thị sự gia hộ không gián đoạn suốt ngày và đêm."],"notes":["Vị thế Thượng thủ cõi Tịnh Lưu Ly y cứ Kinh Dược Sư (Đại Chính tạng T450)."]},{"id":"nhan-duyen-phat-tam","title":"Phát tâm ban đầu","paragraphs":["Theo kinh điển Phật giáo ghi chép về tiền thân của Tam Thánh cõi Tịnh Lưu Ly, vào thuở quá khứ vô lượng kiếp xa xưa, có một vị cư sĩ tên là Điện Quang Huệ, học rộng tài cao, giàu lòng nhân ái từ bi, thấy chúng sinh trong cõi đời nhiều bệnh tật khổ nạn bèn phát đại thệ nguyện trị lành mọi thứ thân bệnh và tâm bệnh cho muôn loài. Vị cư sĩ ấy sinh được hai người con trai tài đức vẹn toàn: người con trưởng tên là Nhật Chiếu và người con thứ tên là Nguyệt Tịnh.","Thấy gương sáng đại bi của phụ thân, người con trưởng Nhật Chiếu đã đối trước mười phương chư Phật dõng mãnh phát Bồ-đề tâm sâu dày: Nguyện con trong đời vị lai sẽ làm vị Bồ Tát tỏa ánh sáng mặt trời trí tuệ đại quang minh ấm áp để trợ duyên cho phụ thân hoằng dương Chánh pháp, thiêu rụi mọi mầm mống tà kiến si ám và cứu giúp chúng sinh thoát khỏi chướng dịch khổ đau. Vị cư sĩ Điện Quang Huệ thuở ấy nay đã thành tựu Phật quả tôn hiệu là Dược Sư Lưu Ly Quang Như Lai, còn người con trưởng Nhật Chiếu nay chính là Bồ Tát Nhật Quang Biến Chiếu.","Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức xác nhận rằng trong vô lượng Bồ Tát ở cõi Tịnh Lưu Ly, Bồ Tát Nhật Quang Biến Chiếu và Bồ Tát Nguyệt Quang Biến Chiếu là hai vị thượng thủ bậc Nhất Sinh Bổ Xứ, tức chỉ còn một đời nữa sẽ thành Phật. Hai Ngài thay mặt đại chúng gìn giữ kho tàng Chánh pháp của Đức Phật Dược Sư và tiếp nối sự nghiệp độ sinh nơi phương Đông."],"notes":["Sự tích tiền thân cư sĩ Điện Quang Huệ và hai người con trích dẫn các bản luận giải pháp môn Dược Sư cổ truyền."]},{"id":"hanh-nguyen","title":"Đại nguyện","paragraphs":["Trong Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức, Bồ Tát Nhật Quang Biến Chiếu cùng Bồ Tát Nguyệt Quang Biến Chiếu cùng phát đại thệ nguyện đời đời kiếp kiếp hộ trì và tuyên dương kho tàng Chánh pháp mười hai đại nguyện của Đức Phật Dược Sư.","Đại nguyện của Bồ Tát Nhật Quang Biến Chiếu là dùng ánh sáng mặt trời của trí tuệ đại bi soi rọi khắp cõi u minh tăm tối, thề nguyện bảo hộ tất cả những ai thọ trì, đọc tụng và biên chép Kinh Dược Sư; tiêu diệt mọi mầm mống dịch bệnh ôn hoàng độc hại, xua tan các loài ma quỷ quấy nhiễu trong đêm tối, đem lại sự ấm áp sinh khí và an lành cho nhân gian.","Trong Kinh Đại Bi Tâm Đà La Ni, sau khi Bồ Tát Quán Thế Âm tuyên thuyết Chú Đại Bi, Bồ Tát Nhật Quang cùng Bồ Tát Nguyệt Quang đều nói thần chú để ủng hộ người thọ trì. Hạnh nguyện ấy cho thấy hai Ngài không chỉ trợ hóa Đức Dược Sư mà còn hộ trì tất cả người tu tập Chánh pháp với tâm từ bi.","Trong đời sống thực tế, hạnh nguyện của Bồ Tát Nhật Quang còn là lời nhắc nhở hành giả sống với ánh sáng tỉnh thức: soi xét nhân quả rõ ràng trước mỗi quyết định, không để tà kiến hay sự mê tín dẫn dắt, đồng thời lan tỏa tinh thần tích cực và lòng ngay thẳng đến cộng đồng chung quanh."],"notes":["Đại nguyện gắn liền với việc tuyên dương và bảo hộ pháp môn Dược Sư."]},{"id":"loi-ich-xung-danh","title":"Công đức niệm danh hiệu","paragraphs":["Trong nghi thức lễ bái truyền thống của pháp môn Dược Sư, danh hiệu của Bồ Tát Nhật Quang Biến Chiếu thường được xưng niệm cùng với Đức Phật Dược Sư và Bồ Tát Nguyệt Quang để cầu nguyện tiêu tai diên thọ, thân tâm an ổn và tăng trưởng trí tuệ sáng suốt.","Khi hướng tâm xưng niệm danh hiệu Bồ Tát Nhật Quang Biến Chiếu, hành giả nương theo ý nghĩa ánh sáng mặt trời để dẹp trừ những ý niệm tiêu cực, u uất, sợ hãi, khơi dậy niềm tin kiên cố và nguồn năng lượng tích cực ấm áp trong đời sống thường nhật.","Khi đảnh lễ và xưng niệm danh hiệu Bồ Tát Nhật Quang Biến Chiếu, người học Phật quán chiếu ánh mặt trời trí tuệ đang chiếu rọi vào tự tâm, soi tan những nghi ngờ, u ám và lười biếng; từ đó giữ tâm minh bạch, chính trực và đem tri thức chân chánh giúp người quanh mình bớt khổ.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Nhật Quang Biến Chiếu Bồ Tát”."],"notes":["Theo nghi thức Dược Sư Sám Pháp và truyền thống lễ bái Đông Phương Tam Thánh."]},{"id":"than-chu-lien-quan","title":"Thần chú và đà-la-ni","paragraphs":["Trong Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, ở phần cuối sau khi thuyết Chú Đại Bi, Bồ Tát Nhật Quang đã đối trước Đức Phật phát tâm ủng hộ người trì tụng kinh chú bằng một bài thần chú đà-la-ni riêng.","Nguyên văn chữ Hán của bài chú trong bản kinh này là: 南無勃陀瞿那迷。南無達摩莫訶低。南無僧伽多夜泥。底哩部畢薩咄檐納摩。","Bài thần chú hộ trì của Bồ Tát Nhật Quang được truyền tụng theo âm Hán-Việt: “Nam-mô bột-đà cù-na-mê, Nam-mô đạt-ma mạc-ha đê, Nam-mô tăng-già đa-dạ-nê, Để-lợi bộ-tất tát-đốt-hàm nạp-mô”.","Công dụng của Thần chú Nhật Quang theo kinh điển: Dùng ánh sáng mặt trời trí tuệ xua tan bóng tối ma chướng, dịch bệnh u ám và tà thuật bùa chú hiểm độc; gia hộ cho người trì chú diệt trừ các ác nghiệp nặng nề, thân tâm thường được ấm áp an định và không bị các loài ác quỷ ban đêm xâm hại.","Theo lời kinh chỉ dẫn, sự kết hợp giữa việc trì tụng thần chú với tâm thành kính và thực hành sám hối giúp củng cố định lực, đồng thời nhắc nhở hành giả sống chan hòa, ngay thẳng như ánh sáng mặt trời ban phát sự sống cho muôn loài."],"notes":["Đối chiếu Kinh Đại Bi Tâm Đà La Ni (Đại Chính tạng T1060)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Kinh Đại Bi Tâm Đà La Ni (Đại Chính tạng số 1060) ghi rằng: sau khi Bồ Tát Quán Thế Âm tuyên thuyết Chú Đại Bi, Bồ Tát Nhật Quang vì muốn ủng hộ người thọ trì nên nói thần chú lớn, dạy rằng ai tụng chú này thì diệt được tất cả tội, cũng tránh được ma chướng và tai nạn. Kinh khuyên người tụng Chú Đại Bi nên tụng kèm thần chú của Bồ Tát Nhật Quang năm biến để thêm phần gia hộ. Lời kinh này là nền tảng cho việc tôn thờ Bồ Tát Nhật Quang trong các thời khóa Đại Bi tại nhiều chùa Bắc truyền.","Kinh Dược Sư kể rằng Bồ Tát Cứu Thoát dạy vua chúa, người bệnh và thân quyến pháp cầu an: thắp bốn mươi chín ngọn đèn, treo phan ngũ sắc, phóng sinh và thọ trì tám giới. Tại nhiều chùa Đông Á, bộ tượng Đông Phương Tam Thánh gồm Đức Dược Sư cùng hai Bồ Tát Nhật Quang, Nguyệt Quang được tôn trí để làm lễ cầu an; nổi tiếng là bộ tượng đồng thế kỷ VIII tại chùa Dược Sư (Yakushi-ji) ở Nara, Nhật Bản, nơi các thời khóa Dược Sư được duy trì liên tục hơn mười ba thế kỷ. Truyền thống ấy cho thấy niềm tin của Phật tử nơi sự gia hộ của Bồ Tát Nhật Quang luôn gắn với giữ giới và làm lành.","Tại Việt Nam và nhiều nước Đông Á, trong các khóa lễ Dược Sư Sám Pháp đầu năm hoặc kỳ siêu cầu an, đại chúng thường kết hợp tụng Nhật Quang Bồ Tát Đà La Ni sau Chú Đại Bi. Nhiều Phật tử chia sẻ rằng việc giữ tâm sáng suốt, lạc quan khi trì niệm danh hiệu Đông Phương Tam Thánh đã giúp người bệnh vơi bớt nỗi lo âu, tinh thần vững vàng hơn để phối hợp điều trị hiệu quả."],"notes":["Dẫn Kinh Đại Bi Tâm Đà La Ni (T1060), đoạn Nhật Quang Bồ Tát thuyết chú; pháp cầu an theo Kinh Dược Sư (T450); bộ tượng Tam Tôn chùa Dược Sư (Yakushi-ji), Nara."]}],"references":["Kinh Dược Sư Lưu Ly Quang Như Lai Bản Nguyện Công Đức, quyển duy nhất — Huyền Trang Hán dịch; Đại Chính tạng tập 14, số 450.","Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, Đại Chính tạng tập 20, số 1060 — đoạn Nhật Quang Chân Ngôn.","Kinh Đại Bi Tâm Đà La Ni, đoạn Nhật Quang Bồ Tát và Nguyệt Quang Bồ Tát thuyết chú — Già Phạm Đạt Ma Hán dịch, Đại Chính tạng số 1060.","Kinh Dược Sư Thất Phật Bổn Nguyện Công Đức — Nghĩa Tịnh Hán dịch, Đại Chính tạng số 451."]},{"id":"nguyet-quang","name":"Nguyệt Quang Biến Chiếu Bồ Tát","summary":"Bồ Tát Nguyệt Quang Biến Chiếu (Candraprabha) là vị đại Bồ Tát thượng thủ tại cõi Tịnh Lưu Ly phương Đông, cùng với Bồ Tát Nhật Quang trợ hóa Đức Phật Dược Sư. Ngài tiêu biểu cho ánh trăng từ bi thanh lương, dịu mát, luôn xoa dịu nỗi khổ nhiệt não của chúng sinh và hộ trì kho tàng Chánh pháp.","sections":[{"id":"than-the","title":"Tiểu sử và vị thế Thượng thủ cõi Tịnh Lưu Ly","paragraphs":["Danh hiệu Nguyệt Quang trong tiếng Phạn là Candraprabha, thường được tôn xưng đầy đủ là Nguyệt Quang Biến Chiếu Bồ Tát, mang ý nghĩa là ánh trăng từ bi thanh lương dịu mát chiếu soi khắp muôn phương vô lượng cõi nước. Trong Kinh Dược Sư Bản Nguyện Công Đức, Ngài là bậc Đại Bồ Tát thượng thủ ngự bên cánh hữu của Đức Phật Dược Sư Lưu Ly Quang Như Lai tại thế giới Tịnh Lưu Ly phương Đông.","Cùng với Bồ Tát Nhật Quang, Ngài là bậc Đại Bồ Tát Nhất sanh bổ xứ đứng đầu trong vô lượng chúng Bồ Tát tại cõi Tịnh Lưu Ly, có đầy đủ công đức oai thần và trí huệ sâu rộng để trợ duyên cho Phật sự tuyên dương Chánh pháp, cứu độ muôn loài chúng sinh thoát khỏi đau khổ ách nạn của thân tâm.","Trong nghệ thuật tạo tượng Phật giáo, Bồ Tát Nguyệt Quang Biến Chiếu thường được thể hiện với thân sắc trắng muốt thanh khiết như ngọc bạch ngọc hoặc màu xanh nguyệt đạm dịu mát, tay cầm hoa sen xanh tươi mát, trên hoa sen an trí một đĩa mặt trăng tròn vành vạnh (Nguyệt luân) tỏa ánh sáng mát lành, biểu trưng cho đức từ bi thanh lương dập tắt ngọn lửa thiêu đốt của tham lam, hận thù và phiền não nơi tâm hồn chúng sinh.","Mặt trời chiếu ban ngày, mặt trăng soi ban đêm. Truyền thống giảng rằng Bồ Tát Nhật Quang biểu thị trí tuệ phá tan tối tăm, còn Bồ Tát Nguyệt Quang biểu thị từ bi làm dịu mát khổ não. Hai đức trí và bi song hành chính là con đường mà Đức Dược Sư dạy để chữa lành cả thân bệnh lẫn tâm bệnh."],"notes":["Vị thế Thượng thủ và hình tướng y cứ Kinh Dược Sư (T450)."]},{"id":"phat-tam-ban-dau","title":"Phát tâm ban đầu","paragraphs":["Theo kinh điển ghi chép về tiền thân của Tam Thánh cõi Tịnh Lưu Ly, vào thuở quá khứ vô lượng kiếp, Ngài là người con trai thứ hai tên là Nguyệt Tịnh của vị cư sĩ giàu lòng đại bi Điện Quang Huệ (tiền thân Phật Dược Sư) và là em trai của Nhật Chiếu (tiền thân Bồ Tát Nhật Quang).","Chứng kiến cảnh chúng sinh trong cõi đời bị ngọn lửa tam độc tham, sân, si và các chứng bệnh nhiệt não, sốt cao bức bách đau đớn, người con thứ Nguyệt Tịnh đã phát khởi tâm Bồ-đề sâu xa: Nguyện con trong đời vị lai sẽ thành vị Bồ Tát mang ánh trăng thanh lương dịu mát để xoa dịu mọi vết thương đau đớn nơi thân xác và tâm hồn muôn loài, tưới mát ngọn lửa sân hận hờn oán, cùng phụ thân và huynh trưởng dẫn dắt muôn loài về cảnh giới giải thoát an vui. Tâm nguyện ấy đã viên thành quả vị Đại Bồ Tát Nguyệt Quang Biến Chiếu.","Cùng với Bồ Tát Nhật Quang Biến Chiếu, Bồ Tát Nguyệt Quang Biến Chiếu giữ địa vị Nhất Sinh Bổ Xứ đứng đầu hàng Bồ Tát tại cõi Tịnh Lưu Ly trong Kinh Dược Sư. Nếu Bồ Tát Nhật Quang biểu trưng cho ánh sáng trí tuệ phá trừ vô minh, thì Bồ Tát Nguyệt Quang biểu trưng cho ánh trăng từ bi thanh lương làm dịu phiền não; hai Ngài hợp thành đôi cánh Trí Tuệ và Từ Bi không thể thiếu trên con đường tu Bồ Tát đạo."],"notes":["Nhân duyên phát tâm ban đầu trích các bản giải nghĩa pháp môn Dược Sư cổ truyền."]},{"id":"dai-nguyen","title":"Đại nguyện","paragraphs":["Trong Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức, Bồ Tát Nguyệt Quang Biến Chiếu là bậc thượng thủ bên hữu của Đức Phật Dược Sư, cùng Bồ Tát Nhật Quang gánh vác sứ mệnh duy trì kho tàng Chánh pháp thanh tịnh nơi cõi Tịnh Lưu Ly.","Đại nguyện của Bồ Tát Nguyệt Quang Biến Chiếu là dùng ánh trăng rằm từ bi thanh lương tưới mát tâm hồn chúng sinh, dập tắt mọi bức bách nhiệt não của phiền não và tật bệnh; thề nguyện đời đời bảo hộ những người tu hành Chánh pháp, ban cho sự an ổn trong giấc ngủ, giải tỏa mọi uất hận oán thù và dẫn dắt chúng sinh đạt đến tâm thái an nhiên tịch tĩnh.","Trong Kinh Đại Bi Tâm Đà La Ni, Bồ Tát Nguyệt Quang thuyết thần chú hộ trì người tụng Chú Đại Bi, nguyện che chở họ khỏi bệnh khổ và tai nạn. Người tu học nương theo hạnh nguyện ấy bằng cách nuôi dưỡng tâm nhu hòa, nhẫn nhục và biết lắng dịu cơn sân trước khi nói năng hay hành động.","Hạnh nguyện thanh lương của Bồ Tát Nguyệt Quang còn hướng đến việc chữa lành những tổn thương tinh thần âm ỉ như oán giận, trầm uất, mất ngủ và lo âu kéo dài. Ngài nguyện dùng ánh sáng êm dịu soi vào nơi tâm tối, giúp hành giả tìm lại sự cân bằng, điềm tĩnh và lòng bao dung giữa những biến cố cuộc đời."],"notes":["Đại nguyện hướng về sự thanh lương, an định và giải tỏa nhiệt não."]},{"id":"loi-ich-niem-danh","title":"Công đức niệm danh hiệu","paragraphs":["Khi hành trì pháp môn Dược Sư hoặc lễ bái Đông Phương Tam Thánh, người học Phật thường chí thành xưng niệm danh hiệu Bồ Tát Nguyệt Quang Biến Chiếu để cầu xin sự mát mẻ, an bình cho thân tâm, xua tan những bức bối, bực dọc và nóng nảy trong cuộc sống.","Niệm danh hiệu Bồ Tát Nguyệt Quang Biến Chiếu còn là một phương pháp nuôi dưỡng tâm nhu hòa, nhẫn nhục và bao dung; giúp tâm thức hành giả lắng dịu như mặt hồ thu phẳng lặng soi bóng trăng rằm thanh tịnh.","Thực hành hạnh Nguyệt Quang trong đời sống gia đình và xã hội là tập lắng nghe sâu sắc không cắt lời, nói năng ôn tồn êm dịu khi đối phương đang nóng giận, và giữ tâm mát lành như ánh trăng thu trước những va chạm thường nhật.","Hướng dẫn xưng niệm trong ứng dụng: “Nam Mô Nguyệt Quang Biến Chiếu Bồ Tát”."],"notes":["Theo nghi thức Dược Sư truyền thống."]},{"id":"than-chu-da-la-ni","title":"Thần chú và đà-la-ni","paragraphs":["Trong Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, ngay sau phần Bồ Tát Nhật Quang, Bồ Tát Nguyệt Quang Biến Chiếu cũng đã đối trước Đức Phật phát tâm tuyên thuyết một bài thần chú đà-la-ni để ủng hộ hành giả tu trì.","Nguyên văn chữ Hán của bài chú được ghi trong bản kinh này là: 深低帝屠蘇吒。阿若蜜帝烏都吒。深耆吒。波賴帝。耶彌若吒烏都吒。拘羅帝吒耆摩吒。沙婆訶。","Bài thần chú bảo hộ của Bồ Tát Nguyệt Quang được xưng tụng theo âm Hán-Việt: “Thâm đê đế đồ tô tra, A nhược mật đế ô đô tra, Thâm kỳ tra, Ba lại đế, Da di nhược tra ô đô tra, Câu la đế tra kỳ ma tra, Sa-bà-ha”.","Công dụng của Thần chú Nguyệt Quang theo kinh điển: Ban rải ánh sáng dịu mát như ánh trăng rằm dập tắt mọi bức bách nhiệt não, ác bệnh sốt cao và oán hận nơi tâm hồn; bảo bọc hành giả trong giấc ngủ an lành không mộng mị hãi hùng, xua tan độc tố tà khí và giúp cho công phu tu tập mau chóng đạt được định tâm an tịnh.","Trong mạch văn của Kinh Đại Bi, để việc hành trì trong pháp hội Đại Bi được đúng pháp, kinh luôn nhấn mạnh hành giả cần kết hợp việc đọc chú với việc giữ tâm thanh tịnh, nuôi dưỡng tâm từ bi thương xót chúng sinh và tránh các điều ác hại người."],"notes":["Đối chiếu Kinh Đại Bi Tâm Đà La Ni (Đại Chính tạng T1060)."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Kinh Đại Bi Tâm Đà La Ni (Đại Chính tạng số 1060) ghi rằng: tiếp sau Bồ Tát Nhật Quang, Bồ Tát Nguyệt Quang cũng vì ủng hộ người thọ trì mà nói thần chú. Kinh dạy người tụng Chú Đại Bi hãy tụng thêm thần chú của Bồ Tát Nguyệt Quang năm biến, rồi lấy chỉ ngũ sắc gia trì làm dây hộ thân, buộc vào chỗ đau để cầu tiêu trừ bệnh khổ. Pháp này nhắc người bệnh và người thân giữ tâm tin tưởng, an tĩnh, đồng thời vẫn chữa trị đầy đủ theo y khoa.","Trong pháp hội Dược Sư, Bồ Tát Nguyệt Quang được tôn trí bên phải Đức Phật, biểu thị ánh trăng thanh lương làm dịu nhiệt não. Nhiều đạo tràng Bắc truyền tại Việt Nam và Đông Á tổ chức khóa lễ Dược Sư cầu an đầu năm hoặc khi trong nhà có người bệnh, đọc tụng kinh và xưng danh hiệu Đông Phương Tam Thánh. Người tham dự thường chia sẻ rằng khi tâm lắng dịu nhờ tụng niệm, giấc ngủ an hơn, lo âu giảm bớt, đó chính là ánh trăng từ bi mà Bồ Tát Nguyệt Quang biểu trưng, hiện hữu ngay trong tâm người tu tập.","Trong mỹ thuật Phật giáo Đông Á, hình tượng Bồ Tát Nguyệt Quang đứng bên phải Đức Phật Dược Sư trong bộ tượng đồng cổ thế kỷ VIII tại chùa Dược Sư (Yakushi-ji, Nara, Nhật Bản) là một minh chứng lịch sử lâu đời cho tín ngưỡng Đông Phương Tam Thánh. Qua hơn một thiên niên kỷ, các khóa lễ Dược Sư cầu an vẫn được duy trì liên tục, nhắc nhở người tu giữ lòng từ ái và sự bình tĩnh giữa nghịch cảnh."],"notes":["Dẫn Kinh Đại Bi Tâm Đà La Ni (T1060), đoạn Nguyệt Quang Bồ Tát thuyết chú và pháp chỉ ngũ sắc; truyền thống khóa lễ Dược Sư cầu an Bắc truyền."]}],"references":["Kinh Dược Sư Lưu Ly Quang Như Lai Bổn Nguyện Công Đức, Đại Chính tạng số 450 — Huyền Trang Hán dịch.","Kinh Thiên Thủ Thiên Nhãn Quán Thế Âm Bồ Tát Quảng Đại Viên Mãn Vô Ngại Đại Bi Tâm Đà La Ni, Đại Chính tạng số 1060 — đoạn Nguyệt Quang Chân Ngôn.","Kinh Dược Sư Thất Phật Bổn Nguyện Công Đức — Nghĩa Tịnh Hán dịch, Đại Chính tạng số 451.","Dược Sư Sám Pháp — nghi thức sám hối và cầu an truyền thống Phật giáo Bắc truyền."]},{"id":"thich-ca-mau-ni","name":"Đức Phật Thích Ca Mâu Ni","summary":"Đức Phật Thích Ca Mâu Ni là bậc Đạo Sư khai sáng đạo Phật, Đấng Từ Phụ Bổn Sư của muôn loài trong cõi Ta Bà. Ngài thị hiện nơi đời ác năm trược, chuyển bánh xe Chánh pháp vô thượng, khai mở con đường diệt khổ giải thoát, đưa chúng sinh quay về tự tính thanh tịnh vốn có.","sections":[{"id":"tieu-su","title":"Tiểu sử và thị hiện Bát tướng","paragraphs":["Đức Phật Thích Ca Mâu Ni là vị Phật lịch sử xuất hiện nơi cõi Ta Bà, đản sinh tại vườn Lâm-tỳ-ni (nay thuộc Nepal) vào khoảng thế kỷ thứ VI trước Công nguyên. Danh hiệu Thích Ca Mâu Ni trong tiếng Phạn là Śākyamuni, mang ý nghĩa cao quý là bậc Năng Nhân Tịch Mặc: Năng Nhân là đức từ bi vô lượng luôn cứu vớt muôn loài, Tịch Mặc là tâm trí tịch tĩnh, vắng bặt mọi phiền não si mê. Ngài vốn là Thái tử Tất-đạt-đa Cồ-đàm, con vua Tịnh Phạn và Hoàng hậu Ma-da nơi kinh thành Ca-tỳ-la-vệ hùng mạnh.","Sống trong cung vàng điện ngọc với lầu phong lưu bốn mùa cùng thê thiếp vương quyền, Thái tử khi dạo qua bốn cửa thành đã tận mắt chứng kiến cảnh già, bệnh, chết và hình bóng thanh thoát của một vị Sa-môn tu sĩ. Thấu suốt bản chất vô thường mong manh của cuộc đời, vào đêm trăng tròn, Ngài đã dũng mãnh từ bỏ ngôi báu, cùng người hầu Xa-nặc vượt dòng sông A-nô-ma xuất gia tầm đạo giải thoát cho muôn loài. Trải qua sáu năm tu khổ hạnh chốn rừng già tuyết sơn, Ngài nhận rõ việc tự hành hạ thân xác không đem lại giác ngộ và quyết định chọn con đường Trung đạo thanh tịnh.","Ngài đến dưới cội cây Bồ-đề bên dòng sông Ni-liên-thiền, trải tòa cỏ cát tường kiết già tọa thiền, lập đại thệ nguyện sâu dày: Nếu ta không chứng được đạo quả Bồ-đề vô thượng thì dù thịt nát xương tan cũng quyết không rời khỏi tòa này. Sau bốn mươi chín ngày đêm thiền định lắng sâu, chiến thắng mọi ma quân cám dỗ và đe dọa, vào lúc sao mai vừa mọc, Ngài triệt để đại ngộ, thành tựu quả vị Chánh Đẳng Chánh Giác, tôn xưng là Đức Bổn Sư Thích Ca Mâu Ni Phật.","Sau khi thành đạo, Đức Thế Tôn đến vườn Lộc Uyển chuyển bánh xe Chánh pháp đầu tiên, giảng kinh Tứ Thánh đế và Bát Chánh đạo độ cho năm anh em Kiều-trần-như, thiết lập Tăng đoàn thanh tịnh. Suốt bốn mươi chín năm hoằng hóa khắp lưu vực sông Hằng, Ngài không quản gian lao mang giáo pháp từ bi và trí tuệ bình đẳng ban rải cho khắp mọi tầng lớp xã hội. Vào năm tám mươi tuổi, sau khi trao truyền Chánh pháp nhãn tạng, Ngài an nhiên thị hiện nhập Đại Bát Niết-bàn giữa hai cây Ta-la song thọ tại rừng Câu-thi-na."],"notes":["Các mốc sự kiện trong cuộc đời Đức Thế Tôn được tôn vinh qua Bát tướng thành đạo trong truyền thống Đại thừa: Đản sinh, Xuất gia, Hàng ma, Thành đạo, Chuyển pháp luân và Nhập Niết-bàn."]},{"id":"phat-tam","title":"Phát tâm ban đầu","paragraphs":["Theo Kinh Bổn Sinh (Jātaka) và truyền thống Phật Sử, vào thuở quá khứ vô lượng kiếp, tiền thân của Đức Phật là đạo sĩ Sumedha (Thiện Huệ). Khi hay tin Đức Phật Nhiên Đăng (Dīpaṅkara) giáng trần ngự giá qua vùng sình lầy, đạo sĩ Sumedha đã chí thành trải mái tóc dài và cả thân mình trên bùn ướt làm cầu cho Đức Phật và chư Tăng bước qua. Đối trước tướng hảo quang minh của Đức Phật Nhiên Đăng, đạo sĩ phát khởi Bồ-đề tâm dõng mãnh: Nguyện con trong đời vị lai sẽ thành tựu Phật quả vô thượng như Ngài để cứu vớt muôn loài trầm luân, quyết không chứng quả A-la-hán tịch diệt một mình. Đức Phật Nhiên Đăng nhìn thấu tâm nguyện đại bi ấy liền thọ ký rằng trải qua vô lượng a-tăng-kỳ kiếp tu hành Ba-la-mật, đạo sĩ sẽ thành Phật nơi cõi Ta Bà với danh hiệu Thích Ca Mâu Ni.","Đặc biệt trong Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký, tiền thân Đức Thế Tôn là đại thần Bảo Hải, cha của Thái tử Bảo Tạng (sau thành Phật Bảo Tạng). Khi chứng kiến chư đại Bồ Tát đều phát nguyện sinh về các cõi Phật thanh tịnh trang nghiêm, đại thần Bảo Hải khởi lòng đại bi vô lượng thương xót chúng sinh cõi Ta Bà u ám nhiều điều tội ác, bèn đối trước Phật Bảo Tạng phát năm trăm lời đại nguyện rộng lớn: Nguyện đời sau nhận lấy cõi đời ác năm trược đầy dẫy phiền não, si mê để thị hiện thành Phật, cứu độ những kẻ cang cường khó giáo hóa nhất.","Tâm nguyện ban đầu ấy thể hiện trọn vẹn tinh thần Đại Bi Đại Trí của Đấng Bổn Sư: không trốn tránh cõi khổ, dấn thân vào nơi tối tăm nhất để thắp lên ngọn đèn chánh pháp. Người đệ tử Phật khi quy kính Ngài luôn noi gương tâm nguyện ấy, học cách mở rộng lòng từ bi, nuôi dưỡng hạnh nhẫn nhục và tinh tấn chuyển hóa tự tâm."],"notes":["Chuyện Sumedha thuộc truyền thống Bổn sinh và Phật Sử; đại nguyện Bảo Hải được tuyên thuyết sâu sắc trong Kinh Bi Hoa, làm nền tảng cho bản nguyện cứu độ đời ngũ trược của Đức Bổn Sư."]},{"id":"dai-nguyen","title":"Đại nguyện và công hạnh","paragraphs":["Trích lời Đức Phật nói về thệ nguyện của mình trong Kinh Diệu Pháp Liên Hoa, phẩm Phương Tiện thứ 2. Bản Việt dịch HT Thích Trí Tịnh:","Ta vốn lập thệ nguyện Muốn cho tất cả chúng Bằng như ta không khác, Như ta xưa đã nguyện Nay đã đầy đủ rồi Độ tất cả chúng sanh Đều khiến vào Phật đạo","Trong Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký, tiền thân của Đức Phật Thích Ca Mâu Ni là Bồ Tát Bảo Hải (Hải Tạng) đã đối trước Đức Phật Bảo Tạng phát 500 lời đại nguyện đại bi, nguyện nhận lấy cõi Ta Bà u ám trong thời kỳ đời ác năm trược:","“Con nguyện đời sau, khi thế giới bước vào đời ác năm trược (kiếp trược, kiến trược, phiền não trược, chúng sanh trược, mạng trược), khi chúng sinh tạo vô số điều ác nghiệp, không cha không mẹ, không kính Sa-môn Bà-la-môn, chịu muôn ngàn khổ não bức bách và bị chư Phật mười phương xả bỏ, con sẽ thị hiện thành Phật nơi cõi ấy để cứu vớt, dìu dắt và thành tựu đạo quả Bồ-đề cho họ, không bỏ rơi bất kỳ ai.”","Bốn lời thệ nguyện lớn (Tứ Hoằng Thệ Nguyện) tóm lược trọn vẹn chí nguyện thành Phật và hóa độ muôn loài của Đức Bổn Sư:","Chúng sanh vô biên thệ nguyện độ\\nPhiền não vô tận thệ nguyện đoạn\\nPháp môn vô lượng thệ nguyện học\\nPhật đạo vô thượng thệ nguyện thành."],"notes":[]},{"id":"cong-duc","title":"Công đức niệm danh hiệu","paragraphs":["Người Phật tử Việt Nam thường xưng niệm: Nam mô Bổn Sư Thích Ca Mâu Ni Phật. Nam mô mang nghĩa kính lễ và quay về nương tựa. Khi niệm danh hiệu, ta nhớ đến bậc Thầy đã chỉ đường, đồng thời tự nhắc mình sống tỉnh thức, biết thương người và chịu trách nhiệm với hành động của mình.","Kinh Tăng Chi Bộ, bài kinh Mahānāma thuộc chương Sáu pháp, dạy về việc nhớ nghĩ ân đức Như Lai. Khi tâm hướng đến những phẩm hạnh ấy, trong lúc đó tâm không bị tham, sân, si chi phối; từ sự ngay thẳng của tâm có thể phát sinh hân hoan, an tịnh và định. Đây là pháp nhớ nghĩ công đức Phật, không chỉ là phát âm danh hiệu mà thiếu sự chú tâm và thực hành.","Trong Kinh Pháp Hoa, phẩm Phương Tiện, lời xưng Nam mô Phật được nhắc đến trong văn cảnh gieo duyên với con đường thành Phật. Không nên biến lời dạy ấy thành sự bảo đảm rằng chỉ đọc một câu là mọi việc tự nhiên thành tựu. Xưng danh, đọc kinh và trì chú có cách thực hành riêng; tất cả đều cần đi cùng việc sửa đổi thân, khẩu, ý và nuôi dưỡng tâm lành.","Để việc lễ niệm Nam mô Bổn Sư Thích Ca Mâu Ni Phật đi vào chiều sâu thực hành, hành giả nên gắn mỗi lạy và mỗi câu niệm với Tam Vô Lậu Học là Giới, Định, Tuệ và con đường Bát Chánh Đạo. Nhờ giữ giới thanh tịnh, tập trung chánh niệm trong từng hơi thở và quán chiếu nhân duyên vô thường, mỗi thời khóa lễ Phật trở thành cơ hội chuyển hóa thân tâm thiết thực ngay trong đời sống hiện tại."],"notes":["Dẫn kinh Tăng Chi Bộ AN 6.10, Mahānāma; Kinh Pháp Hoa, phẩm Phương Tiện."]},{"id":"than-chu","title":"Thần chú và đà-la-ni liên quan","paragraphs":["Bên cạnh câu xưng danh quen thuộc, truyền thống Phật giáo Tây Tạng lưu truyền tâm chú Đức Phật Thích Ca trong nghi quỹ Treasury of Blessings của Mipham. Bản phiên tự được ghi là: tadyathā oṃ mune mune mahāmunaye svāhā. Người thực hành cũng gặp bản bắt đầu từ oṃ: oṃ mune mune mahāmunaye svāhā.","Câu tâm chú Đức Phật Thích Ca Mâu Ni được phiên âm tiếng Việt để hành giả thuận tiện trì tụng: “Tát-điệt-tha: Ôm, mu-ni mu-ni, ma-ha mu-na-dê xoa-ha” (Âm Hán-Việt: “Đát-điệt-tha: Án, mâu-ni, mâu-ni, ma-ha mâu-ni-dã, ta-bà-ha”).","Công dụng của Thần chú Thích Ca theo kinh điển: Khiến cho mọi xao động tán loạn và phiền não nơi thân tâm được tịch tĩnh lắng dịu, đưa tâm hành giả quay về với trạng thái giác ngộ thanh tịnh rỗng rang vốn có; tiêu trừ các nghiệp ác chướng ngăn che, nuôi dưỡng hạt giống Phật tính Bồ-đề và giúp người thực hành củng cố trọn vẹn con đường Giới - Định - Tuệ.","Danh xưng Muni gợi đến bậc hiền thánh tịch tĩnh. Trong văn cảnh nghi quỹ, câu chú gắn với lòng quy kính Đức Phật, nhớ nghĩ phẩm hạnh giác ngộ và phát tâm tu học. Câu chú không đồng nghĩa với câu xưng danh Nam mô Bổn Sư Thích Ca Mâu Ni Phật; người đọc nên nhận biết mình đang thực hành hình thức nào.","Khi trì tụng, hãy theo cách đọc được thầy hoặc truyền thống mình nương tựa hướng dẫn, không tự ghép những dị bản thành một câu mới. Việc học ý nghĩa của lời kinh, giữ giới và chăm sóc tâm từ là nền tảng để sự kính lễ trở thành công phu thiết thực."],"notes":["Phiên tự đối chiếu nghi quỹ Treasury of Blessings của Mipham trong bản dịch do Lotsawa House công bố."]},{"id":"su-tich-cam-ung","title":"Sự tích cảm ứng và linh nghiệm","paragraphs":["Sự tích hóa giải Tướng cướp Vô Não (Aṅgulimāla) được chép trong Kinh Trung Bộ (bài kinh số 86, Aṅgulimāla Sutta): Aṅgulimāla là kẻ sát nhân khét tiếng, đã giết chết chín trăm chín mươi chín người, cắt ngón tay xâu thành chuỗi đeo nơi cổ và đang lùng sục tìm kiếm nạn nhân thứ một ngàn để hoàn tất lời thề tà đạo. Khi thấy Đức Thế Tôn đơn độc đi trên con đường vắng, Aṅgulimāla tuốt gươm sáng loáng, dốc toàn lực chạy thục mạng đuổi theo nhằm sát hại Ngài. Tuy nhiên, dù y dốc hết sức bình sinh phi thân chạy cuồng loạn, Đức Phật vẫn khoan thai từng bước chậm rãi mà y không sao đuổi kịp. Quá đỗi kinh ngạc và kiệt sức, Aṅgulimāla gầm thét lớn: “Này Sa-môn, hãy dừng lại! Hãy dừng lại!”. Đức Thế Tôn ngoảnh lại, từ tốn bảo: “Này Aṅgulimāla, Ta đã dừng lại từ lâu rồi, chính ngươi mới là kẻ chưa dừng lại. Ta đã dừng việc sát hại và làm tổn thương muôn loài chúng sinh, Ta an trú trong lòng từ bi vô lượng; còn ngươi vẫn chưa dừng lại bàn tay vấy máu và tâm niệm tàn ác si mê”. Lời dạy từ bi vang rền như tiếng sấm thức tỉnh tận đáy tâm can, Aṅgulimāla bàng hoàng tỉnh ngộ, lập tức buông rơi thanh gươm đẫm máu xuống đất, sụp lạy dưới chân Phật xin sám hối xuất gia, về sau tinh tấn tu hành chứng đắc quả vị A-la-hán giải thoát.","Sự tích hàng phục Voi say Nalagiri được ghi chép trong Luật tạng Đại phẩm: Đề-bà-đạt-đa vì dã tâm muốn đoạt quyền lãnh đạo Tăng đoàn đã âm mưu mượn tay vua A-xà-thế chuốc rượu độc cho thớt voi dữ Nalagiri say cuồng, rồi thả ra ngay trên con đường hẹp mà Đức Phật và chư Tăng sắp đi khất thực vào thành Vương Xá. Con voi say lồng lộn gầm rống kinh hoàng, giẫm nát nhà cửa quán sá, vung vòi quật ngã cây cối khiến dân chúng hoảng loạn trèo lên mái nhà la khóc thảm thiết. Tôn giả A-nan hoảng hốt xông ra chắn trước Đức Thế Tôn để che chở cho Ngài, nhưng Đức Phật nhẹ nhàng bảo Tôn giả lui lại. Khi con voi điên hung hãn lao thẳng về phía Đức Phật với cặp ngà nhọn hoắt, Đức Thế Tôn liền trải rộng năng lượng Từ tâm tam muội (Mettā) bao trùm lấy con thú. Cảm nhận được nguồn năng lượng từ bi êm dịu vô bờ bến chưa từng có, con voi say lập tức dừng phắt lại, hạ vòi xuống đất, từ từ quỳ mọp cả bốn chân phục sát bên chân Đức Phật, để mặc cho Ngài âu yếm đặt bàn tay thanh tịnh xoa lên vầng trán nóng bỏng, hoàn toàn thuần phục trong sự rơi lệ tán thán của vạn dân thành Vương Xá.","Sự tích Thiền sư Khương Tăng Hội cầu Xá-lợi linh ứng tại Giao Châu và Giang Nam được ghi chép trong Lương Cao Tăng Truyện (quyển 1): Vào năm Xích Ô thứ mười (năm 247) thời Tam Quốc, Thiền sư Khương Tăng Hội từ Giao Châu (Việt Nam) sang kinh đô Kiến Nghiệp của nước Đông Ngô dựng thảo am lập tượng hành đạo. Ngô chủ Tôn Quyền thấy hình mạo dị kỳ bèn triệu Sư vào triều cật vấn về sự linh nghiệm của đạo Phật. Sư Tăng Hội dõng dạc thưa rằng: “Đức Như Lai nhập diệt đã hơn ngàn năm, nhưng xá-lợi thiêng liêng của Ngài lưu lại thế gian chiếu soi quang minh bất khả tư nghì, xưa kia vua A-dục từng dựng tám vạn bốn ngàn bảo tháp tôn thờ”. Tôn Quyền cho là hoang đường, bèn thách thức: “Nếu Sa-môn cầu được xá-lợi giáng hiện hiển linh, ta sẽ lập tức hạ chiếu xây chùa đúc tháp; nhược bằng dối trá lừa gạt, quốc pháp ắt không tha”. Sư Khương Tăng Hội bèn xin kỳ hạn hai mươi mốt ngày, cùng các đệ tử tắm gội thanh tịnh, thiết lập hương án trang nghiêm, đặt một chiếc bình đồng sạch sẽ dốc lòng quỳ lạy cầu nguyện. Qua bảy ngày rồi mười bốn ngày bình đồng vẫn trống không, Tôn Quyền nổi giận đe dọa xử trảm. Đến đêm ngày thứ hai mươi mốt, đúng vào canh năm lúc sương đêm tĩnh mịch, bỗng trong bình đồng vang lên một tiếng “keng” thanh thoát ngân dài chấn động hư không. Sư đến mở ra xem thì thấy một viên ngọc xá-lợi ngũ sắc rực rỡ, chiếu sáng lung linh cả gian phòng. Sáng hôm sau, Sư bưng bình ngọc dâng lên điện triều; Tôn Quyền đích thân cầm bình trút ra mâm đồng, hạt xá-lợi vừa chạm xuống thì chiếc mâm đồng lập tức vỡ toác. Tôn Quyền kinh ngạc, sai lực sĩ đặt xá-lợi lên đe thép rồi vung búa sắt khổng lồ giáng xuống hết sức bình sinh; kỳ diệu thay, cả đe và búa đều lún sâu nứt mẻ mà hạt xá-lợi vẫn nguyên vẹn không tì vết, lại tỏa ánh hào quang chói lọi hơn trước. Tôn Quyền kinh sợ rúng động tâm can, lập tức sụp lạy tạ tội, ban chiếu xây dựng ngôi chùa Kiến Sơ Tự cùng ngôi bảo tháp lộng lẫy để tôn thờ xá-lợi, đánh dấu mốc son Phật pháp chính thức hưng thịnh rạng ngời tại vùng Giang Nam."],"notes":["Tích Aṅgulimāla đối chiếu Kinh Trung Bộ số 86; Tích voi Nalagiri đối chiếu Luật tạng Cullavagga; Tích Khương Tăng Hội đối chiếu Lương Cao Tăng Truyện (Đại Chính Tạng tập 50, kinh số 2059)."]}],"references":["Kinh Diệu Pháp Liên Hoa, phẩm Phương Tiện thứ 2 — HT Thích Trí Tịnh Việt dịch.","Kinh Trung Bộ, số 26: Kinh Thánh Cầu (Ariyapariyesanā), Hòa thượng Thích Minh Châu dịch.","Kinh Trung Bộ, số 86: Kinh Aṅgulimāla (Aṅgulimāla Sutta), Hòa thượng Thích Minh Châu dịch.","Kinh Trường Bộ, số 16: Kinh Đại Bát Niết-bàn (Mahāparinibbāna).","Kinh Tương Ưng Bộ SN 56.11: Chuyển Pháp Luân.","Kinh Tăng Chi Bộ AN 6.10: Mahānāma.","Kinh Bi Hoa, phẩm Chư Bồ Tát Bổn Thọ Ký — bản dịch Hán tạng Đại Chính số 157.","Lương Cao Tăng Truyện, quyển 1: truyện Khương Tăng Hội — Huệ Hạo soạn, Đại Chính tạng tập 50, số 2059.","Mipham, Treasury of Blessings: nghi quỹ Đức Phật Thích Ca, bản dịch Lotsawa House."]}]`);function t(t){return e.find(e=>e.id===t)??null}export{t as getBuddhaProfile};